-- Executor capability adapter. Executors differ wildly (names, argument shapes, return shapes) and NONE has been
-- verified for ShadowScan yet. This adapter only DETECTS what exists and normalises it; if something is missing the
-- caller gets nil and must degrade safely. It never invents a capability.
local A = {}

-- genvs: ordered list of tables to search (e.g. { getgenv(), _G })
function A.detect(genvs)
	genvs = genvs or {}
	local function find(name)
		for _, g in ipairs(genvs) do
			if type(g) == "table" then
				local ok, v = pcall(function() return g[name] end)
				if ok and v ~= nil then return v end
			end
		end
		return nil
	end
	local function nested(libname, fname)
		local lib = find(libname)
		if type(lib) == "table" then
			local ok, f = pcall(function() return lib[fname] end)
			if ok and type(f) == "function" then return f end
		end
		return nil
	end
	local request = find("request") or find("http_request") or nested("syn", "request") or nested("http", "request") or nested("fluxus", "request")
	local caps = {
		request = type(request) == "function" and request or nil,
		readfile = type(find("readfile")) == "function" and find("readfile") or nil,
		writefile = type(find("writefile")) == "function" and find("writefile") or nil,
		makefolder = type(find("makefolder")) == "function" and find("makefolder") or nil,
		isfolder = type(find("isfolder")) == "function" and find("isfolder") or nil,
	}
	local clip = find("setclipboard") or find("toclipboard") or nested("Clipboard", "set")
	caps.setclipboard = type(clip) == "function" and clip or nil
	caps.toclipboard = type(find("toclipboard")) == "function" and find("toclipboard") or nil
	caps.delfile = type(find("delfile")) == "function" and find("delfile") or nil
	caps.delfolder = type(find("delfolder")) == "function" and find("delfolder") or nil
	local gethui = find("gethui") or find("get_hidden_gui")
	caps.gethui = type(gethui) == "function" and gethui or nil
	caps.http = caps.request ~= nil
	local ident = find("identifyexecutor") or find("getexecutorname")
