-- Only plain-http loopback URLs on 127.0.0.1 are ever allowed for report delivery.
function A.is_local_url(url)
	return type(url) == "string" and string.match(url, "^http://127%.0%.0%.1:%d+/[%w/_%-]*$") ~= nil
end

-- post_local -> ok, status, body_or_error
function A.http_local(caps, method, url, headers, body)
