__factories["client.compat"] = function(require)
-- Runtime compatibility layer (0.4.0): probes every optional environment capability EXPLICITLY and records a
-- status for it. Statuses: "supported" | "unsupported" | "partial" | "not_tested" | "failed_init".
-- Nothing is silently substituted: when a capability is missing, features degrade LOUDLY (UI notices + report).
-- No anti-cheat evasion, no interception, no credential access: this layer only OBSERVATES what the environment
-- offers to a normal client and files it in the capability report.
--
-- A probe NEVER throws: every check is pcall-wrapped; a probe that errors yields "failed_init" with the reason.
local util = require("client.util.util")

local C = {}

C.STATUS = { supported = "supported", unsupported = "unsupported", partial = "partial", not_tested = "not_tested", failed = "failed_init" }

-- every capability ShadowScan may use; `probe` returns ok, status, detail
local function mkprobe(name, probe)
	return { name = name, probe = probe }
end

local function flag_probe(name, present, detail_present, detail_missing)
	-- a boolean capability: either the callable/field exists or it does not
	return mkprobe(name, function(env)
		local v = present(env)
		if v then return true, C.STATUS.supported, detail_present or "available" end
		return true, C.STATUS.unsupported, detail_missing or "not available in this environment"
	end)
end

local PROBES = {
	-- core runtime: without these the loader already refused, but the report should still say so explicitly
	flag_probe("loader_run", function(env) return env.loader_ran == true end, "the pinned loader executed this bundle",
		"the bundle was not started through the pinned loader; bundle hash was not verified"),
	flag_probe("task_scheduler", function(env) return env.task ~= nil and type(env.task.wait) == "function" and type(env.task.spawn) == "function" end,
		nil, "falls back to coroutine-based scheduling"),
	-- input
	flag_probe("UserInputService", function(env) return env.user_input_service ~= nil end, nil,
		"keyboard toggles are disabled; reopen from the console (ui:show())"),
	-- GUI hosting
	flag_probe("gethui", function(env) return env.gethui ~= nil end, "dedicated GUI host container",
		"falls back to CoreGui, then PlayerGui (may be visible in player GUIs)"),
	flag_probe("CoreGui_access", function(env)
		if not env.game then return false end
		local ok, core = pcall(function() return env.game:GetService("CoreGui") end)
		return ok and core ~= nil
	end, nil, "ScreenGui parent falls back to PlayerGui"),
	flag_probe("PlayerGui", function(env)
		if not env.game then return false end
		local ok, pg = pcall(function() return env.game:GetService("Players").LocalPlayer end)
		return ok and pg ~= nil
	end, nil, "no ScreenGui parent found: the GUI cannot open here"),
	-- traversal
	flag_probe("GetChildren", function(env)
		if not env.game then return false end
		local ok, r = pcall(function() return type(env.game:GetChildren()) == "table" end)
		return ok and r
	end),
	flag_probe("GetDescendants", function(env)
		if not env.game then return false end
		local ok, r = pcall(function() return type(env.game.GetDescendants) == "function" end)
		return ok and r
	end, nil, "the scanner uses its own traversal (GetChildren walk); behaviour is identical"),
	flag_probe("GetAttributes", function(env)
		if not env.game then return false end
		local ok, r = pcall(function() return type(env.game.GetAttributes) == "function" end)
		return ok and r
	end, nil, "attribute inspection is skipped"),
	flag_probe("ChildAdded_signal", function(env)
		if not env.game then return false end
		local ok, r = pcall(function() return env.game.ChildAdded ~= nil end)
		return ok and r
	end),
	flag_probe("ChildRemoved_signal", function(env)
		if not env.game then return false end
		local ok, r = pcall(function() return env.game.ChildRemoved ~= nil end)
		return ok and r
	end),
	flag_probe("DescendantAdded_signal", function(env)
		if not env.game then return false end
		local ok, r = pcall(function() return env.game.DescendantAdded ~= nil end)
		return ok and r
	end, nil, "live observation is unavailable (passive scan still works)"),
	-- executor-supplied optional functions (NOT standard Roblox APIs; detected, never assumed)
	flag_probe("http_request", function(env) return env.caps and env.caps.request ~= nil end, nil,
		"the local companion cannot be reached; use export_unencrypted + encrypt-file"),
	flag_probe("readfile", function(env) return env.caps and env.caps.readfile ~= nil end, nil,
		"manifest loading and snapshot comparison by path are unavailable"),
	flag_probe("writefile", function(env) return env.caps and env.caps.writefile ~= nil end, nil,
		"encrypted TXT export and snapshots cannot be written"),
	flag_probe("makefolder", function(env) return env.caps and env.caps.makefolder ~= nil end, nil,
		"the ShadowScan/out folder must already exist for exports"),
	flag_probe("setclipboard", function(env) return env.caps and (env.caps.setclipboard ~= nil or env.caps.toclipboard ~= nil) end, nil,
		"copy actions fall back to Export Encrypted TXT"),
	flag_probe("delfile", function(env) return env.caps and env.caps.delfile ~= nil end, nil,
		"deleting old snapshots is unavailable; overwrite them instead"),
	flag_probe("identifyexecutor", function(env) return env.caps and env.caps.executor_name ~= nil and env.caps.executor_name ~= "unknown" end,
		nil, "executor identity unknown (does not affect auditing)"),
	-- os/time
	flag_probe("os_time", function(env) return type(os) == "table" and type(os.time) == "function" end,
		nil, "manifest expiry checks degrade without os.time"),
}

-- probe(env) -> report
-- env = { game, caps, user_input_service, task, gethui, loadstring, probe_errors = {} (optional sink) }
function C.probe(env)
	env = env or {}
	local items, counts = {}, { supported = 0, unsupported = 0, partial = 0, not_tested = 0, failed_init = 0 }
	for _, p in ipairs(PROBES) do
		local ok, status, detail = false, C.STATUS.failed, nil
		if type(p.probe) == "function" then
			local pok, r1, r2, r3 = pcall(p.probe, env)
			if pok and r1 == true then
				ok, status, detail = true, r2 or C.STATUS.supported, r3 or r2 or "available"
			elseif pok and r1 == false then
				ok, status, detail = true, r2 or C.STATUS.unsupported, r3 or "not available"
			else
				-- the probe itself errored OR returned a failure: record it, never crash
				status, detail = C.STATUS.failed, util.clean_text(tostring(pok == false and r1 or "probe error"), 200)
			end
		end
		counts[status] = (counts[status] or 0) + 1
		items[#items + 1] = { capability = p.name, status = status, detail = util.clean_text(tostring(detail), 200) }
	end
	return { capabilities = items, counts = counts, probed_at = env.now_iso or nil }
end

-- human one-liner for the console / logs
function C.summarize(report)
	local c = report.counts
	return string.format("compatibility: %d supported, %d unsupported, %d failed (details: ss:capability_report())",
		c.supported or 0, c.unsupported or 0, c.failed_init or 0)
end

-- rows for the GUI (Settings/About page): sorted by status severity then name
function C.gui_rows(report)
	local order = { failed_init = 1, unsupported = 2, partial = 3, supported = 4, not_tested = 5 }
	local rows = {}
	for _, it in ipairs(report.capabilities or {}) do
		rows[#rows + 1] = { id = it.capability, cap = it,
			cells = { capability = it.capability, status = it.status, detail = it.detail } }
	end
	table.sort(rows, function(a, b)
		local oa, ob = order[a.cap.status] or 9, order[b.cap.status] or 9
		if oa ~= ob then return oa < ob end
		return a.cap.capability < b.cap.capability
	end)
	return rows
end

return C
end
__factories["client.main"] = function(require)
-- ShadowScan session object (the "API" a tester drives from the executor console).
-- One Main.new() == one tester session. All state lives on the object; nothing is kept at module level, so two audits
-- (or two sessions) can never leak results into each other.
local json = require("client.util.json")
local util = require("client.util.util")
local compat = require("client.compat")
local profiles = require("client.profiles")
local secrets = require("client.util.secrets")
local Adapter = require("client.adapter")
local sha256 = require("client.util.sha256")
local inventory = require("scanner.inventory")
local analyzer = require("scanner.analyzer")
local live_mod = require("scanner.live")
local graph_mod = require("scanner.graph")
local runner = require("scanner.active_runner")
local validator = require("test_manifest.validator")
local report_builder = require("reporting.report_builder")
local version_info = require("client.version")

local Main = {}
Main.__index = Main

Main.EXPORT_ACK = "I UNDERSTAND THIS REPORT IS NOT ENCRYPTED"
Main.DEFAULT_CONFIG = {
	audit_mode = "passive",
	minimize = true,             -- data minimisation (default ON)
	anonymize_tester = true,
	tester_label = "tester",
	include_job_id = false,
	scan_roots = { "ReplicatedStorage", "Workspace", "ReplicatedFirst" },
	max_objects = 100000,
	profile = "balanced",        -- performance profile: low_impact | balanced | fast (see client/profiles.lua)
	batch_budget_ms = nil,       -- optional explicit override of the profile's batch budget
	allowed_place_ids = nil,     -- optional: refuse to run anywhere else (even passive)
	companion_port = 47821,
	live_max_events = 500,       -- buffer size for passive live observation
}

local function index_findings(audit)
	local by = {}
	for _, f in ipairs(audit.findings or {}) do by[f.object_path] = f end
	audit.findings_by_path = by
end

local function merge(defaults, over)
	local out = {}
	for k, v in pairs(defaults) do out[k] = v end
	for k, v in pairs(over or {}) do out[k] = v end
	return out
end

function Main.new(opts)
	opts = opts or {}
	local self = setmetatable({}, Main)
	local G = opts.globals or _G
	local d = opts.deps or {}
	self.config = merge(Main.DEFAULT_CONFIG, opts.config)
	self.loader_info = opts.loader_info or {}
	self.deps = {
		print = d.print or print,
		game = d.game or (type(G) == "table" and rawget(G, "game")) or (rawget(_G, "game")),
		wait = d.wait or function(s) if task and task.wait then return task.wait(s) end end,
		clock = d.clock or os.clock,
		time = d.time or os.time,
		spawn = d.spawn or function(f) if task and task.spawn then return task.spawn(f) end return coroutine.wrap(f)() end,
		rand = d.rand or math.random,
	}
	self.caps = d.caps or Adapter.detect({ G, _G })
	self.audit = nil
	self.plan = nil
	self.manifest = nil
	self.last_report = nil
	self.last_report_json = nil
	self.last_cipher = nil
	self.last_manifest_draft = nil
	self.snapshot_diff = nil
	self.listener = nil
	self.live = nil
	-- 0.4.0: explicit runtime capability probe (statuses: supported/unsupported/partial/not_tested/failed_init)
	local uis = nil
	if self.deps.game then
		local ok, svc = pcall(function() return self.deps.game:GetService("UserInputService") end)
		if ok then uis = svc end
	end
	local task_lib = rawget(G, "task")
	if type(task_lib) ~= "table" and type(task) == "table" then task_lib = task end
	self.compat = compat.probe({
		game = self.deps.game, caps = self.caps, user_input_service = uis, task = task_lib,
		gethui = self.caps.gethui, loader_ran = self.loader_info ~= nil,
		now_iso = function() return self:_now_iso() end,
	})
	self:_say(compat.summarize(self.compat))
	self:_announce()
	return self
end

-- the full capability report (also mirrored into reports under environment.compatibility)
function Main:capability_report()
	return self.compat
end

-- ---------------------------------------------------------------- helpers
function Main:set_listener(fn) self.listener = fn end

function Main:_say(msg, level)
	self.deps.print("[ShadowScan] " .. msg)
	if self.listener then
		local lvl = level
		if not lvl then
			if string.find(msg, "FAILED", 1, true) or string.find(msg, "NOT SAVED", 1, true) or string.find(msg, "INVALID", 1, true) then lvl = "error"
			elseif string.find(msg, "BLOCKED", 1, true) or string.find(msg, "REFUSED", 1, true) or string.find(msg, "CANCELLED", 1, true) then lvl = "warn"
			else lvl = "info" end
		end
		pcall(self.listener, lvl, msg)
	end
end
function Main:_now_iso() return util.unix_to_iso(self.deps.time()) end

function Main:_read_target()
	local t = {}
	local g = self.deps.game
	if g then
		for field, prop in pairs({ game_id = "GameId", place_id = "PlaceId", job_id = "JobId", private_server_id = "PrivateServerId" }) do
			pcall(function() t[field] = g[prop] end)
		end
	end
	return t
end

function Main:_announce()
	local t = self:_read_target()
	self:_say(string.format("SHADOWSCAN INITIALIZED  v%s build %s  |  PlaceId=%s  |  mode=%s",
		version_info.version, version_info.build_id, tostring(t.place_id or "n/a"), self.config.audit_mode))
	if self.loader_info.bundle_sha256 then
		self:_say("integrity: bundle sha256 verified by loader (" .. string.sub(self.loader_info.bundle_sha256, 1, 12) .. "...)")
	else
		self:_say("integrity: NOT loaded through the pinned loader; bundle hash was not verified")
	end
	self:_say(Adapter.describe(self.caps))
	if not self.config.allowed_place_ids then
		self:_say("note: config.allowed_place_ids is not set; passive scanning will run on any place. Active tests always need an approved manifest.")
	end
end

function Main:_new_audit()
	self.audit = {
		audit_id = util.rand_hex(16, self.deps.rand), started_utc = self:_now_iso(), mode = "passive",
		errors = {}, test_runs = {}, findings = {}, scan = nil, blocked = false, target_check = "not_run", manifest_info = nil,
	}
	self.snapshot_diff = nil
	self.last_report, self.last_report_json = nil, nil
end

function Main:_ensure_audit() if not self.audit then self:_new_audit() end end

function Main:_error(code, message)
	self:_ensure_audit()
	table.insert(self.audit.errors, { code = code, message = util.clean_text(message, 300) })
end

function Main:_resolve(path)
	local g = self.deps.game
	if not g then return nil end
	local cur
	for seg in string.gmatch(path .. ".", "([^%.]*)%.") do
		if not cur then
			local ok, svc = pcall(function() return g:GetService(seg) end)
			if not ok or not svc then return nil end
			cur = svc
		elseif seg == "@LocalPlayer" then
			local ok, lp = pcall(function() return cur.LocalPlayer end)
			if not ok or not lp then return nil end
			cur = lp
		else
			local ok, child = pcall(function() return cur:FindFirstChild(seg) end)
			if not ok or not child then return nil end
			cur = child
		end
	end
	return cur
end

-- ---------------------------------------------------------------- target check
function Main:target_check()
	local t = self:_read_target()
	local allowed = self.config.allowed_place_ids
	local ok, why = true, nil
	if allowed then
		ok = false
		for _, p in ipairs(allowed) do if p == t.place_id then ok = true end end
		if not ok then why = "PlaceId " .. tostring(t.place_id) .. " is not in config.allowed_place_ids" end
	end
	self:_ensure_audit()
	self.audit.target_check = ok and "passed" or "failed"
	if ok then
		self:_say("TARGET CHECK PASSED" .. (allowed and "" or " (no place allowlist configured)"))
	else
		self:_say("TARGET CHECK FAILED: " .. why)
	end
	return ok, why
end

-- ---------------------------------------------------------------- passive reconnaissance
-- opts: { should_cancel = fn()->bool, on_progress = fn(visited), progress_every = n }
-- returns ok, state ("complete" | "cancelled" | "refused")
function Main:passive_scan(opts)
	opts = opts or {}
	local ok = self:target_check()
	if not ok then
		self:_say("Passive scan refused. Fix config.allowed_place_ids or run in the authorised place.")
		return false, "refused"
	end
	local prev = self.audit
	self:_new_audit() -- a new scan is a NEW audit; earlier results are discarded, never merged
	if prev and prev.scan then self:_say("note: previous audit results were discarded (save them first next time)") end
	self.audit.target_check = "passed"
	self:_say("PASSIVE INVENTORY STARTED")

	local roots = {}
	for _, name in ipairs(self.config.scan_roots) do
		local okr, inst = pcall(function() return self.deps.game:GetService(name) end)
		if okr and inst then roots[#roots + 1] = { name = name, inst = inst }
		else self:_error("root_unavailable", "service " .. name .. " could not be read") end
	end
	local players
	pcall(function() players = self.deps.game:GetService("Players") end)
	local profile, prof_cfg = profiles.apply(self.config.profile, { batch_budget_ms = self.config.batch_budget_ms })
	self.audit.profile = profile.key
	local res = inventory.scan({
		roots = roots, players = players, now_iso = function() return self:_now_iso() end,
		yield = function() self.deps.wait() end, clock = os.clock,
	}, { max_objects = self.config.max_objects, should_cancel = opts.should_cancel, progress_every = opts.progress_every or prof_cfg.progress_every,
		batch_budget_ms = prof_cfg.batch_budget_ms, batch_min = prof_cfg.batch_min, batch_max = prof_cfg.batch_max },
		function(n)
			self:_say("  progress: " .. n .. " objects visited")
			if opts.on_progress then opts.on_progress(n) end
		end)

	self.audit.scan = res
	self.audit.findings = analyzer.analyze(res.observations)
	index_findings(self.audit)
	if res.stats.cancelled then
		self:_say(string.format("PASSIVE INVENTORY CANCELLED after %d objects; results are partial", res.stats.visited))
	else
		self:_say(string.format("PASSIVE INVENTORY DONE: %d objects visited, %d observed", res.stats.visited, #res.observations))
	end
	self:_say(string.format("CANDIDATES GENERATED: %d (candidates are NOT confirmed vulnerabilities)", #self.audit.findings))
	return true, res.stats.cancelled and "cancelled" or "complete"
end

-- ---------------------------------------------------------------- manifest / active tests
function Main:load_manifest_string(text)
	local m, err = json.decode(text)
	if not m then
		self:_say("MANIFEST INVALID: " .. tostring(err))
		return false, { tostring(err) }
	end
	local plan, errs = runner.new_plan(m, { target = self:_read_target(), now_unix = self.deps.time() })
	if not plan then
		self:_say("MANIFEST INVALID (" .. #errs .. " problem(s)); first ones:")
		for i = 1, math.min(10, #errs) do self:_say("  - " .. errs[i]) end
		self.plan, self.manifest = nil, nil
		return false, errs
	end
	self.plan, self.manifest = plan, m
	self:_say(string.format("APPROVED TEST PLAN LOADED: %s v%s, %d test case(s), mode=%s", plan.manifest_id, plan.manifest_version, #plan.tests, plan.mode))
	if not plan.gate.ok then self:_say("TARGET CHECK FAILED for this manifest: " .. table.concat(plan.gate.reasons, "; ")) end
	return true
end

function Main:load_manifest_file(path)
	local ok, data = Adapter.read_file(self.caps, path)
	if not ok then
		self:_say("MANIFEST NOT LOADED: " .. tostring(data))
		return false, { tostring(data) }
	end
	return self:load_manifest_string(data)
end

function Main:preview_manifest()
	if not self.plan then
		self:_say("No approved test plan is loaded. Use load_manifest_file() / load_manifest_string().")
		return nil
	end
	local lines = runner.preview_lines(self.plan)
	for _, l in ipairs(lines) do self:_say(l) end
	return lines
end

-- opts: { dry_run = bool, confirm = "APPROVE <id> <hash8>", reset_confirmed = bool }
function Main:active_run(opts)
	opts = opts or {}
	if not self.manifest then
		self:_say("ACTIVE TEST BLOCKED: no approved test plan loaded")
		return nil
	end
	self:_ensure_audit()
	local plan, errs = runner.new_plan(self.manifest, { target = self:_read_target(), now_unix = self.deps.time() })
	if not plan then
		self:_say("ACTIVE TEST BLOCKED: manifest no longer valid (" .. tostring(errs[1]) .. ")")
		self.audit.blocked = true
		return nil
	end
	self.plan = plan
	local env = {
		resolve = function(p) return self:_resolve(p) end,
		wait = self.deps.wait, clock = self.deps.clock, spawn = self.deps.spawn,
	}
	local result = runner.execute(plan, env, opts)
	self.audit.test_runs = result.test_runs
	self.audit.manifest_info = { manifest_id = plan.manifest_id, version = plan.manifest_version, sha256 = plan.manifest_sha256, plan_hash = plan.plan_hash }
	self.audit.target_check = plan.gate.ok and "passed" or "failed"
	runner.attach_to_findings(self.audit.findings, result.test_runs)

	if result.status == "blocked" then
		self.audit.blocked = true
		self.audit.mode = (self.audit.mode == "passive") and "active" or self.audit.mode
		self:_say("ACTIVE TEST BLOCKED: " .. tostring(result.reason))
		if result.reason == "confirmation gate not met" then
			self:_say("Review preview_manifest(), then pass confirm = \"" .. plan.required_confirmation .. "\"")
		end
	elseif result.status == "dry_run" then
		if self.audit.mode == "passive" then self.audit.mode = "active_dry_run" end
		self.audit.blocked = false
		self:_say(string.format("DRY RUN ONLY: %d test case(s) planned; NOTHING was sent", result.counts.planned))
		for _, l in ipairs(runner.preview_lines(plan)) do self:_say(l) end
	else
		self.audit.mode = "active"
		self.audit.blocked = false
		local c = result.counts
		self:_say(string.format("ACTIVE TEST COMPLETE: %d executed, %d skipped, %d blocked, %d failed (%d call(s) sent)",
			c.executed, c.skipped, c.blocked, c.failed, result.total_calls or 0))
		if result.reason then self:_say("stopped early: " .. result.reason) end
	end
	return result
end

-- ---------------------------------------------------------------- reporting
function Main:build_report()
	if not self.audit then
		self:_say("Nothing to report yet. Run passive_scan() first.")
		return nil
	end
	local a = self.audit
	a.finished_utc = self:_now_iso()
	local t = self:_read_target()
	t.target_mode = self.plan and self.plan.mode or "unspecified"
	t.target_check = a.target_check
	local state = {
		audit_id = a.audit_id, started_utc = a.started_utc, finished_utc = a.finished_utc, mode = a.mode,
		minimize = self.config.minimize, anonymize = self.config.anonymize_tester, tester_label = self.config.tester_label,
		include_job_id = self.config.include_job_id, tool = { version = version_info.version, build_id = version_info.build_id, bundle_sha256 = self.loader_info.bundle_sha256 },
		target = t, caps = self.caps, scan = a.scan, findings = a.findings, test_runs = a.test_runs, manifest_info = a.manifest_info,
		errors = a.errors, blocked = a.blocked, counts = runner.counts(a.test_runs),
		snapshot_diff = self.snapshot_diff,
		compat = self.compat,
		profile = self.audit and self.audit.profile or self.config.profile,
	}
	local ok, report = pcall(report_builder.build, state)
	if not ok then
		self:_error("report_build_failed", tostring(report))
		self:_say("REPORT BUILD FAILED: " .. tostring(report))
		return nil
	end
	local okj, text = pcall(report_builder.to_json, report)
	if not okj then
		self:_say("REPORT ENCODING FAILED: " .. tostring(text))
		return nil
	end
	self.last_report, self.last_report_json = report, text
	return report
end

-- Non-sensitive statistics only (counts). Safe to show or paste.
function Main:summary()
	local a = self.audit
	if not a then return { audit = "none" } end
	local fs = analyzer.summarize(a.findings)
	local out = {
		audit_id = a.audit_id, mode = a.mode,
		objects_visited = a.scan and a.scan.stats.visited or 0,
		objects_observed = a.scan and #a.scan.observations or 0,
		candidates_total = fs.total, candidates_by_severity = fs.by_severity,
		tests = runner.counts(a.test_runs),
	}
	self:_say(string.format("SUMMARY: %d observed, %d candidates (high=%d medium=%d low=%d info=%d), tests executed=%d",
		out.objects_observed, fs.total, fs.by_severity.high, fs.by_severity.medium, fs.by_severity.low, fs.by_severity.informational, out.tests.executed))
	return out
end

local STATUS_TEXT = {
	[401] = "the pairing token was rejected or expired. Restart the companion to get a fresh one-time token.",
	[403] = "the companion refused the request (host/origin check).",
	[409] = "the companion refused a replay (token already used or audit already stored).",
	[413] = "the report is larger than the companion's payload limit.",
	[415] = "the companion expected application/json.",
	[422] = "the companion rejected the report (schema validation, or a secret was detected). Nothing was stored.",
	[500] = "the companion could not encrypt the report. Nothing was stored (there is NO plaintext fallback).",
}

-- opts: { token = "ssp_...", port = 47821 }
function Main:save_encrypted(opts)
	opts = opts or {}
	local function fail(code, msg)
		self:_say("REPORT NOT SAVED: " .. msg)
		self:_say("Safe next steps: start the companion (python shadowscan.py companion), or use export_unencrypted() + 'python shadowscan.py encrypt-file' offline.")
		return false, code
	end
	if not self.last_report_json then
		if not self:build_report() then return fail("no_report", "no report could be built") end
	end
	if not self.caps.request then return fail("no_http", "this executor exposes no HTTP function, so the local companion cannot be reached") end
	local token = opts.token
	if type(token) ~= "string" or not string.match(token, "^ssp_[%w_%-]+$") then
		return fail("bad_token", "pass the one-time pairing token printed by the companion (starts with ssp_)")
	end
	local port = opts.port or self.config.companion_port
	local url = string.format("http://127.0.0.1:%d/v1/report", port)
	local headers = { ["Content-Type"] = "application/json", ["X-ShadowScan-Token"] = token }
	if opts.return_ciphertext then headers["X-ShadowScan-Return"] = "ciphertext" end
	local ok, status, body = Adapter.http_local(self.caps, "POST", url, headers, self.last_report_json)
	token = nil
	if not ok then return fail("http_error", tostring(body)) end
	if status ~= 201 then return fail("http_" .. tostring(status), STATUS_TEXT[status] or ("companion answered HTTP " .. tostring(status))) end
	local resp = json.decode(body)
	local nfiles = type(resp) == "table" and type(resp.files) == "table" and #resp.files or 0
	if opts.return_ciphertext then
		local armored = type(resp) == "table" and resp.ciphertext_armored
		if type(armored) ~= "string" or sha256.hex(armored) ~= resp.ciphertext_sha256 then
			return fail("cipher_mismatch", "the companion's ciphertext did not match its own SHA-256; it was discarded (the encrypted files on disk are unaffected)")
		end
		-- Spec export name: ShadowScan_Audit_YYYYMMDD_HHMMSS.txt (UTC), the file is age-ARMORED CIPHERTEXT.
		self.last_cipher = { armored = armored, sha256 = resp.ciphertext_sha256, bytes = #armored, created_at = self.deps.time(),
			file_name = string.format("ShadowScan_Audit_%s.txt", util.audit_stamp(self.deps.time())) }
	end
	self:_say("REPORT ENCRYPTED")
	self:_say(string.format("REPORT SAVED by the companion (%d encrypted file(s))", nfiles))
	return true, "saved"
end

-- GET /v1/health on the loopback companion. returns ok, info|message
function Main:companion_status(port)
	if not self.caps.request then return false, "no_http", "This executor exposes no HTTP function." end
	local url = string.format("http://127.0.0.1:%d/v1/health", port or self.config.companion_port)
	local ok, status, body = Adapter.http_local(self.caps, "GET", url, {}, nil)
	if not ok then return false, "unreachable", tostring(body) end
	if status ~= 200 then return false, "unreachable", "companion answered HTTP " .. tostring(status) end
	local info = json.decode(body)
	if type(info) ~= "table" or info.service ~= "shadowscan-companion" then return false, "unreachable", "something else is listening on that port" end
	return true, "reachable", info
end

-- Writes the ARMORED CIPHERTEXT (never plaintext) received from the companion, plus a .sha256 sidecar.
-- returns ok, path|message
function Main:export_ciphertext_txt()
	local c = self.last_cipher
	if not c then return false, "There is no ciphertext yet. Encrypt with the companion first." end
	local path = "ShadowScan/out/" .. c.file_name
	local ok, err = Adapter.write_file(self.caps, path, c.armored)
	if not ok then return false, tostring(err) end
	-- Sidecar: "<sha256>  <file name>" so the receiver can check integrity before opening it.
	-- It proves the bytes match the hash; it does NOT prove who sent the file.
	local sidecar_ok = Adapter.write_file(self.caps, path .. ".sha256", string.format("%s  %s\n", c.sha256, c.file_name))
	self:_say("ENCRYPTED TXT EXPORTED -> " .. path .. (sidecar_ok and " (+ .sha256 sidecar)" or " (sidecar could not be written)"))
	return true, path
end

-- Writes report METADATA only (file name, SHA-256, size, audit id, tool version) -- never report content.
-- returns ok, path|message
function Main:export_report_metadata()
	local c = self.last_cipher
	if not c then return false, "There is no ciphertext yet. Encrypt with the companion first." end
	local meta = {
		format = "shadowscan-export-metadata/1",
		file_name = c.file_name, sha256 = c.sha256, bytes = c.bytes,
		exported_utc = self:_now_iso(), audit_id = self.audit and self.audit.audit_id or nil,
		tool = { name = "ShadowScan", version = version_info.version, build_id = version_info.build_id },
		note = "Metadata only. The .txt beside it is age-armored ciphertext; the SHA-256 matches only these bytes and does not prove the sender's identity.",
	}
	local json_ok, text = pcall(json.encode, meta)
	if not json_ok then return false, "could not encode metadata" end
	local path = "ShadowScan/out/" .. c.file_name .. ".metadata.json"
	local ok, err = Adapter.write_file(self.caps, path, text)
	if not ok then return false, tostring(err) end
	self:_say("REPORT METADATA EXPORTED -> " .. path)
	return true, path
end

function Main:copy(text) return Adapter.set_clipboard(self.caps, text) end

-- Opens the GUI (client/ui). Lazy so a headless session never loads it. returns the app object.
function Main:open_ui(opts)
	local App = require("client.ui.app")
	self.ui = App.open(self, opts)
	return self.ui
end

-- facts for the GUI (no secrets)
function Main:ui_info()
	local t = self:_read_target()
	local caps = self.caps
	return {
		version = version_info.version, build_id = version_info.build_id, integrity = self.loader_info.bundle_sha256 and "verified" or "unverified",
		bundle_sha = self.loader_info.bundle_sha256, executor = caps.executor_name or "unknown",
		mode = self.audit and self.audit.mode or self.config.audit_mode, place_id = t.place_id, game_id = t.game_id,
		caps = { http = caps.request ~= nil, readfile = caps.readfile ~= nil, writefile = caps.writefile ~= nil, clipboard = caps.setclipboard ~= nil,
			gui_host = caps.gethui and "gethui" or "CoreGui / PlayerGui (fallback)" },
		config = { minimize = self.config.minimize, anonymize = self.config.anonymize_tester },
		live = self:live_info(),
		snapshot_diff = self.snapshot_diff and { added = self.snapshot_diff.added_count, removed = self.snapshot_diff.removed_count } or nil,
		compat = self.compat and self.compat.counts or nil,
		compat_items = self.compat and (function()
			local out = {}
			for _, it in ipairs(self.compat.capabilities or {}) do
				if it.status ~= "supported" and #out < 12 then out[#out + 1] = it end
			end
			return out
		end)() or {},
		profile = self.config.profile,
		profile_label = profiles.get(self.config.profile).label,
	}
end

-- switch the performance profile at runtime (Settings page). Unknown keys fall back to balanced.
function Main:set_profile(key)
	if not profiles.PROFILES[key] then return false end
	self.config.profile = key
	self:_say("PERFORMANCE PROFILE: " .. profiles.get(key).label .. " (" .. profiles.get(key).description .. ")")
	return true
end

-- plain-language summary of the loaded manifest for the GUI
function Main:manifest_summary()
	local m, plan = self.manifest, self.plan
	if not m or not plan then return nil end
	local mt, id, lim = m.target, m.manifest, m.limits
	local qa = mt.qa or {}
	local server_check = "none (production observation)"
	if mt.mode == "private_qa" then
		local parts = {}
		if qa.require_private_server then parts[#parts + 1] = "private server required" end
		if qa.allowed_job_ids then parts[#parts + 1] = #qa.allowed_job_ids .. " allowed JobId(s)" end
		server_check = table.concat(parts, ", ")
	end
	local exp = util.iso_to_unix(id.expires_utc)
	local rows, calls, endpoints, seen, mutating = {}, 0, 0, {}, false
	for i, t in ipairs(plan.tests) do
		rows[i] = { id = t.test_id, endpoint = (string.gsub(t.path, "^ReplicatedStorage%.", "")), type = t.test_type, calls = t.max_calls, mutates = t.mutates_state, expected = t.expected_outcome, result = "" }
		calls += t.max_calls
		if t.mutates_state then mutating = true end
		if not seen[t.path] then seen[t.path] = true; endpoints += 1 end
	end
	return {
		summary = {
			manifest_id = id.manifest_id, version = id.version, approved_by = id.approved_by, approval_reference = id.approval_reference, mode = mt.mode,
			scope = string.format("GameId %d, %d place(s)", mt.game_id, #mt.place_ids), server_check = server_check,
			expires_text = string.format("%s (%s)", id.expires_utc, require("client.ui.viewmodel").until_text(exp, self.deps.time())),
			limits_text = string.format("%d calls, >=%ss apart, <=%ss", lim.max_total_calls, tostring(lim.min_interval_seconds), tostring(lim.max_duration_seconds)),
			test_count = #plan.tests,
		},
		tests = rows, gate_reasons = plan.gate.reasons,
		plan = { phrase = plan.required_confirmation, calls = calls, endpoints = endpoints, mode = mt.mode, mutating = mutating, reset_instructions = qa.reset and qa.reset.instructions or nil },
	}
end

-- Explicit, loud, opt-in. Writes PLAINTEXT. Prefer save_encrypted().
function Main:export_unencrypted(opts)
	opts = opts or {}
	if opts.acknowledge ~= Main.EXPORT_ACK then
		self:_say("EXPORT REFUSED: this writes the report WITHOUT encryption. Pass acknowledge = \"" .. Main.EXPORT_ACK .. "\" to proceed.")
		return false, "not_acknowledged"
	end
	if not self.last_report_json and not self:build_report() then return false, "no_report" end
	local path = string.format("ShadowScan/out/%s.UNENCRYPTED.json", self.audit.audit_id)
	local ok, err = Adapter.write_file(self.caps, path, self.last_report_json)
	if not ok then
		self:_say("EXPORT FAILED: " .. tostring(err) .. ". Nothing was saved.")
		return false, "write_failed"
	end
	self:_say("REPORT EXPORTED WITHOUT ENCRYPTION -> " .. path)
	self:_say("Encrypt it now: python shadowscan.py encrypt-file --in <that file> --delete-source")
	return true, path
end

-- ---------------------------------------------------------------- passive live observation (0.3.0)
-- Event-driven: the watcher buffers objects that replicate while the session is open. Nothing is sent anywhere.
function Main:start_live()
	if not self.audit or not self.audit.scan then
		self:_say("LIVE OBSERVATION NOT STARTED: run passive_scan() first (live events extend the current audit)")
		return false
	end
	if self.live and self.live.running then return true end
	if not self.live then
		local players
		pcall(function() players = self.deps.game:GetService("Players") end)
		self.live = live_mod.new({ game = self.deps.game, players = players }, { max_events = self.config.live_max_events })
	end
	local ok = self.live.start()
	if ok then
		self:_say("LIVE OBSERVATION STARTED: newly replicated objects of interest are recorded into the current audit (nothing is sent)")
	else
		self:_say("LIVE OBSERVATION UNAVAILABLE: this environment does not expose DescendantAdded; the passive scan still works")
	end
	return ok
end

function Main:stop_live()
	if self.live and self.live.running then
		self.live.stop()
		self:_say("LIVE OBSERVATION STOPPED")
	end
end

-- Folds buffered live events into the current audit and re-derives candidates. Returns the number folded.
function Main:drain_live()
	if not (self.live and self.audit and self.audit.scan) then return 0 end
	local events = self.live.drain()
	if #events == 0 then return 0 end
	local counter = { n = #self.audit.scan.observations + 1 }
	local added = live_mod.merge(self.audit.scan, events, function() return self:_now_iso() end, counter)
	if #added > 0 then
		self.audit.findings = analyzer.analyze(self.audit.scan.observations)
		index_findings(self.audit)
		self:_say(string.format("LIVE OBSERVATION: +%d object(s) recorded; candidates re-derived (%d total)", #added, #self.audit.findings))
	end
	return #added
end

function Main:live_info()
	if not self.live then return { supported = nil, running = false, recorded = 0 } end
	return { supported = self.live.supported, running = self.live.running, stats = self.live.stats }
end

-- ---------------------------------------------------------------- audit snapshots (0.3.0, extended in 0.4.0)
-- A snapshot is a compact, comparable fingerprint of the remote surface: class/name/path plus a metadata summary
-- and the functional family per remote (v2). It contains nothing but structure - no values, no secrets.
function Main:snapshot()
	local a = self.audit
	if not a or not a.scan then return nil, "no audit to snapshot; run passive_scan() first" end
	local remotes, counts = {}, {}
	for _, o in ipairs(a.scan.observations) do
		counts[o.class_name] = (counts[o.class_name] or 0) + 1
		if o.class_name == "RemoteEvent" or o.class_name == "RemoteFunction" or o.class_name == "UnreliableRemoteEvent" then
			-- compact metadata fingerprint: sorted "Key=value" pairs (values are already redacted summaries)
			local mparts = {}
			for _, k in ipairs(util.sorted_keys(o.metadata or {})) do
				local v = o.metadata[k]
				if type(v) == "string" or type(v) == "number" or type(v) == "boolean" then
					mparts[#mparts + 1] = k .. "=" .. tostring(v)
				end
			end
			local family = ""
			local findings_by_path = a.findings_by_path
			if findings_by_path and findings_by_path[o.path] and findings_by_path[o.path].classification then
				family = findings_by_path[o.path].classification.family
			end
			remotes[#remotes + 1] = { c = o.class_name, n = o.name, p = o.path, m = table.concat(mparts, "|"), f = family }
		end
	end
	table.sort(remotes, function(x, y)
		if x.p ~= y.p then return x.p < y.p end
		return x.c < y.c
	end)
	local t = self:_read_target()
	local snap = {
		snapshot_version = 2, tool = { name = "ShadowScan", version = version_info.version },
		place_id = t.place_id, game_id = t.game_id, created_utc = self:_now_iso(), audit_id = a.audit_id,
		objects_visited = a.scan.stats.visited, counts = counts, remotes = remotes,
	}
	snap.counts = json.object(snap.counts)
	local ok, text = pcall(json.encode, snap)
	if not ok then return nil, "snapshot encoding failed" end
	snap.sha256 = sha256.hex(text)
	local ok2, text2 = pcall(json.encode, snap)
	if not ok2 then return nil, "snapshot encoding failed" end
	return { data = snap, json = text2, sha256 = snap.sha256 }
end

function Main:save_snapshot()
	local snap, err = self:snapshot()
	if not snap then return false, err end
	local stamp = util.audit_stamp(self.deps.time())
	local path = "ShadowScan/out/snapshot-" .. stamp .. ".json"
	local ok, werr = Adapter.write_file(self.caps, path, snap.json)
	if not ok then return false, tostring(werr) end
	self:_say("SNAPSHOT SAVED -> " .. path .. " (" .. tostring(#snap.data.remotes) .. " remote(s))")
	return true, path
end

-- Delete a snapshot file. Only possible when the executor exposes delfile; never pretends otherwise.
function Main:delete_snapshot(path)
	if not self.caps.delfile then return false, "this environment exposes no delfile function; delete the file through your executor's file manager instead" end
	if type(path) ~= "string" or path == "" or not string.find(path, "snapshot-", 1, true) then
		return false, "refusing to delete: the path must name a ShadowScan snapshot file"
	end
	local ok, err = pcall(self.caps.delfile, path)
	if not ok then return false, "delfile failed: " .. tostring(err) end
	self:_say("SNAPSHOT DELETED -> " .. path)
	return true, path
end

-- compare_snapshot(previous_json) -> ok, diff | message.
-- 0.4.0 diff: added / removed / metadata-changed / moved (name-based match, LOW confidence) + per-match confidence.
function Main:compare_snapshot(previous_json)
	local current, err = self:snapshot()
	if not current then return false, err end
	local prev = json.decode(previous_json)
	if type(prev) ~= "table" or type(prev.remotes) ~= "table" or (prev.snapshot_version ~= 1 and prev.snapshot_version ~= 2) then
		return false, "that file is not a ShadowScan snapshot (v1/v2)"
	end
	local t = self:_read_target()
	if prev.place_id ~= nil and t.place_id ~= nil and prev.place_id ~= t.place_id then
		return false, "the snapshot was taken in a different place (" .. tostring(prev.place_id) .. " vs " .. tostring(t.place_id) .. "); comparison refused"
	end
	local prev_set, cur_set = {}, {}
	for _, r in ipairs(prev.remotes) do prev_set[r.c .. "|" .. r.p] = r end
	for _, r in ipairs(current.data.remotes) do cur_set[r.c .. "|" .. r.p] = r end
	local added, removed, changed = {}, {}, {}
	for k, r in pairs(cur_set) do
		local old = prev_set[k]
		if not old then
			added[#added + 1] = { class_name = r.c, path = r.p, name = r.n, family = r.f or "" }
		elseif (old.m or "") ~= (r.m or "") or (old.n or "") ~= (r.n or "") then
			-- same place in the tree, different observable metadata/name (replication timing may explain it)
			changed[#changed + 1] = { class_name = r.c, path = r.p, name = r.n,
				previous_metadata = old.m or "", current_metadata = r.m or "", match_confidence = "high" }
		end
	end
	for k, r in pairs(prev_set) do
		if not cur_set[k] then
			removed[#removed + 1] = { class_name = r.c, path = r.p, name = r.n, family = r.f or "" }
		end
	end
	-- conservative cross-session matching for moved objects: same class+name at a different path = LOW confidence
	local moved = {}
	for _, rm in ipairs(removed) do
		for _, ra in ipairs(added) do
			if rm.class_name == ra.class_name and rm.name == ra.name then
				moved[#moved + 1] = { class_name = rm.class_name, name = rm.name, from = rm.path, to = ra.path, match_confidence = "low" }
				break
			end
		end
	end
	table.sort(added, function(x, y) return x.path < y.path end)
	table.sort(removed, function(x, y) return x.path < y.path end)
	table.sort(changed, function(x, y) return x.path < y.path end)
	local diff = {
		previous_created_utc = prev.created_utc, compared_utc = self:_now_iso(),
		previous_snapshot_version = prev.snapshot_version,
		added = added, removed = removed, changed = changed, moved = moved,
		added_count = #added, removed_count = #removed, changed_count = #changed, moved_count = #moved,
		previous_remote_count = #prev.remotes, current_remote_count = #current.data.remotes,
		-- honesty: disappearance is NOT proof of deletion (streaming/replication timing)
		note = "A remote that no longer appears may still exist on the server: replication, streaming and distance can hide it.",
	}
	if self.audit then self.snapshot_diff = diff end
	self:_say(string.format("SNAPSHOT COMPARED: +%d added, -%d removed, ~%d changed, %d moved (low-confidence) since %s",
		#added, #removed, #changed, #moved, tostring(prev.created_utc)))
	return true, diff
end

-- File-backed convenience for the GUI: reads the snapshot, then compares.
function Main:compare_snapshot_file(path)
	local ok, data = Adapter.read_file(self.caps, path)
	if not ok then return false, tostring(data) end
	return self:compare_snapshot(data)
end

-- ---------------------------------------------------------------- draft test plan generator (0.3.0)
-- Produces a manifest DRAFT from the highest-risk remote candidates. The draft is deliberately INVALID until a
-- human replaces the approval placeholders (validators on both sides reject unedited drafts).
function Main:draft_manifest(opts)
	opts = opts or {}
	if not self.audit or #self.audit.findings == 0 then return nil, "no findings to draft from; run passive_scan() first" end
	local t = self:_read_target()
	if type(t.game_id) ~= "number" or type(t.place_id) ~= "number" then
		return nil, "GameId/PlaceId unavailable in this environment; the draft needs a real target"
	end
	local max_tests = math.min(opts.max_tests or 5, 20)
	local sev_order = { informational = 1, low = 2, medium = 3, high = 4 }
	-- default floor "low": most passive candidates are name-hinted; the developer edits the draft anyway,
	-- and the selection is ordered by risk score so the most-evidenced remotes come first.
	local min_sev = sev_order[opts.severity_min or "low"] or 2
	local picked = {}
	for _, f in ipairs(self.audit.findings) do
		local cls_ok = f.object_class == "RemoteEvent" or f.object_class == "RemoteFunction" or f.object_class == "UnreliableRemoteEvent"
		local root_ok = util.startswith(f.object_path, "ReplicatedStorage.") or util.startswith(f.object_path, "Workspace.") or util.startswith(f.object_path, "ReplicatedFirst.")
		if cls_ok and root_ok and #f.object_path <= 400 and (sev_order[f.severity] or 0) >= min_sev then
			picked[#picked + 1] = f
		end
	end
	table.sort(picked, function(x, y)
		local sx, sy = x.risk and x.risk.score or 0, y.risk and y.risk.score or 0
		if sx ~= sy then return sx > sy end
		return x.object_path < y.object_path
	end)
	while #picked > max_tests do table.remove(picked) end
	if #picked == 0 then return nil, "no remote candidate meets the severity floor for a draft" end
	local cases = {}
	for i, f in ipairs(picked) do
		cases[i] = {
			test_id = "DRAFT-" .. string.format("%03d", i),
			title = "DRAFT: baseline call to " .. util.last_segment(f.object_path) .. " (review and complete with the developer)",
			endpoint = { path = f.object_path, class = f.object_class, is_canary = false },
			test_type = "read_only_call",
			args = {},
			mutates_state = false,
			read_only_justification = "REPLACE: explain why this call is safe to observe read-only in production, or move the test to a private QA place.",
			max_calls = 1,
			min_interval_seconds = 0.2,
			expected_outcome = "accepted",
			evidence = { channel = "none" },
			confirmable = false,
		}
	end
	local now = self.deps.time()
	local draft = {
		schema_version = "1.0",
		manifest = {
			manifest_id = "DRAFT-" .. string.upper(util.rand_hex(4, self.deps.rand)),
			version = "0.1.0",
			created_utc = self:_now_iso(),
			expires_utc = util.unix_to_iso(now + 7 * 86400),
			approved_by = "DRAFT - replace with the approver's name",
			approval_reference = "REPLACE - reference to the written approval (ticket, signed review, ...)",
		},
		target = { game_id = t.game_id, place_ids = { t.place_id }, mode = "production_observation", qa = nil },
		limits = { max_total_calls = math.min(#cases, 100), min_interval_seconds = 0.2, max_duration_seconds = 600 },
		stop_conditions = { stop_on_error = true, stop_on_unexpected_outcome = true, stop_on_inconclusive = false },
		test_cases = cases,
	}
	local ok, text = pcall(json.encode, draft, true)
	if not ok then return nil, "draft encoding failed" end
	self.last_manifest_draft = text
	self:_say(string.format("MANIFEST DRAFT GENERATED: %d test case(s). It is NOT valid until a human replaces the DRAFT/REPLACE placeholders and approves it.", #cases))
	return text
end

function Main:export_manifest_draft()
	if not self.last_manifest_draft and not self:draft_manifest() then return false, "no draft available" end
	local stamp = util.audit_stamp(self.deps.time())
	local path = "ShadowScan/out/draft-manifest-" .. stamp .. ".json"
	local ok, err = Adapter.write_file(self.caps, path, self.last_manifest_draft)
	if not ok then return false, tostring(err) end
	self:_say("MANIFEST DRAFT EXPORTED -> " .. path .. " (validate it: python shadowscan.py manifest validate <file>)")
	return true, path
end

function Main:discard()
	self:stop_live()
	self.audit, self.last_report, self.last_report_json = nil, nil, nil
	self.last_manifest_draft, self.snapshot_diff = nil, nil
	self:_say("audit state discarded")
end

-- Re-derives candidates from the observations already in memory (nothing is sent, nothing is re-scanned).
-- returns { observed, candidates } or nil when there is nothing to refresh.
function Main:refresh_inventory()
	local a = self.audit
	if not a or not a.scan then
		self:_say("No inventory to refresh yet. Run passive_scan() first.")
		return nil
	end
	a.findings = analyzer.analyze(a.scan.observations)
	index_findings(a)
	self:_say(string.format("INVENTORY REFRESHED: %d observation(s) re-analysed -> %d candidate(s); nothing was sent to the game", #a.scan.observations, #a.findings))
	return { observed = #a.scan.observations, candidates = #a.findings }
end

return Main
end
__factories["client.profiles"] = function(require)
-- Performance profiles (0.4.0): presets for the incremental scanner. All three keep cancellation and the
-- batch structure; they trade interference for throughput. The values are engineering targets measured with
-- tools/benchmark.py - NOT guaranteed frame times (see docs/PERFORMANCE.md).
local P = {}

P.ORDER = { "low_impact", "balanced", "fast" }

P.PROFILES = {
	low_impact = {
		key = "low_impact", label = "Low Impact",
		batch_budget_ms = 1.5, batch_min = 8, batch_max = 128, progress_every = 4000,
		description = "Smallest batches, fewest GUI updates, lowest practical interference.",
	},
	balanced = {
		key = "balanced", label = "Balanced",
		batch_budget_ms = 3, batch_min = 16, batch_max = 512, progress_every = 2000,
		description = "Default. Balanced throughput and responsiveness.",
	},
	fast = {
		key = "fast", label = "Fast",
		batch_budget_ms = 6, batch_min = 64, batch_max = 1024, progress_every = 1000,
		description = "Larger adaptive batches; still bounded and cancellable.",
	},
}

function P.get(key)
	return P.PROFILES[key] or P.PROFILES.balanced
end

-- resolves the scanner config for a profile; explicit config values override the preset
function P.apply(profile_key, config)
	local base = P.get(profile_key)
	local out = {
		batch_budget_ms = config.batch_budget_ms or base.batch_budget_ms,
		batch_min = config.batch_min or base.batch_min,
		batch_max = config.batch_max or base.batch_max,
		progress_every = config.progress_every or base.progress_every,
	}
	return base, out
end

return P
end
__factories["client.ui.app"] = function(require)
-- App: wires session + store + controller + renderer and owns the window lifecycle (open / hide / minimize / destroy).
local Store = require("client.ui.store")
local Controller = require("client.ui.controller")
local Renderer = require("client.ui.renderer")
local Shell = require("client.ui.shell")

local App = {}
App.__index = App

-- opts (all optional; tests inject everything): deps, factory, parent, env, viewport, toggle_key
function App.open(session, opts)
	opts = opts or {}
	local self = setmetatable({}, App)
	local base = session.deps
	local deps = opts.deps or { time = base.time, clock = base.clock, spawn = base.spawn, wait = base.wait }
	local viewport = opts.viewport or { w = 1366, h = 768 }
	if not opts.viewport and workspace and workspace.CurrentCamera then
		local ok, vs = pcall(function() return workspace.CurrentCamera.ViewportSize end)
		if ok and vs then viewport = { w = math.floor(vs.X), h = math.floor(vs.Y) } end
	end
	self.store = Store.new(Store.new_state({ now = deps.time(), viewport = viewport }))
	self.controller = Controller.new(session, self.store, deps)
	self.env = opts.env or { Color3 = Color3, UDim2 = UDim2, UDim = UDim, Enum = Enum }
	self.factory = opts.factory or { create = function(class) return Instance.new(class) end }

	-- ScreenGui host: gethui() when the executor has it, otherwise CoreGui, otherwise PlayerGui
	self.gui = opts.gui or self.factory.create("ScreenGui")
	self.gui.Name = "ShadowScan"
	self.gui.ResetOnSpawn = false
	self.gui.IgnoreGuiInset = true
	if opts.parent then self.gui.Parent = opts.parent
	else
		local parent = session.caps.gethui and session.caps.gethui()
		if not parent then
			local okc, core = pcall(function() return game:GetService("CoreGui") end)
			parent = okc and core or nil
		end
		if not parent then
			local okp, pg = pcall(function() return game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui", 5) end)
			parent = okp and pg or nil
		end
		self.gui.Parent = parent
	end

	self.renderer = Renderer.new({ factory = self.factory, parent = self.gui, env = self.env, dispatch = function(action) self:dispatch(action) end })
	self.store:subscribe(function() self:render() end)
	self:render()
	self.key_conns = {}
	-- Keyboard toggle: use the injected UserInputService when the caller supplies one (tests, custom hosts);
	-- otherwise ask the normal Roblox service interface (the session's game first, then the global one).
	-- When neither works, NO binding is made and the UI must not claim keyboard support (the sidebar hint
	-- reflects this via window.toggle_key).
	local game_ref = (session.deps and session.deps.game) or game
	local uis, uis_source = opts.uis, opts.uis and "injected" or nil
	if not uis and game_ref then
		local ok, svc = pcall(function() return game_ref:GetService("UserInputService") end)
		if ok and svc then uis, uis_source = svc, "service" end
	end
	self.uis, self.uis_source = uis, uis_source
	if uis then self:_bind_keys(uis, opts.toggle_key or "RightShift") end
	return self
end

function App:dispatch(action)
	if action.name == "window.close" then
		self.controller:dispatch(action)
		local st = self.store.state
		if st.scan.state == "scanning" then self.controller.session:_say("window hidden; the scan keeps running (press the toggle key to show it again)") end
		return
	end
	self.controller:dispatch(action)
end

function App:render()
	local st = self.store.state
	self.gui.Enabled = st.window.visible
	local root, meta = Shell.build(st)
	if self.controller:apply_meta(meta) then
		root = Shell.build(st) -- paging was clamped; draw the corrected page once
	end
	self.renderer:render(root)
	self.last_scene = root
end

function App:show() self.store.state.window.visible = true self.store:notify() end
function App:hide() self.store.state.window.visible = false self.store:notify() end
function App:toggle() self.store.state.window.visible = not self.store.state.window.visible self.store:notify() end

function App:_bind_keys(uis, key_name)
	-- One tracked connection per binding; destroy() disconnects every one of them.
	-- Enum comes from the injected environment so this also works outside Roblox (CLI tests, custom hosts).
	local enum = (self.env and self.env.Enum) or Enum
	local function listen(signal, fn)
		local ok, conn = pcall(function() return signal:Connect(fn) end)
		if ok and conn then self.key_conns[#self.key_conns + 1] = conn end
		return ok and conn ~= nil
	end
	local bound = false
	if listen(uis.InputBegan, function(input, processed)
		local code = input and input.KeyCode
		if code == enum.KeyCode[key_name] and not processed then self:toggle()
		elseif code == enum.KeyCode.Escape and self.store.state.manifest.confirm_open then
			self.controller:dispatch({ name = "manifest.run_cancel" })
		end
	end) then
		self.toggle_key = key_name
		self.store.state.window.toggle_key = key_name
		bound = true
	end
	if not bound then self.uis, self.uis_source = nil, nil end
	self.store:notify()
end

function App:destroy()
	for _, conn in ipairs(self.key_conns or {}) do
		pcall(function() conn:Disconnect() end)
	end
	self.key_conns = {}
	self.renderer:destroy()
	pcall(function() self.gui:Destroy() end)
end

return App
end
__factories["client.ui.components"] = function(require)
-- Reusable scene components. Every function returns plain node tables; nothing here touches Roblox.
-- Sizes come from design tokens and snap to the 4px grid; tests/luau/test_ui.lua validates every page built from these.
local tokens = require("client.ui.tokens")
local measure = require("client.ui.measure")
local layout = require("client.ui.layout")

local C = {}
local K, SP, SZ, TY = tokens.color, tokens.space, tokens.size, tokens.type

local function ceil4(v) return math.ceil(v / 4) * 4 end
C.ceil4 = ceil4

-- ---------------------------------------------------------------- colour helpers
local function hex_to_rgb(h) return tonumber(string.sub(h, 2, 3), 16), tonumber(string.sub(h, 4, 5), 16), tonumber(string.sub(h, 6, 7), 16) end
function C.resolve(c) if string.sub(c, 1, 1) == "#" then return c end return K[c] end
function C.mix(a, b, t) -- t of `a` over `b`
	local ar, ag, ab = hex_to_rgb(C.resolve(a))
	local br, bg, bb = hex_to_rgb(C.resolve(b))
	local function m(x, y) return math.floor(x * t + y * (1 - t) + 0.5) end
	return string.format("#%02X%02X%02X", m(ar, br), m(ag, bg), m(ab, bb))
end

local TONES = {
	neutral = { fg = "text_muted", border = "border" },
	text = { fg = "text", border = "border_strong" },
	accent = { fg = "accent_hover", border = "accent" },
	success = { fg = "success", border = "success" },
	warning = { fg = "warning", border = "warning" },
	error = { fg = "error", border = "error" },
}
C.TONES = TONES

-- ---------------------------------------------------------------- primitives
function C.text(id, rect, text, o)
	o = o or {}
	local ty = TY[o.type or "body"]
	return { id = id, kind = "text", rect = rect, text = tostring(text == nil and "" or text), font = o.font or ty.font, size = ty.size, line = ty.line,
		color = o.color or "text", align = o.align or "left", wrap = o.wrap, truncate = o.truncate, numeric = o.numeric }
end

-- single line of text at (x,y) with the token line height
function C.line_text(id, x, y, w, text, o)
	local ty = TY[(o and o.type) or "body"]
	return C.text(id, { x = x, y = y, w = w, h = ty.line }, text, o)
end

-- wrapped paragraph; returns node whose height fits the wrapped lines
function C.paragraph(id, x, y, w, text, o)
	o = o or {}
	local ty = TY[o.type or "body"]
	local font = o.font or ty.font
	local lines = measure.lines(text, ty.size, font, w)
	local node = C.text(id, { x = x, y = y, w = w, h = lines * ty.line }, text, o)
	node.wrap = true
	return node
end

function C.button_w(label, min_w) return math.max(min_w or 80, ceil4(measure.width(label, 13, "ui_medium") + 32)) end

function C.button(id, rect, label, o)
	o = o or {}
	return { id = id, kind = "button", rect = rect, label = label, style = o.style or "secondary", action = o.action, disabled = o.disabled,
		loading = o.loading, selected = o.selected, role = o.role, font = "ui_medium", size = 13, truncate = o.truncate, compact_ok = o.compact_ok, tip = o.tip }
end

function C.line(id, rect, color) return { id = id, kind = "frame", rect = rect, fill = color or "border", hairline = true } end

function C.badge(id, x, y, label, tone, height)
	local t = TONES[tone or "neutral"]
	local bh = height or SZ.badge_h
	local w = ceil4(measure.width(label, 12, "ui_medium") + 16)
	local fill = C.mix(t.fg, "panel", 0.14)
	return {
		id = id, kind = "frame", leaf = true, rect = { x = x, y = y, w = w, h = bh }, fill = fill, stroke = C.mix(t.border, "panel", 0.5), radius = SP.xs,
		children = { C.text(id .. ".t", { x = 4, y = 0, w = w - 8, h = bh }, label, { type = "label", color = t.fg, align = "center" }) },
	}, w
end

function C.badge_w(label) return ceil4(measure.width(label, 12, "ui_medium") + 16) end

-- ---------------------------------------------------------------- containers
-- returns node, inner (inner is relative to the node, below the title)
function C.panel(id, rect, title, o)
	o = o or {}
	local node = { id = id, kind = "frame", rect = rect, fill = o.fill or "panel", stroke = "border", radius = SP.xs + 2, pad = SZ.panel_pad, children = {} }
	local top = SZ.panel_pad
	if title then
		local right = o.title_right_w or 0
		node.children[#node.children + 1] = C.text(id .. ".title", { x = SZ.panel_pad, y = SZ.panel_pad, w = rect.w - 2 * SZ.panel_pad - right, h = 20 }, title,
			{ type = "heading", truncate = true })
		top = SZ.panel_pad + 20 + SP.md
	end
	return node, { x = SZ.panel_pad, y = top, w = rect.w - 2 * SZ.panel_pad, h = rect.h - top - SZ.panel_pad }
end

function C.scroll(id, rect, canvas_h) return { id = id, kind = "scroll", rect = rect, canvas_h = math.max(canvas_h, rect.h), children = {} } end

-- key/value rows, label column left, value left aligned in the second column. returns nodes, used height
function C.kv(id, inner, rows, label_w)
	label_w = label_w or 140
	local nodes, y = {}, inner.y
	for i, row in ipairs(rows) do
		nodes[#nodes + 1] = C.line_text(id .. ".l" .. i, inner.x, y + 4, label_w - SP.sm, row.label, { type = "caption", color = "text_muted", truncate = true })
		local vx, vw = inner.x + label_w, inner.w - label_w
		if row.badge then
			local b = C.badge(id .. ".v" .. i, vx, y + 4, row.badge, row.tone)
			nodes[#nodes + 1] = b
			if row.text then
				local bw = C.badge_w(row.badge)
				nodes[#nodes + 1] = C.line_text(id .. ".d" .. i, vx + bw + SP.sm, y + 4, math.max(0, vw - bw - SP.sm), row.text, { type = "caption", color = "text_muted", truncate = true })
			end
		else
			nodes[#nodes + 1] = C.line_text(id .. ".v" .. i, vx, y + 4, vw, row.value, { type = row.mono and "mono" or "body", color = row.color or "text", truncate = true })
