end

function C.kv_height(n) return n * 28 end

-- ---------------------------------------------------------------- states
function C.empty_state(id, rect, title, body, action)
	local nodes = {}
	local bw = math.min(rect.w - 32, 360)
	local x = rect.x + ceil4((rect.w - bw) / 2)
	local para = C.paragraph(id .. ".body", x, 0, bw, body, { color = "text_muted", align = "center" })
