	end
	return nodes
end

function C.error_state(id, rect, title, body, next_step, action)
	local nodes = {}
	local bw = math.min(rect.w - 32, 420)
	local x = rect.x + ceil4((rect.w - bw) / 2)
	local p1 = C.paragraph(id .. ".body", x, 0, bw, body, { color = "text" })
	local p2 = C.paragraph(id .. ".next", x, 0, bw, "Next step: " .. next_step, { color = "text_muted" })
	local h = 28 + SP.sm + p1.rect.h + SP.sm + p2.rect.h + (action and (SP.lg + 32) or 0)
	local y = rect.y + math.max(0, ceil4((rect.h - h) / 2))
	nodes[#nodes + 1] = C.line_text(id .. ".title", x, y, bw, title, { type = "heading", color = "error", truncate = true })
	nodes[#nodes].rect.h = 28
	p1.rect.y = y + 28 + SP.sm
	p2.rect.y = p1.rect.y + p1.rect.h + SP.sm
	nodes[#nodes + 1] = p1
	nodes[#nodes + 1] = p2
	if action then
		local w = C.button_w(action.label)
		nodes[#nodes + 1] = C.button(id .. ".act", { x = x, y = p2.rect.y + p2.rect.h + SP.lg, w = w, h = 32 }, action.label, action)
	end
	return nodes
end

-- one-line feedback: "Done  Saved ..." / "Failed  ..." (label + message, so colour is never the only signal)
function C.notice(id, rect, tone, label, message)
	local lw = ceil4(measure.width(label, 12, "ui_medium") + SP.md)
	return {
		C.line_text(id .. ".l", rect.x, rect.y, lw, label, { type = "label", color = TONES[tone].fg }),
		C.line_text(id .. ".m", rect.x + lw, rect.y, rect.w - lw, message, { type = "caption", color = "text_muted", truncate = true }),
	}
end

-- ---------------------------------------------------------------- table
-- spec: columns = { {key,label,w?,min_w,align,numeric,mono,tone=function(v)->tone,priority,sortable} }, rows = { {id, cells={key=value}} }
--       sort={key,dir}, sort_action=function(key), row_action=function(row), selected_id, page_index, page_action=function(delta), empty={title,body}
function C.table_capacity(h, total)
	local avail = h - SZ.table_header_h
	local cap = math.floor(avail / SZ.row_h)
	if total > cap then cap = math.floor((avail - 48) / SZ.row_h) end
	return math.max(1, cap)
end

local function pick_columns(cols, width)
	local active = {}
	for _, c in ipairs(cols) do active[#active + 1] = c end
	local function need()
		local n = 0
		for _, c in ipairs(active) do n += (c.w or c.min_w or 96) end
		return n
	end
	while need() > width and #active > 2 do
		local drop, best = nil, -1
		for i, c in ipairs(active) do
			if (c.priority or 0) > best then best, drop = c.priority or 0, i end
		end
		if best <= 0 then break end
		table.remove(active, drop)
	end
	return active
end

function C.table(id, rect, spec)
	local node = { id = id, kind = "frame", rect = rect, fill = "panel", stroke = "border", radius = SP.xs + 2, children = {}, clip = true }
	local cols = pick_columns(spec.columns, rect.w)
	local fixed, flex = 0, 0
	for _, c in ipairs(cols) do
		if c.w then fixed += c.w else flex += 1 end
	end
	local widths, used = {}, 0
	local flex_total = rect.w - fixed
	local flex_i = 0
	for i, c in ipairs(cols) do
		if c.w then widths[i] = c.w
		else
			flex_i += 1
			widths[i] = (flex_i == flex) and (flex_total - math.floor(flex_total / flex / 4) * 4 * (flex - 1)) or math.floor(flex_total / flex / 4) * 4
		end
		used += widths[i]
	end
	-- header
	local header = { id = id .. ".head", kind = "frame", rect = { x = 0, y = 0, w = rect.w, h = SZ.table_header_h }, fill = "panel_raised", children = {} }
	local x = 0
	local colx = {}
	for i, c in ipairs(cols) do
		colx[i] = x
		local label = c.label
		if spec.sort and spec.sort.key == c.key then label = label .. (spec.sort.dir == "asc" and "  ^" or "  v") end
		local cell = { x = x + SP.sm, y = 4, w = widths[i] - 2 * SP.sm, h = 20 }
		if c.sortable and spec.sort_action then
			local b = C.button(id .. ".h." .. c.key, { x = x, y = 0, w = widths[i], h = SZ.table_header_h }, label, { style = "header", action = spec.sort_action(c.key), compact_ok = true, truncate = true })
			b.align = c.align
			header.children[#header.children + 1] = b
		else
			header.children[#header.children + 1] = C.text(id .. ".h." .. c.key, cell, label, { type = "label", color = "text_muted", align = c.align or "left", truncate = true })
		end
		x += widths[i]
	end
	node.children[#node.children + 1] = header
	node.children[#node.children + 1] = C.line(id .. ".hl", { x = 0, y = SZ.table_header_h - 1, w = rect.w, h = 1 }, "border")

	local total = #spec.rows
	local cap = C.table_capacity(rect.h, total)
	local page_count = math.max(1, math.ceil(total / cap))
	local page_index = math.min(math.max(spec.page_index or 1, 1), page_count)
	local first = (page_index - 1) * cap + 1
	local last = math.min(total, first + cap - 1)
	if total == 0 then
		local e = spec.empty or { title = "Nothing to show", body = "There are no rows yet." }
		for _, n in ipairs(C.empty_state(id .. ".empty", { x = 0, y = SZ.table_header_h, w = rect.w, h = rect.h - SZ.table_header_h }, e.title, e.body, e.action)) do
			node.children[#node.children + 1] = n
		end
	end
	for k = first, last do
		local row = spec.rows[k]
		local y = SZ.table_header_h + (k - first) * SZ.row_h
		local btn = C.button(id .. ".r." .. tostring(row.id), { x = 0, y = y, w = rect.w, h = SZ.row_h }, nil, { style = "row", action = spec.row_action and spec.row_action(row),
			selected = (spec.selected_id ~= nil and row.id == spec.selected_id) })
		btn.children = {}
		for i, c in ipairs(cols) do
			local v = row.cells[c.key]
			local cw = widths[i] - 2 * SP.sm
			if c.badge and v ~= nil and v ~= "" then
				local tone = c.badge(v)
				local b = C.badge(id .. ".r." .. tostring(row.id) .. "." .. c.key, colx[i] + SP.sm, 8, tostring(v), tone)
				if b.rect.w > cw then b.rect.w = cw; b.children[1].rect.w = math.max(0, cw - 8); b.children[1].truncate = true end
				btn.children[#btn.children + 1] = b
			else
				local t = C.text(id .. ".r." .. tostring(row.id) .. "." .. c.key, { x = colx[i] + SP.sm, y = 8, w = cw, h = 20 }, v, { type = c.mono and "mono" or "body",
					color = c.muted and "text_muted" or "text", align = c.align or "left", truncate = true, numeric = c.numeric })
				if c.mono then t.rect.h = 20 end
				btn.children[#btn.children + 1] = t
			end
		end
		node.children[#node.children + 1] = btn
	end
	-- pager
	if page_count > 1 then
		local py = rect.h - 48
		node.children[#node.children + 1] = { id = id .. ".pager", kind = "frame", rect = { x = 0, y = py, w = rect.w, h = 48 }, fill = "panel_raised", children = {} }
		local pg = node.children[#node.children]
		pg.children[1] = C.line_text(id .. ".pager.t", SP.lg, 12, rect.w - 2 * SP.lg - 2 * 96 - SP.sm * 2, string.format("%d-%d of %d", first, last, total), { type = "caption", color = "text_muted", numeric = false, truncate = true })
		pg.children[1].rect.h = 20
		local rs = layout.right_aligned({ x = 0, y = 8, w = rect.w - SP.lg, h = 32 }, { 96, 96 }, 32)
		pg.children[2] = C.button(id .. ".prev", rs[1], "Previous", { disabled = page_index <= 1, action = spec.page_action and spec.page_action(-1) })
		pg.children[3] = C.button(id .. ".next", rs[2], "Next", { disabled = page_index >= page_count, action = spec.page_action and spec.page_action(1) })
	end
	return node, { page_size = cap, page_count = page_count, page_index = page_index, first = first, last = last, total = total, columns = #cols }
end

-- ---------------------------------------------------------------- dialog
-- spec: title, body, input={value,placeholder,action,password}, buttons={{label,style,action,disabled}}, width
function C.dialog(id, win_w, win_h, spec)
	local w = layout.snap(math.min(spec.width or 480, win_w - 64))
	local inner_w = w - 2 * SZ.panel_pad
	local body = C.paragraph(id .. ".body", SZ.panel_pad, 0, inner_w, spec.body or "", { color = "text_muted" })
	local phrase = spec.phrase and C.paragraph(id .. ".phrase", SZ.panel_pad, 0, inner_w, spec.phrase, { type = "mono" })
	local check = spec.checkbox and C.button(id .. ".check", { x = SZ.panel_pad, y = 0, w = inner_w, h = 32 }, spec.checkbox.label,
		{ style = "segment", selected = spec.checkbox.value, action = spec.checkbox.action, truncate = true })
	local h = SZ.panel_pad + 24 + SP.sm + body.rect.h + (phrase and (SP.sm + phrase.rect.h) or 0) + (spec.input and (SP.md + 32) or 0) + (check and (SP.md + 32) or 0) + SP.lg + 32 + SZ.panel_pad
	h = ceil4(h)
	local dialog = { id = id .. ".box", kind = "frame", rect = { x = layout.snap((win_w - w) / 2), y = layout.snap((win_h - h) / 2), w = w, h = h },
		fill = "panel_raised", stroke = "border_strong", radius = SP.xs + 2, pad = SZ.panel_pad, children = {} }
	dialog.children[1] = C.line_text(id .. ".title", SZ.panel_pad, SZ.panel_pad, inner_w, spec.title, { type = "heading", truncate = true })
	dialog.children[1].rect.h = 24
	body.rect.y = SZ.panel_pad + 24 + SP.sm
	dialog.children[2] = body
	local y = body.rect.y + body.rect.h
	if phrase then
		phrase.rect.y = y + SP.sm
		dialog.children[#dialog.children + 1] = phrase
		y = phrase.rect.y + phrase.rect.h
	end
	if spec.input then
		y += SP.md
		dialog.children[#dialog.children + 1] = { id = id .. ".input", kind = "input", rect = { x = SZ.panel_pad, y = y, w = inner_w, h = 32 }, text = spec.input.value or "",
			placeholder = spec.input.placeholder, action = spec.input.action, mono = true }
		y += 32
	end
	if check then
		y += SP.md
		check.rect.y = y
		dialog.children[#dialog.children + 1] = check
		y += 32
	end
	y += SP.lg
	local widths = {}
	for i, b in ipairs(spec.buttons) do widths[i] = C.button_w(b.label) end
	local rects = layout.right_aligned({ x = SZ.panel_pad, y = y, w = inner_w, h = 32 }, widths, 32)
	for i, b in ipairs(spec.buttons) do
		local o = { style = b.style, action = b.action, disabled = b.disabled }
		if i == #spec.buttons then o.role = "primary_action" end
		dialog.children[#dialog.children + 1] = C.button(id .. ".b" .. i, rects[i], b.label, o)
	end
	return { id = id, kind = "button", style = "scrim", rect = { x = 0, y = 0, w = win_w, h = win_h }, overlay = true, fill = "overlay", alpha = 0.6, children = { dialog } }
end

-- ---------------------------------------------------------------- shell
C.NAV = {
	{ key = "overview", label = "Overview" },
	{ key = "scanner", label = "Scanner" },
	{ key = "findings", label = "Findings" },
	{ key = "explorer", label = "Remote Explorer" },
	{ key = "graph", label = "Graph" },
	{ key = "compare", label = "Session Compare" },
	{ key = "tests", label = "Approved Tests" },
	{ key = "export", label = "Secure Export" },
	{ key = "settings", label = "Settings / About" },
}

-- header: wordmark + tagline left; status + window controls right
function C.header(win_w, status, minimized)
	local node = { id = "header", kind = "frame", rect = { x = 0, y = 0, w = win_w, h = SZ.header_h }, fill = "sidebar", children = {} }
	local ch = node.children
	ch[#ch + 1] = { id = "header.mark", kind = "frame", rect = { x = SZ.content_pad, y = 16, w = 16, h = 16 }, fill = "accent", radius = 2 }
	ch[#ch + 1] = C.line_text("header.name", SZ.content_pad + 28, 12, 120, "SHADOWSCAN", { type = "heading" })
	ch[#ch].rect.h = 24
	if not minimized then ch[#ch + 1] = C.line_text("header.tag", SZ.content_pad + 28 + 128, 16, 160, "Client Security Auditor", { type = "caption", color = "text_muted" }) end
	local close_w, min_w = 72, minimized and 80 or 96
	local x = win_w - SP.lg - close_w
	ch[#ch + 1] = C.button("header.close", { x = x, y = 8, w = close_w, h = 32 }, "Close", { style = "ghost", action = { name = "window.close" } })
	x -= SP.sm + min_w
	ch[#ch + 1] = C.button("header.min", { x = x, y = 8, w = min_w, h = 32 }, minimized and "Restore" or "Minimize", { style = "ghost", action = { name = minimized and "window.restore" or "window.minimize" } })
	if status and not minimized then
		local bw = C.badge_w(status.label)
		local b = C.badge("header.status", x - SP.md - bw, 12, status.label, status.tone, 24)
		ch[#ch + 1] = b
	end
	ch[#ch + 1] = C.line("header.rule", { x = 0, y = SZ.header_h - 1, w = win_w, h = 1 }, "border")
	return node
end

function C.sidebar(shell, active, counts, version, toggle_key)
	local sb = shell.sidebar
	local node = { id = "sidebar", kind = "frame", rect = { x = sb.x, y = sb.y, w = sb.w, h = sb.h }, fill = "sidebar", children = {} }
	local y = SP.lg
	for _, item in ipairs(C.NAV) do
		local b = C.button("nav." .. item.key, { x = SP.sm, y = y, w = sb.w - 2 * SP.sm, h = SZ.nav_item_h }, item.label,
			{ style = "nav", selected = (item.key == active), action = { name = "nav", arg = item.key }, truncate = true })
		b.align = "left"
		node.children[#node.children + 1] = b
		local c = counts and counts[item.key]
		if c and c > 0 then
			b.children = { C.text("nav." .. item.key .. ".n", { x = b.rect.w - 12 - 40, y = 8, w = 40, h = 20 }, tostring(c), { type = "caption", color = "text_muted", align = "right", numeric = true }) }
		end
		y += SZ.nav_item_h + SP.xs
	end
	node.children[#node.children + 1] = C.line("sidebar.rule", { x = sb.w - 1, y = 0, w = 1, h = sb.h }, "border")
	node.children[#node.children + 1] = C.line_text("sidebar.ver", SP.lg, sb.h - 40, sb.w - 2 * SP.lg, "v" .. tostring(version), { type = "caption", color = "text_muted", truncate = true })
	-- Only claim the keyboard toggle when a UserInputService was actually bound (see client/ui/app.lua).
	local hint = toggle_key and (toggle_key .. ": show / hide") or "reopen from the console: ui:show()"
	node.children[#node.children + 1] = C.line_text("sidebar.hint", SP.lg, sb.h - 24, sb.w - 2 * SP.lg, hint, { type = "caption", color = "text_disabled", truncate = true })
	node.children[#node.children].rect.y = sb.h - 24
	return node
end

return C
end
__factories["client.ui.controller"] = function(require)
-- Controller: turns UI actions into calls on the session (client/main.lua) and mirrors the results into the store.
-- All business rules (allowlist, manifest checks, encryption, plaintext protection) stay in the session / scanner / companion.
-- This layer only adds: busy guards (no double submission), cancellable scan, honest feedback, and view state.
local Store = require("client.ui.store")
local V = require("client.ui.viewmodel")
local pb = require("client.ui.pages_b")
local layout = require("client.ui.layout")
local classify = require("scanner.classify")
local graph_mod = require("scanner.graph")

local Ctl = {}
Ctl.__index = Ctl

function Ctl.new(session, store, deps)
	local self = setmetatable({ session = session, store = store, deps = deps }, Ctl)
	local st = store.state
	st.info = session:ui_info()
	st.now = deps.time()
	st.started_at = st.now
	session:set_listener(function(level, text)
		Store.log(st, level, text, deps.time())
		store:notify()
	end)
	return self
end

local H = {}

local function now(self) return self.deps.time() end

-- Explorer data is CACHED here and refreshed only when findings change (scan end, live drain, refresh, clear) --
-- never re-computed per frame (see docs/PERFORMANCE.md).
local function refresh_explorer(st, session)
	local audit = session.audit
	if audit and audit.findings and audit.scan then
		st.explorer.families = classify.tally(audit.findings)
		local g = graph_mod.build(audit.scan.observations)
		local containers = graph_mod.container_summary(g, 200)
		st.explorer.containers, st.explorer.container_count = containers, #containers
		st.explorer.graph_stats = g.stats
		-- 0.4.0 Graph page: bounded listing (top 50 containers x 20 remotes), built once per findings change
		local listing, total = graph_mod.listing(g, 50, 20)
		st.graph.containers, st.graph.containers_total, st.graph.stats = listing, total, g.stats
		if st.graph.selected then
			local still_there = false
			for _, c in ipairs(listing) do if c.path == st.graph.selected then still_there = true end end
			if not still_there then st.graph.selected = nil end
		end
	else
		st.explorer.families, st.explorer.containers, st.explorer.container_count, st.explorer.graph_stats = {}, {}, 0, nil
		st.graph.containers, st.graph.containers_total, st.graph.stats = {}, 0, nil
	end
	st.explorer.version = (st.explorer.version or 0) + 1
end

function Ctl:_begin(key)
	local st = self.store.state
	if st.busy[key] then return false end
	st.busy[key] = true
	return true
end

function Ctl:_end(key)
	self.store.state.busy[key] = nil
	self.store:notify()
end

function Ctl:_feedback(tone, label, text)
	self.store.state.export.feedback = { tone = tone, label = label, text = text }
end

function Ctl:dispatch(action)
	if type(action) ~= "table" or not action.name then return end
	local h = H[action.name]
	if not h then return end
	h(self, action.arg)
	self.store:notify()
end

function Ctl:set_viewport(w, h)
	self.store.state.viewport = { w = w, h = h }
	self.store:notify()
end

function Ctl:tick()
	local st = self.store.state
	st.now = now(self)
	if st.scan.state == "scanning" and st.scan.started then st.scan.elapsed = self.deps.clock() - st.scan.started end
	-- passive live observation: drain the watcher's bounded buffer when it is running (cheap when empty)
	if st.live.running and self.session.live and self.session.live.running then
		local n = self.session:drain_live()
		if n > 0 then
			st.scan.observed = self.session.audit and #self.session.audit.scan.observations or st.scan.observed
			st.scan.candidates = self.session.audit and #self.session.audit.findings or st.scan.candidates
			st.findings.list = self.session.audit.findings
			refresh_explorer(st, self.session)
		end
	end
	if st.page == "overview" or st.scan.state == "scanning" or st.live.running then self.store:notify() end
end

-- ---------------------------------------------------------------- navigation & window
function H.nav(self, page) self.store.state.page = page end
function H.window_close(self) self.store.state.window.visible = false end
H["window.close"] = H.window_close
H["window.minimize"] = function(self) self.store.state.window.minimized = true end
H["window.restore"] = function(self) self.store.state.window.minimized = false end

-- ---------------------------------------------------------------- live observation (0.3.0)
H["live.toggle"] = function(self)
	local st = self.store.state
	if st.live.running then
		self.session:stop_live()
		st.live.running = false
		Store.log(st, "info", "Live observation stopped.", now(self))
	else
		local ok = self.session:start_live()
		st.live.running = ok
		if not ok then Store.log(st, "warn", "Live observation unavailable in this environment.", now(self)) end
	end
	st.info = self.session:ui_info()
end

-- ---------------------------------------------------------------- scanner
H["scan.start"] = function(self)
	local st = self.store.state
	if not self:_begin("scan") then return end
	local started = self.deps.clock()
	st.scan = { state = "scanning", visited = 0, observed = nil, candidates = nil, elapsed = 0, error = nil, started = started, cancel_requested = false }
	st.findings.list, st.findings.selected, st.findings.page = {}, nil, 1
	st.export.report, st.export.cipher, st.export.feedback = nil, nil, nil
	st.export.encryption = { state = "idle", detail = nil }
	self.deps.spawn(function()
		local ok, res, scan_state = pcall(self.session.passive_scan, self.session, {
			progress_every = 500,
			should_cancel = function() return st.scan.cancel_requested end,
			on_progress = function(n)
				st.scan.visited = n
				st.scan.elapsed = self.deps.clock() - started
				self.store:notify()
			end,
		})
		st.scan.elapsed = self.deps.clock() - started
		if not ok then
			st.scan.state, st.scan.error = "error", "The scan stopped unexpectedly: " .. tostring(res)
		elseif res == false then
			st.scan.state, st.scan.error = "error", "Target check failed. This place is not in config.allowed_place_ids, so nothing was scanned."
		else
			local audit = self.session.audit
			st.scan.visited = audit.scan.stats.visited
			st.scan.observed = #audit.scan.observations
			st.scan.candidates = #audit.findings
			st.findings.list = audit.findings
			st.scan.state = (scan_state == "cancelled") and "cancelled" or "complete"
		end
		st.info = self.session:ui_info()
		refresh_explorer(st, self.session)
		self:_end("scan")
	end)
end

H["scan.stop"] = function(self)
	local st = self.store.state
	if st.scan.state == "scanning" and not st.scan.cancel_requested then
		st.scan.cancel_requested = true
		Store.log(st, "warn", "Stop requested; finishing the current step...", now(self))
	end
end

-- Refresh Inventory: re-derives candidates from the observations already in memory. Nothing is sent to the game.
H["scan.refresh"] = function(self)
	local st = self.store.state
	if not self:_begin("scan.refresh") then return end
	local res = self.session:refresh_inventory()
	if res then
		st.scan.observed, st.scan.candidates = res.observed, res.candidates
		st.findings.list = self.session.audit.findings
		st.info = self.session:ui_info()
		refresh_explorer(st, self.session)
	else
		Store.log(st, "warn", "Nothing to refresh yet; run a passive scan first.", now(self))
	end
	self:_end("scan.refresh")
end

-- ---------------------------------------------------------------- findings
H["findings.sort"] = function(self, key)
	local f = self.store.state.findings
	f.sort = V.toggle_sort(f.sort, key)
	f.page = 1
end
H["findings.severity"] = function(self, sev)
	local f = self.store.state.findings
	f.filter.severity = (sev ~= "all") and sev or nil
	f.page = 1
end
H["findings.text"] = function(self, text)
	local f = self.store.state.findings
	f.filter.text = tostring(text or "")
	f.page = 1
end
H["findings.clear_filters"] = function(self)
	local f = self.store.state.findings
	f.filter = { severity = nil, text = "" }
	f.page = 1
end
H["findings.select"] = function(self, id) self.store.state.findings.selected = id end
H["findings.page"] = function(self, delta)
	local f = self.store.state.findings
	f.page = math.max(1, f.page + (delta or 0))
end

-- ---------------------------------------------------------------- approved tests
H["manifest.path"] = function(self, text) self.store.state.manifest.path_input = tostring(text or "") end
H["manifest.page"] = function(self, d) local m = self.store.state.manifest m.page = math.max(1, m.page + (d or 0)) end

H["manifest.load"] = function(self)
	local st = self.store.state
	local m = st.manifest
	if not self:_begin("manifest.load") then return end
	local ok, errs = self.session:load_manifest_file(m.path_input)
	m.page, m.dry_run_done, m.run_state, m.confirm_open, m.confirm_input = 1, false, "idle", false, ""
	if ok then
		local info = self.session:manifest_summary()
		m.state, m.errors, m.summary, m.tests, m.gate_reasons, m.plan = "valid", {}, info.summary, info.tests, info.gate_reasons, info.plan
	else
		m.state, m.errors, m.summary, m.tests, m.gate_reasons, m.plan = "invalid", errs or { "unknown error" }, nil, {}, {}, nil
	end
	self:_end("manifest.load")
end

local function mark_results(m, result)
	local by_id = {}
	for _, r in ipairs(result.test_runs or {}) do
		local label
		if r.status == "executed" or r.status == "failed" then label = V.VERDICT_LABEL[r.verdict] or r.verdict
		elseif r.status == "blocked" then label = "Blocked"
		elseif r.status == "skipped" then label = "Skipped"
		elseif r.status == "dry_run" then label = "Planned" end
		by_id[r.test_id] = label
	end
	for _, t in ipairs(m.tests) do t.result = by_id[t.id] or "" end
end

H["manifest.dry"] = function(self)
	local m = self.store.state.manifest
	if m.state ~= "valid" or not self:_begin("manifest.dry") then return end
	local result = self.session:active_run({ dry_run = true })
	if result and result.status == "dry_run" then
		m.dry_run_done, m.run_state = true, "idle"
		mark_results(m, result)
	else
		m.dry_run_done, m.run_state = false, "blocked"
		m.gate_reasons = (result and result.reason) and { result.reason } or m.gate_reasons
	end
	self:_end("manifest.dry")
end

H["manifest.run_open"] = function(self)
	local m = self.store.state.manifest
	if m.state == "valid" and m.dry_run_done and #m.gate_reasons == 0 then m.confirm_open, m.confirm_input, m.reset_ack = true, "", false end
end
H["manifest.run_cancel"] = function(self) local m = self.store.state.manifest m.confirm_open, m.confirm_input = false, "" end
H["manifest.confirm_input"] = function(self, text) self.store.state.manifest.confirm_input = tostring(text or "") end
H["manifest.reset_ack"] = function(self) local m = self.store.state.manifest m.reset_ack = not m.reset_ack end

H["manifest.run"] = function(self)
	local st = self.store.state
	local m = st.manifest
	if not m.confirm_open or not m.plan or m.confirm_input ~= m.plan.phrase then return end -- the phrase must match EXACTLY
	if m.plan.mutating and not m.reset_ack then return end
	if not self:_begin("manifest.run") then return end
	m.confirm_open = false
	m.run_state = "running"
	self.deps.spawn(function()
		local ok, result = pcall(self.session.active_run, self.session, { confirm = m.plan.phrase, reset_confirmed = m.reset_ack == true })
		m.confirm_input = ""
		if ok and result then
			mark_results(m, result)
			m.run_state = (result.status == "complete") and "done" or "blocked"
		else
			m.run_state = "blocked"
			Store.log(st, "error", "Active run failed: " .. tostring(result), now(self))
		end
		local audit = self.session.audit
		if audit then st.findings.list = audit.findings end
		self:_end("manifest.run")
	end)
end

-- ---------------------------------------------------------------- explorer (0.3.0)
H["explorer.family"] = function(self, fam)
	local e = self.store.state.explorer
	e.family = (fam ~= "all") and fam or nil
	e.page = 1
end
H["explorer.sort"] = function(self, key)
	local e = self.store.state.explorer
	if e.sort.key == key then e.sort.dir = (e.sort.dir == "desc") and "asc" or "desc"
	else e.sort = { key = key, dir = "desc" } end
	e.page = 1
end
H["explorer.select"] = function(self, id)
	local st = self.store.state
	st.findings.selected = id
	st.page = "findings"
end
H["explorer.page"] = function(self, d) local e = self.store.state.explorer e.page = math.max(1, e.page + (d or 0)) end
-- clicking a container opens Findings filtered by its name (all its remotes share that path segment)
H["explorer.container"] = function(self, path)
	local st = self.store.state
	local seg = string.match(tostring(path or ""), "([^%.]+)$") or tostring(path or "")
	st.findings.filter.text = seg
	st.findings.page = 1
	st.page = "findings"
end

-- ---------------------------------------------------------------- snapshots (0.3.0)
H["snapshot.path"] = function(self, text) self.store.state.snapshot.path_input = tostring(text or "") end

H["snapshot.save"] = function(self)
	local st = self.store.state
	if not self:_begin("snapshot.save") then return end
	local ok, res = self.session:save_snapshot()
	st.snapshot.state = ok and "saved" or "error"
	st.snapshot.detail = ok and tostring(res) or tostring(res)
	self:_end("snapshot.save")
end

H["snapshot.compare"] = function(self)
	local st = self.store.state
	local sn = st.snapshot
	if not self:_begin("snapshot.compare") then return end
	local ok, res = self.session:compare_snapshot_file(sn.path_input)
	if ok then
		sn.state, sn.diff, sn.detail = "compared", res, nil
		st.explorer.version = (st.explorer.version or 0) + 1
	else
		sn.state, sn.diff, sn.detail = "error", nil, tostring(res)
	end
	self:_end("snapshot.compare")
end

-- ---------------------------------------------------------------- draft plan generator (0.3.0)
H["manifest.draft"] = function(self)
	local st = self.store.state
	if not self:_begin("manifest.draft") then return end
	local ok, res = self.session:draft_manifest({})
	if ok then
		local okw, wres = self.session:export_manifest_draft()
		Store.log(st, "info", okw and ("Draft plan written to " .. tostring(wres) .. " - edit the placeholders, then validate it on the PC.")
			or ("Draft generated but not exported: " .. tostring(wres)), now(self))
	else
		Store.log(st, "warn", "No draft generated: " .. tostring(res), now(self))
	end
	self:_end("manifest.draft")
