-- ---------------------------------------------------------------- export
H["export.token"] = function(self, text) self.store.state.export.token_input = tostring(text or "") end
H["export.port"] = function(self, text)
	local digits = string.match(tostring(text or ""), "^%s*(%d+)%s*$")
	if digits then self.store.state.export.port_input = digits end
end

local function port_of(st)
	local p = tonumber(st.export.port_input)
	if not p or p < 1 or p > 65535 then return nil end
	return p
end

H["export.build"] = function(self)
	local st = self.store.state
	if not self:_begin("export.build") then return end
	local ex = st.export
	ex.feedback = nil
	local report = self.session:build_report()
	if report then
		local a = self.session.audit
		ex.report = { file_name = string.format("shadowscan-%s.report.json", a.audit_id), built_at = now(self), bytes = #self.session.last_report_json,
			candidates = #a.findings, runs = #a.test_runs }
		ex.cipher, ex.encryption = nil, { state = "idle", detail = nil }
		self:_feedback("success", "Built", "The report is in memory only. Encrypt it next; nothing was written to disk.")
	else
		ex.report = nil
		self:_feedback("error", "Failed", "There is nothing to report yet. Run a passive scan first.")
	end
	self:_end("export.build")
end

H["companion.check"] = function(self)
	local st = self.store.state
	local port = port_of(st)
	if not port then
		st.export.companion = { state = "unreachable", detail = "Enter a port between 1 and 65535." }
		return
	end
	if not self:_begin("companion.check") then return end
	st.export.companion = { state = "checking", detail = nil }
	self.deps.spawn(function()
		local ok, code, info = self.session:companion_status(port)
		if ok then
			st.export.companion = { state = "reachable", detail = string.format("%d recipient(s), token valid %ds", info.recipients or 0, info.token_seconds_left or 0) }
		elseif code == "no_http" then
			st.export.companion = { state = "no_http", detail = "This executor cannot make HTTP requests." }
		else
			st.export.companion = { state = "unreachable", detail = tostring(info) .. " Start the companion app, then check again." }
		end
		self:_end("companion.check")
	end)
end

local ENCRYPT_ADVICE = {
	no_http = "This executor has no HTTP function, so it cannot reach the companion. Nothing was saved.",
	bad_token = "Paste the one-time pairing token shown in the companion (it starts with ssp_).",
	http_401 = "The pairing token was rejected or expired. Restart the companion to get a new one.",
	http_403 = "The companion refused the request. Restart it and try again.",
	http_409 = "The companion already has this report or token. Restart it for a fresh token.",
	http_413 = "The report is larger than the companion accepts.",
	http_422 = "The companion rejected the report; nothing was stored.",
	http_500 = "The companion could not encrypt the report. Nothing was stored.",
	http_error = "The companion is not reachable. Start the companion app, then try again.",
	cipher_mismatch = "The ciphertext returned by the companion failed its integrity check and was discarded.",
}

H["export.encrypt"] = function(self)
	local st = self.store.state
	local ex = st.export
	if not ex.report then self:_feedback("error", "Failed", "Build the report first.") return end
	local port = port_of(st)
	if not port then self:_feedback("error", "Failed", "Enter a port between 1 and 65535.") return end
	if not self:_begin("export.encrypt") then return end
	ex.feedback = nil
	ex.encryption = { state = "encrypting", detail = "sending to 127.0.0.1:" .. port }
	self.deps.spawn(function()
		local ok, code = self.session:save_encrypted({ token = ex.token_input, port = port, return_ciphertext = true })
		if ok then
			local c = self.session.last_cipher
			ex.cipher = { file_name = c.file_name, sha256 = c.sha256, bytes = c.bytes, created_at = c.created_at }
			ex.encryption = { state = "encrypted", detail = "stored by the companion" }
			ex.token_input = "" -- single use: never keep it around
			self:_feedback("success", "Encrypted", "The companion stored the encrypted files. Export or copy the text below if you need it elsewhere.")
		else
			ex.encryption = { state = "failed", detail = tostring(code) }
			self:_feedback("error", "Failed", ENCRYPT_ADVICE[code] or ("Nothing was saved (" .. tostring(code) .. ")."))
		end
		self:_end("export.encrypt")
	end)
end

H["export.save"] = function(self)
	if not self:_begin("export.save") then return end
	local ok, res = self.session:export_ciphertext_txt()
	if ok then self:_feedback("success", "Saved", "Wrote " .. res .. " and its .sha256 sidecar (encrypted text only).")
	else self:_feedback("error", "Failed", tostring(res) .. " Nothing was written.") end
	self:_end("export.save")
end

H["export.meta"] = function(self)
	if not self:_begin("export.meta") then return end
	local ok, res = self.session:export_report_metadata()
	if ok then self:_feedback("success", "Saved", "Wrote " .. res .. " (file name, SHA-256, timestamps; no report content).")
	else self:_feedback("error", "Failed", tostring(res) .. " Nothing was written.") end
	self:_end("export.meta")
end

-- Clear Session: wipes the in-memory audit and every view state that mirrors it. The single-use token input is
-- cleared with everything else. Reports already exported stay on disk.
H["export.clear"] = function(self)
	local st = self.store.state
	self.session:discard()
	st.scan = { state = "idle", visited = nil, observed = nil, candidates = nil, elapsed = 0, error = nil, started = nil, cancel_requested = false }
	st.findings.list, st.findings.selected, st.findings.page = {}, nil, 1
	st.manifest.state, st.manifest.summary, st.manifest.tests, st.manifest.gate_reasons, st.manifest.plan = "none", nil, {}, {}, nil
	st.manifest.dry_run_done, st.manifest.run_state, st.manifest.confirm_open, st.manifest.confirm_input, st.manifest.reset_ack = false, "idle", false, "", false
	st.export.report, st.export.cipher, st.export.feedback = nil, nil, nil
	st.export.encryption = { state = "idle", detail = nil }
	st.export.companion = { state = "unknown", detail = nil }
	st.export.token_input = ""
	st.snapshot = { path_input = st.snapshot.path_input, state = "idle", detail = nil, diff = nil }
	refresh_explorer(st, self.session)
	st.info = self.session:ui_info()
	Store.log(st, "warn", "Session cleared: audit data discarded from memory. Exported files were not deleted.", now(self))
end

local function copy_action(self, what)
	local c = self.session.last_cipher
	if not c then self:_feedback("error", "Failed", "There is nothing to copy yet.") return end
	local text = (what == "sha") and c.sha256 or c.armored
	local ok, err = self.session:copy(text)
	if ok then
		self:_feedback("success", "Copied", (what == "sha") and "SHA-256 copied to the clipboard." or string.format("Ciphertext copied (%d bytes). It is encrypted; only a listed recipient can read it.", #text))
	else
		self:_feedback("error", "Failed", tostring(err) .. " Use Export Encrypted TXT instead.")
	end
end
H["export.copy_sha"] = function(self) copy_action(self, "sha") end
H["export.copy_cipher"] = function(self) copy_action(self, "cipher") end

-- ---------------------------------------------------------------- settings
H["settings.toggle"] = function(self, which)
	local cfg = self.session.config
	if which == "minimize" then cfg.minimize = not cfg.minimize
	elseif which == "anonymize" then cfg.anonymize_tester = not cfg.anonymize_tester end
	self.store.state.info = self.session:ui_info()
end

-- Graph page: select a container to see its remotes (data comes from the bounded cached listing)
H["graph.select"] = function(self, path)
	local g = self.store.state.graph
	g.selected = (g.selected == path) and nil or path
	g.page = 1
end
H["graph.page"] = function(self, d) local g = self.store.state.graph g.page = math.max(1, g.page + (d or 0)) end

-- Session Compare page: delete a snapshot file (only when the executor really can)
H["snapshot.delete"] = function(self)
	local st = self.store.state
	if not self:_begin("snapshot.delete") then return end
	local ok, res = self.session:delete_snapshot(st.snapshot.path_input)
	st.snapshot.state = ok and "deleted" or "error"
	st.snapshot.detail = tostring(res)
	Store.log(st, ok and "warn" or "error", ok and ("Snapshot deleted: " .. tostring(res)) or tostring(res), now(self))
	self:_end("snapshot.delete")
end

-- performance profile switch (Settings page)
H["settings.profile"] = function(self, key)
	self.session:set_profile(key)
	self.store.state.info = self.session:ui_info()
end

-- the table paging facts computed by the last render (see Shell.build meta), applied outside the view
function Ctl:apply_meta(meta)
	local st = self.store.state
	if meta and meta.table and st.page == "findings" and st.findings.page ~= meta.table.page_index then
		st.findings.page = meta.table.page_index
		return true
	end
	if meta and meta.table and st.page == "tests" and st.manifest.page ~= meta.table.page_index then
		st.manifest.page = meta.table.page_index
		return true
	end
	return false
end

Ctl.handlers = H
return Ctl
end
__factories["client.ui.layout"] = function(require)
-- Pure geometry. Everything snaps to a 4px grid; spacing comes from design tokens. No Roblox API here.
local tokens = require("client.ui.tokens")

local L = {}
local S, Z = tokens.space, tokens.size

local function snap(v) return math.floor(v / 4) * 4 end
L.snap = snap

local function clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

function L.rect(x, y, w, h) return { x = x, y = y, w = w, h = h } end

-- App window inside the viewport: centred, never edge to edge, never smaller than the minimum.
function L.window(vw, vh)
	local w = snap(clamp(vw - 2 * Z.screen_margin, Z.min_window_w, Z.max_window_w))
	local h = snap(clamp(vh - 2 * Z.screen_margin, Z.min_window_h, Z.max_window_h))
	return { x = snap((vw - w) / 2), y = snap((vh - h) / 2), w = w, h = h }
end

function L.compact(win_w) return win_w < Z.compact_below_window_w end

-- shell regions in window-local coordinates
function L.shell(win)
	local sw = L.compact(win.w) and Z.sidebar_w_compact or Z.sidebar_w
	local content = { x = sw, y = Z.header_h, w = win.w - sw, h = win.h - Z.header_h }
	return {
		header = { x = 0, y = 0, w = win.w, h = Z.header_h },
		sidebar = { x = 0, y = Z.header_h, w = sw, h = win.h - Z.header_h },
		content = content,
		inner = { x = Z.content_pad, y = Z.content_pad, w = content.w - 2 * Z.content_pad, h = content.h - 2 * Z.content_pad }, -- relative to content
		compact = L.compact(win.w),
	}
end

-- inset a rect by n on every side
function L.inset(r, n) return { x = r.x + n, y = r.y + n, w = r.w - 2 * n, h = r.h - 2 * n } end

-- vertical stack: take(h) returns the next rect and advances the cursor; gap() adds extra space
function L.stack(rect, gap)
	local self = { rect = rect, y = rect.y, gap = gap or S.lg, first = true }
	function self:take(h)
		if not self.first then self.y += self.gap end
		self.first = false
		local r = { x = self.rect.x, y = self.y, w = self.rect.w, h = h }
		self.y += h
		return r
	end
	function self:remaining() return self.rect.y + self.rect.h - self.y - (self.first and 0 or self.gap) end
	function self:used() return self.y - self.rect.y end
	return self
end

-- split a width into n columns; weights optional. widths sum exactly to rect.w - gap*(n-1) and are multiples of 4 (last takes the remainder)
function L.columns(rect, n, gap, weights)
	gap = gap or S.lg
	weights = weights or {}
	local total_w = rect.w - gap * (n - 1)
	local sum = 0
	for i = 1, n do sum += (weights[i] or 1) end
	local out, x, used = {}, rect.x, 0
	for i = 1, n do
		local w = (i == n) and (total_w - used) or snap(total_w * (weights[i] or 1) / sum)
		out[i] = { x = x, y = rect.y, w = w, h = rect.h }
		x += w + gap
		used += w
	end
	return out
end

-- horizontal row of fixed-width items aligned to the RIGHT edge of `rect` (action rows). widths in order left->right.
function L.right_aligned(rect, widths, h, gap)
	gap = gap or S.sm
	local total = 0
	for _, w in ipairs(widths) do total += w end
	total += gap * (#widths - 1)
	local x = rect.x + rect.w - total
	local out = {}
	for i, w in ipairs(widths) do
		out[i] = { x = x, y = rect.y, w = w, h = h }
		x += w + gap
	end
	return out
end

return L
end
__factories["client.ui.measure"] = function(require)
-- Approximate text metrics used for layout validation and truncation decisions OUTSIDE Roblox.
-- In Roblox the renderer additionally sets TextTruncate = AtEnd, so an estimate that is a little off cannot cause overlap.
-- The estimate is deliberately slightly WIDER than Gotham so a layout that passes here has headroom.
local M = {}

local NARROW = "ijl.,:;'|!()[]/ ft"
local WIDE = "MWmw@%"

local function char_em(c, font)
	if font == "mono" then return 0.62 end
	local w
	if string.find(NARROW, c, 1, true) then w = 0.34
	elseif string.find(WIDE, c, 1, true) then w = 0.92
	elseif string.find(c, "%u") then w = 0.70
	elseif string.find(c, "%d") then w = 0.62
	else w = 0.58 end
	if font == "ui_bold" then w = w * 1.07 elseif font == "ui_medium" then w = w * 1.03 end
	return w
end

-- width in pixels of a single line
function M.width(text, size, font)
	text = tostring(text)
	if not utf8.len(text) then return math.ceil(#text * 0.6 * size) end -- invalid UTF-8 from a game name: assume wide
	local total = 0
	for _, cp in utf8.codes(text) do
		local ch = utf8.char(cp)
		total += (#ch > 1) and 1.0 or char_em(ch, font)
	end
	return math.ceil(total * size)
end

-- number of lines when wrapped at `width` pixels (word wrap)
function M.lines(text, size, font, width)
	local lines, cur = 1, 0
	local space = M.width(" ", size, font)
	for word in string.gmatch(tostring(text), "%S+") do
		local w = M.width(word, size, font)
		if cur > 0 and cur + space + w > width then
			lines += 1
			cur = w
		else
			cur = (cur > 0) and (cur + space + w) or w
		end
		while cur > width and width > 0 do -- very long unbroken word: Roblox breaks it across lines
			lines += 1
			cur -= width
		end
	end
	return lines
end

return M
end
__factories["client.ui.pages_a"] = function(require)
-- Pages: Overview, Scanner, Settings/About. Each builder returns (nodes, content_bottom) in content-relative coordinates.
local C = require("client.ui.components")
local V = require("client.ui.viewmodel")
local layout = require("client.ui.layout")
local tokens = require("client.ui.tokens")

local P = {}
local SP, SZ = tokens.space, tokens.size

local function title(id, R, text, right_text)
	local nodes = { C.line_text(id .. ".title", R.x, R.y, R.w, text, { type = "title" }) }
	if right_text then
		local w = 240
		nodes[1].rect.w = R.w - w - SP.lg
		nodes[#nodes + 1] = C.line_text(id .. ".count", R.x + R.w - w, R.y + 8, w, right_text, { type = "caption", color = "text_muted", align = "right", numeric = true })
	end
	return nodes
end
P.title = title

local function append(dst, src) for _, n in ipairs(src) do dst[#dst + 1] = n end end

-- labelled input row (same shape as pages_b.export's form_row; kept local to avoid cross-module coupling)
local function form_row(id, inner, y, label, input)
	local lw = 128
	local nodes = { C.line_text(id .. ".l", inner.x, y + 8, lw - SP.sm, label, { type = "caption", color = "text_muted", truncate = true }) }
	input.rect = { x = inner.x + lw, y = y, w = input.w or (inner.w - lw), h = 32 }
	input.w = nil
	input.id = id .. ".i"
	input.kind = "input"
	nodes[#nodes + 1] = input
	return nodes
end

P.SCAN_BADGE = {
	idle = { "Idle", "neutral" }, scanning = { "Scanning", "accent" }, complete = { "Complete", "success" },
	cancelled = { "Cancelled", "warning" }, error = { "Error", "error" },
}
P.COMPANION_BADGE = {
	unknown = { "Not checked", "neutral" }, checking = { "Checking", "accent" }, reachable = { "Reachable", "success" },
	unreachable = { "Unreachable", "error" }, no_http = { "No HTTP", "warning" },
}
P.ENCRYPTION_BADGE = {
	idle = { "Not encrypted", "neutral" }, encrypting = { "Encrypting", "accent" }, encrypted = { "Encrypted", "success" }, failed = { "Failed", "error" },
}
P.REPORT_BADGE = { none = { "Not built", "neutral" }, ready = { "Built", "accent" } }
P.MANIFEST_BADGE = { none = { "None", "neutral" }, valid = { "Valid", "success" }, invalid = { "Invalid", "error" } }

-- ---------------------------------------------------------------- Overview
function P.overview(ctx)
