		node.children[2] = C.line_text("ov.tile" .. i .. ".v", SZ.panel_pad, SZ.panel_pad + 16, cols[col + 1].w - 32, t[2], { type = "title", truncate = true })
		nodes[#nodes + 1] = node
	end
	y += rows * SZ.stat_h + (rows - 1) * SP.lg + SP.lg

	local info = st.info
	local integ = info.integrity == "verified" and { "Hash pinned", "success", "matches the loader pin" } or { "Not verified", "warning", "loader not used" }
	local scan_b = P.SCAN_BADGE[st.scan.state]
	local comp_b = P.COMPANION_BADGE[st.export.companion.state]
	local rep_b = st.export.report and P.REPORT_BADGE.ready or P.REPORT_BADGE.none
	local enc_b = P.ENCRYPTION_BADGE[st.export.encryption.state]
	local man_b = P.MANIFEST_BADGE[m.state]
	local left_rows = {
		{ label = "Version", value = string.format("%s (build %s)", info.version, info.build_id), mono = false },
		{ label = "Integrity", badge = integ[1], tone = integ[2], text = integ[3] },
		{ label = "Audit mode", value = info.mode },
		{ label = "PlaceId", value = V.num(info.place_id), mono = true },
		{ label = "GameId", value = V.num(info.game_id), mono = true },
		{ label = "Executor", badge = "Unverified", tone = "warning", text = info.executor },
	}
	local live_state = st.live.running and "running" or (info.live and info.live.supported == false and "unavailable" or "stopped")
	local live_text = st.live.running and "newly replicated objects are recorded" or nil
	local right_rows = {
		{ label = "Live observation", badge = V.LIVE_LABEL[live_state], tone = V.LIVE_TONE[live_state], text = live_text },
		{ label = "Companion", badge = comp_b[1], tone = comp_b[2], text = st.export.companion.detail },
		{ label = "Scan", badge = scan_b[1], tone = scan_b[2], text = st.scan.state == "scanning" and (V.num(st.scan.visited) .. " visited") or nil },
		{ label = "Manifest", badge = man_b[1], tone = man_b[2], text = m.summary and m.summary.manifest_id or nil },
		{ label = "Report", badge = rep_b[1], tone = rep_b[2], text = st.export.report and st.export.report.file_name or nil },
		{ label = "Encryption", badge = enc_b[1], tone = enc_b[2] },
	}
	local ph = 48 + C.kv_height(#left_rows) + SZ.panel_pad
	local wide = R.w >= 640
	local cols = wide and layout.columns({ x = R.x, y = y, w = R.w, h = ph }, 2, SP.lg) or { { x = R.x, y = y, w = R.w, h = ph }, { x = R.x, y = y + ph + SP.lg, w = R.w, h = ph } }
	local pl, il = C.panel("ov.session", cols[1], "Session")
	append(pl.children, (C.kv("ov.session.kv", il, left_rows)))
	local pr, ir = C.panel("ov.status", cols[2], "Status")
	append(pr.children, (C.kv("ov.status.kv", ir, right_rows)))
	nodes[#nodes + 1] = pl
	nodes[#nodes + 1] = pr
	local ay = wide and (y + ph + SP.lg) or (y + 2 * ph + 2 * SP.lg)
	local ah = math.max(120, R.y + R.h - ay)
	local act, ai = C.panel("ov.activity", { x = R.x, y = ay, w = R.w, h = ah }, "Recent activity")
	local cap = math.max(1, math.floor(ai.h / 24))
	if #st.log == 0 then
		append(act.children, C.empty_state("ov.activity.empty", ai, "Nothing has happened yet", "Events from scans, tests and exports appear here.", nil))
	else
		local ly = ai.y
		for i = math.max(1, #st.log - cap + 1), #st.log do
			local e = st.log[i]
			act.children[#act.children + 1] = C.text("ov.act." .. i .. ".t", { x = ai.x, y = ly + 4, w = 72, h = 16 }, V.clock(e.t), { type = "mono", color = "text_muted" })
			act.children[#act.children + 1] = C.text("ov.act." .. i .. ".m", { x = ai.x + 80, y = ly + 4, w = ai.w - 80, h = 16 }, e.text, { type = "mono", truncate = true,
				color = e.level == "error" and "error" or (e.level == "warn" and "warning" or "text") })
			ly += 24
		end
	end
	nodes[#nodes + 1] = act
	return nodes, ay + ah
end

-- ---------------------------------------------------------------- Scanner
function P.scanner(ctx)
	local R, st = ctx.R, ctx.state
	local sc, busy = st.scan, st.busy
	local nodes = title("sc", R, "Scanner")
	local y = R.y + 28 + SP.lg
	local badge = P.SCAN_BADGE[sc.state]
	local bw = C.badge_w(badge[1])
	local desc = "Reads the objects your client can already see (remotes, prompts, detectors, sensitive-looking values) and ranks candidates for review. It sends nothing to the game."
	local inner_w = R.w - 2 * SZ.panel_pad
	local para_h = C.paragraph("probe", 0, 0, inner_w, desc, { color = "text_muted" }).rect.h
	local err_h = (sc.state == "error" or sc.state == "cancelled") and 28 or 0
	local inner_h = para_h + SP.lg + 48 + err_h + SP.lg + 32 + SP.md + 32
	local ph = 48 + inner_h + SZ.panel_pad
	local panel, inner = C.panel("sc.panel", { x = R.x, y = y, w = R.w, h = ph }, "Passive scan", { title_right_w = bw + SP.sm })
	local b = C.badge("sc.state", R.w - SZ.panel_pad - bw, SZ.panel_pad, badge[1], badge[2])
	panel.children[#panel.children + 1] = b
	local cy = inner.y
	panel.children[#panel.children + 1] = C.paragraph("sc.desc", inner.x, cy, inner_w, desc, { color = "text_muted" })
	cy += para_h + SP.lg
	local mcols = layout.columns({ x = inner.x, y = cy, w = inner.w, h = 48 }, 4, SP.lg)
	local metrics = { { "Objects visited", V.num(sc.visited) }, { "Observed", V.num(sc.observed) }, { "Candidates", V.num(sc.candidates) }, { "Elapsed", V.duration(sc.elapsed) } }
	for i, m in ipairs(metrics) do
		panel.children[#panel.children + 1] = C.line_text("sc.m" .. i .. ".l", mcols[i].x, cy, mcols[i].w, m[1], { type = "caption", color = "text_muted", truncate = true })
		panel.children[#panel.children + 1] = C.line_text("sc.m" .. i .. ".v", mcols[i].x, cy + 16, mcols[i].w, m[2], { type = "title", truncate = true })
	end
	cy += 48
	if err_h > 0 then
		local label, tone, msg = "Error", "error", sc.error or "The scan failed."
		if sc.state == "cancelled" then label, tone, msg = "Cancelled", "warning", "Stopped by you. Results so far are partial and are marked as such in reports." end
		append(panel.children, C.notice("sc.note", { x = inner.x, y = cy + SP.sm, w = inner.w, h = 16 }, tone, label, msg))
		cy += err_h
	end
	cy += SP.lg
	local scanning = sc.state == "scanning"
	local w1, w2 = C.button_w("Stop Scan"), C.button_w(scanning and "Scanning..." or "Start Passive Scan")
	local rs = layout.right_aligned({ x = inner.x, y = cy, w = inner.w, h = 32 }, { w1, w2 }, 32)
	panel.children[#panel.children + 1] = C.button("sc.stop", rs[1], "Stop Scan", { style = "secondary", disabled = not scanning, action = { name = "scan.stop" } })
	panel.children[#panel.children + 1] = C.button("sc.start", rs[2], scanning and "Scanning..." or "Start Passive Scan",
		{ style = "primary", role = "primary_action", loading = scanning, action = { name = "scan.start" } })
	cy += 32 + SP.md
	-- second row: live observation + inventory/session maintenance (right-aligned like every main action row)
	local live_label = st.live.running and "Stop Live" or "Start Live"
	local l1w, r1w, c1w = C.button_w(live_label), C.button_w("Refresh Inventory"), C.button_w("Clear Current Session")
	local rs2 = layout.right_aligned({ x = inner.x, y = cy, w = inner.w, h = 32 }, { l1w, r1w, c1w }, 32)
	panel.children[#panel.children + 1] = C.button("sc.live", rs2[1], live_label,
		{ style = "secondary", disabled = scanning, action = { name = "live.toggle" } })
	panel.children[#panel.children + 1] = C.button("sc.refresh", rs2[2], "Refresh Inventory",
		{ style = "secondary", disabled = scanning or not sc.observed, loading = busy["scan.refresh"], action = { name = "scan.refresh" } })
	panel.children[#panel.children + 1] = C.button("sc.clear", rs2[3], "Clear Current Session", { style = "danger", action = { name = "export.clear" } })
	nodes[#nodes + 1] = panel
	y += ph + SP.lg

	-- snapshot panel (0.3.0): save the current remote surface fingerprint, compare against a saved one
	local sn = st.snapshot
	local snap_rows = {}
	if sn.diff then
		snap_rows = {
			{ label = "Added remotes", value = tostring(sn.diff.added_count), mono = false },
			{ label = "Removed remotes", value = tostring(sn.diff.removed_count), mono = false },
			{ label = "Compared with snapshot from", value = tostring(sn.diff.previous_created_utc), mono = true },
		}
		for i = 1, math.min(3, sn.diff.added_count) do
			snap_rows[#snap_rows + 1] = { label = "+ " .. i, value = sn.diff.added[i].path, mono = true }
		end
		for i = 1, math.min(3, sn.diff.removed_count) do
			snap_rows[#snap_rows + 1] = { label = "- " .. i, value = sn.diff.removed[i].path, mono = true }
		end
	else
		snap_rows = { { label = "Status", value = sn.state == "saved" and ("Snapshot written: " .. tostring(sn.detail)) or "No comparison yet" } }
	end
	if sn.state == "error" and sn.detail then
		snap_rows[#snap_rows + 1] = { label = "Problem", value = sn.detail, mono = false }
	end
	local sh = 48 + C.kv_height(#snap_rows) + SP.md + 32 + SP.md + 32 + SZ.panel_pad
	local sp, si = C.panel("sc.snap", { x = R.x, y = y, w = R.w, h = sh }, "Snapshot and comparison (remote surface fingerprint)")
	append(sp.children, (C.kv("sc.snap.kv", si, snap_rows, 200)))
	local sy = si.y + C.kv_height(#snap_rows) + SP.md
	append(sp.children, form_row("sc.snap.path", si, sy, "Snapshot file", { text = sn.path_input, placeholder = "ShadowScan/out/snapshot-....json", action = { name = "snapshot.path" }, mono = true }))
	sy += 32 + SP.md
	local sbw1, sbw2 = C.button_w("Save Snapshot"), C.button_w("Compare with Snapshot")
	local srs = layout.right_aligned({ x = si.x, y = sy, w = si.w, h = 32 }, { sbw1, sbw2 }, 32)
	sp.children[#sp.children + 1] = C.button("sc.snap.save", srs[1], "Save Snapshot",
		{ style = "secondary", disabled = st.scan.state ~= "complete" and st.scan.state ~= "cancelled", loading = st.busy["snapshot.save"], action = { name = "snapshot.save" } })
	sp.children[#sp.children + 1] = C.button("sc.snap.compare", srs[2], "Compare with Snapshot",
		{ style = "secondary", disabled = st.scan.state ~= "complete" and st.scan.state ~= "cancelled", loading = st.busy["snapshot.compare"], action = { name = "snapshot.compare" } })
	nodes[#nodes + 1] = sp
	y += sh + SP.lg

	-- activity log: fills the remaining height (at least 160)
	local lh = math.max(160, R.y + R.h - y)
	local lp, li = C.panel("sc.log", { x = R.x, y = y, w = R.w, h = lh }, "Activity")
	local cap = math.max(1, math.floor(li.h / 24))
	local entries = st.log
	if #entries == 0 then
		append(lp.children, C.empty_state("sc.log.empty", li, "No activity yet", "Start a passive scan. Events appear here as they happen.", nil))
	else
		local first = math.max(1, #entries - cap + 1)
		local ly = li.y
		for i = first, #entries do
			local e = entries[i]
			local tone = e.level == "error" and "error" or (e.level == "warn" and "warning" or "text_muted")
			local color = e.level == "error" and "error" or (e.level == "warn" and "warning" or "text_muted")
			lp.children[#lp.children + 1] = C.text("sc.log." .. i .. ".t", { x = li.x, y = ly + 4, w = 72, h = 16 }, V.clock(e.t), { type = "mono", color = "text_muted" })
			lp.children[#lp.children + 1] = C.text("sc.log." .. i .. ".l", { x = li.x + 72, y = ly + 4, w = 56, h = 16 }, string.upper(e.level), { type = "mono", color = color })
			lp.children[#lp.children + 1] = C.text("sc.log." .. i .. ".m", { x = li.x + 128, y = ly + 4, w = li.w - 128, h = 16 }, e.text, { type = "mono", truncate = true })
			ly += 24
		end
	end
	nodes[#nodes + 1] = lp
	return nodes, y + lh
end

-- ---------------------------------------------------------------- Settings / About
local function toggle_row(id, inner, y, label, desc, value, action)
	local nodes = {}
	local bw = 72
	nodes[#nodes + 1] = C.line_text(id .. ".l", inner.x, y, inner.w - bw - SP.lg, label, { type = "body", truncate = true })
	nodes[#nodes + 1] = C.line_text(id .. ".d", inner.x, y + 20, inner.w - bw - SP.lg, desc, { type = "caption", color = "text_muted", truncate = true })
	nodes[#nodes + 1] = C.button(id .. ".t", { x = inner.x + inner.w - bw, y = y + 4, w = bw, h = 32 }, value and "On" or "Off", { style = "toggle", selected = value, action = action })
	return nodes
end

function P.settings(ctx)
	local R, st = ctx.R, ctx.state
	local info, caps = st.info, st.info.caps
	local nodes = title("se", R, "Settings / About")
	local y = R.y + 28 + SP.lg
	local wide = R.w >= 720
	local lw = wide and (R.w - SP.lg) / 2 or R.w
	local cols = wide and layout.columns({ x = R.x, y = y, w = R.w, h = 0 }, 2, SP.lg) or { { x = R.x, y = y, w = R.w, h = 0 }, { x = R.x, y = 0, w = R.w, h = 0 } }

	-- Preferences
	local pref_h = 48 + 40 + SP.md + 40 + SP.md + 40 + SZ.panel_pad
	local pref, pi = C.panel("se.pref", { x = cols[1].x, y = y, w = cols[1].w, h = pref_h }, "Preferences")
	local py = pi.y
	append(pref.children, toggle_row("se.min", pi, py, "Data minimisation", "List only observations that back a finding.", st.info.config.minimize, { name = "settings.toggle", arg = "minimize" }))
	py += 40 + SP.md
	append(pref.children, toggle_row("se.anon", pi, py, "Anonymise tester", "Reports say 'anonymous' instead of a label.", st.info.config.anonymize, { name = "settings.toggle", arg = "anonymize" }))
	py += 40 + SP.md
	pref.children[#pref.children + 1] = C.line_text("se.port.l", pi.x, py, pi.w - 120 - SP.lg, "Companion port", { type = "body", truncate = true })
	pref.children[#pref.children].rect.y = py + 4
	pref.children[#pref.children + 1] = { id = "se.port.i", kind = "input", rect = { x = pi.x + pi.w - 120, y = py, w = 120, h = 32 }, text = st.export.port_input, action = { name = "export.port" }, mono = true }
	nodes[#nodes + 1] = pref

	-- Performance profile (0.4.0): LOW IMPACT / BALANCED / FAST
	local prof_y = wide and y or (y + pref_h + SP.lg)
	local prof_panel_h = 48 + 24 + SP.md + 32 + 24 + SZ.panel_pad
	local prof, prf = C.panel("se.profile", { x = cols[1].x, y = prof_y, w = cols[1].w, h = prof_panel_h }, "Performance profile")
	local pfy = prf.y
	prof.children[#prof.children + 1] = C.line_text("se.profile.desc", prf.x, pfy, prf.w, tostring(st.info.profile_label or "Balanced") .. " - batch budget is a target, not a frame-time guarantee", { type = "caption", color = "text_muted", truncate = true })
	pfy += 24 + SP.md
	local px = prf.x
	local profiles_list = { { key = "low_impact", label = "Low Impact" }, { key = "balanced", label = "Balanced" }, { key = "fast", label = "Fast" } }
	for _, opt in ipairs(profiles_list) do
		local w = math.max(72, C.button_w(opt.label, 72) - 8)
		prof.children[#prof.children + 1] = C.button("se.profile." .. opt.key, { x = px, y = pfy, w = w, h = 32 }, opt.label,
			{ style = "segment", selected = (st.info.profile == opt.key), action = { name = "settings.profile", arg = opt.key } })
		px += w + SP.xs
	end
	nodes[#nodes + 1] = prof
	local prof_bottom = prof_y + prof_panel_h + SP.lg

	-- Capability report (0.4.0): every probed capability with its honest status
	local COMP_STATUS_TONE = { supported = "success", partial = "accent", unsupported = "warning", not_tested = "neutral", failed_init = "error" }
	local cap_rows = {}
	local counts = st.info.compat or {}
	local summary = counts.supported and string.format("%d supported, %d unsupported, %d failed", counts.supported, counts.unsupported, counts.failed_init) or "not probed"
	cap_rows[1] = { label = "Summary", value = summary }
	for _, it in ipairs(st.info.compat_items or {}) do
		cap_rows[#cap_rows + 1] = { label = it.capability, badge = it.status, tone = COMP_STATUS_TONE[it.status] or "neutral", text = it.detail }
	end
	local cap_h = 48 + C.kv_height(#cap_rows) + SZ.panel_pad
	local c2y = wide and y or prof_bottom
	local comp, ci = C.panel("se.capreport", { x = cols[2].x, y = c2y, w = cols[2].w, h = cap_h }, "Runtime capability report")
	append(comp.children, (C.kv("se.capreport.kv", ci, cap_rows, 152)))
	nodes[#nodes + 1] = comp
	local right_bottom = c2y + cap_h + SP.lg
	y = wide and math.max(prof_bottom, right_bottom) or math.max(prof_bottom, right_bottom)

	-- Compatibility
	local function yn(v) return v and { "Available", "success" } or { "Missing", "warning" } end
	local rows = {
		{ label = "Executor", badge = "Unverified", tone = "warning", text = info.executor },
		{ label = "HTTP request", badge = yn(caps.http)[1], tone = yn(caps.http)[2] },
		{ label = "File read / write", badge = yn(caps.readfile and caps.writefile)[1], tone = yn(caps.readfile and caps.writefile)[2] },
		{ label = "Clipboard", badge = yn(caps.clipboard)[1], tone = yn(caps.clipboard)[2] },
		{ label = "GUI host", value = caps.gui_host or "-" },
		{ label = "Bundle hash", value = info.bundle_sha and (string.sub(info.bundle_sha, 1, 20) .. "...") or "not verified", mono = true },
	}
	local comp_h = 48 + C.kv_height(#rows) + SZ.panel_pad
	local c2y = wide and y or (y + pref_h + SP.lg)
	local comp, ci = C.panel("se.compat", { x = cols[2].x, y = c2y, w = cols[2].w, h = comp_h }, "Compatibility")
	append(comp.children, (C.kv("se.compat.kv", ci, rows)))
	nodes[#nodes + 1] = comp
	y = wide and (y + math.max(pref_h, comp_h) + SP.lg) or (c2y + comp_h + SP.lg)

	-- About / limits
	local lines = {
		"ShadowScan " .. info.version .. " (build " .. info.build_id .. ") is verified only against a mock Roblox environment. No executor has been tested.",
		"It sees what your client sees. Server code, server-side validation and unreplicated data are invisible to it.",
		"A candidate is not a vulnerability. Only a CONFIRMED verdict from an approved test with verifiable evidence is.",
		"Active tests need a developer-approved manifest. Reports are only ever saved encrypted.",
	}
	local inner_w = R.w - 2 * SZ.panel_pad
	local total = 0
	local paras = {}
	for i, l in ipairs(lines) do
		local p = C.paragraph("se.about." .. i, 0, 0, inner_w, l, { color = i == 1 and "text" or "text_muted" })
		paras[i] = p
		total += p.rect.h + SP.sm
	end
	local doc = C.paragraph("se.docs", 0, 0, inner_w, "Documentation: README.md, docs/LIMITATIONS.md, docs/MANIFEST.md, docs/RECIPIENTS.md, docs/REPORT.md", { type = "caption", color = "text_muted" })
	local ah = 48 + total + doc.rect.h + SZ.panel_pad
	local about, ai = C.panel("se.about", { x = R.x, y = y, w = R.w, h = ah }, "About and limits")
	local ay = ai.y
	for _, p in ipairs(paras) do
		p.rect.x, p.rect.y = ai.x, ay
		about.children[#about.children + 1] = p
		ay += p.rect.h + SP.sm
	end
	doc.rect.x, doc.rect.y = ai.x, ay
	about.children[#about.children + 1] = doc
	nodes[#nodes + 1] = about
	return nodes, y + ah
end

return P
end
__factories["client.ui.pages_b"] = function(require)
-- Pages: Findings, Approved Tests, Secure Export.
local C = require("client.ui.components")
local V = require("client.ui.viewmodel")
local layout = require("client.ui.layout")
local tokens = require("client.ui.tokens")
local pa = require("client.ui.pages_a")
local measure = require("client.ui.measure")

local P = {}
local SP, SZ = tokens.space, tokens.size
local title = pa.title

local function append(dst, src) for _, n in ipairs(src) do dst[#dst + 1] = n end end

-- ---------------------------------------------------------------- Findings
local FIND_COLUMNS = {
	{ key = "id", label = "ID", w = 80, mono = true, sortable = true, priority = 0 },
	{ key = "object", label = "Object", min_w = 120, sortable = true, priority = 0 },
	{ key = "category", label = "Category", w = 168, sortable = true, priority = 2, muted = true },
	{ key = "severity", label = "Severity", w = 96, sortable = true, priority = 0, badge = function(v) return V.SEVERITY_TONE[({ HIGH = "high", MEDIUM = "medium", LOW = "low", INFO = "informational" })[v]] end },
	{ key = "confidence", label = "Confidence", w = 104, sortable = true, priority = 1, muted = true },
	{ key = "verdict", label = "Verdict", w = 112, sortable = true, priority = 0, badge = function(v)
		for k, label in pairs(V.VERDICT_LABEL) do if label == v then return V.VERDICT_TONE[k] end end
		return "neutral"
	end },
}

-- rows that fit in the findings table for a given window height (the controller needs this to clamp paging)
function P.findings_page_size(win_h, compact)
	local content_h = win_h - SZ.header_h
	local R_h = content_h - 2 * SZ.content_pad
	local toolbar = compact and 72 or 32
	local body_h = R_h - 28 - SP.lg - toolbar - SP.lg
	return C.table_capacity(body_h, 1e9)
end

local function field(nodes, id, x, y, w, label, text, o)
	o = o or {}
	nodes[#nodes + 1] = C.line_text(id .. ".l", x, y, w, label, { type = "caption", color = "text_muted" })
	local p = C.paragraph(id .. ".v", x, y + 16, w, text, { type = o.mono and "mono" or "body", color = o.color or "text" })
	nodes[#nodes + 1] = p
	return y + 16 + p.rect.h + SP.md
end

local function detail_panel(id, rect, f, back)
	local node, inner = C.panel(id, rect, "Details", { title_right_w = back and 96 or 0 })
	if back then
		node.children[#node.children + 1] = C.button(id .. ".back", { x = rect.w - SZ.panel_pad - 96, y = 8, w = 96, h = 32 }, "Back", { style = "ghost", action = { name = "findings.select", arg = nil }, compact_ok = true })
		node.children[#node.children].rect.y = 8
		node.children[#node.children].bleed = true
	end
	if not f then
		append(node.children, C.empty_state(id .. ".none", inner, "No finding selected", "Select a row to see its evidence, what is unknown and how to verify it.", nil))
		return node
	end
	local sc = C.scroll(id .. ".scroll", { x = inner.x, y = inner.y, w = inner.w, h = inner.h }, 0)
	local w = inner.w - 8
	local ch, y = sc.children, 0
	ch[#ch + 1] = C.line_text(id .. ".id", 0, y, w, f.finding_id, { type = "mono", color = "text_muted" })
	y += 16
	ch[#ch + 1] = C.line_text(id .. ".name", 0, y, w, f.object_name, { type = "heading", truncate = true })
	y += 20 + SP.sm
	local b1, w1 = C.badge(id .. ".sev", 0, y, V.SEVERITY_LABEL[f.severity], V.SEVERITY_TONE[f.severity])
	local b2 = C.badge(id .. ".ver", w1 + SP.sm, y, V.VERDICT_LABEL[f.verdict] or f.verdict, V.VERDICT_TONE[f.verdict] or "neutral")
	ch[#ch + 1] = b1
	ch[#ch + 1] = b2
	y += 20 + SP.md
	local note = C.paragraph(id .. ".note", 0, y, w, V.VERDICT_NOTE[f.verdict] or "", { type = "caption", color = "text_muted" })
	ch[#ch + 1] = note
	y += note.rect.h + SP.lg
	y = field(ch, id .. ".cat", 0, y, w, "Category", f.category .. (#f.secondary_categories > 0 and (" (also: " .. table.concat(f.secondary_categories, ", ") .. ")") or ""))
	y = field(ch, id .. ".conf", 0, y, w, "Confidence", f.confidence)
	y = field(ch, id .. ".path", 0, y, w, "Path", f.object_path, { mono = true })
	ch[#ch + 1] = C.line_text(id .. ".eh", 0, y, w, "Observed evidence", { type = "label" })
	y += 20
	for i, e in ipairs(f.evidence) do
		local p = C.paragraph(id .. ".e" .. i, 0, y, w, "- " .. e.detail, { type = "caption", color = "text_muted" })
		ch[#ch + 1] = p
		y += p.rect.h + SP.xs
	end
	y += SP.md
	y = field(ch, id .. ".why", 0, y, w, "Why it needs review", f.rationale)
	if #f.unknowns > 0 then
		ch[#ch + 1] = C.line_text(id .. ".uh", 0, y, w, "Not known from the client side", { type = "label" })
		y += 20
		for i, u in ipairs(f.unknowns) do
			local p = C.paragraph(id .. ".u" .. i, 0, y, w, "- " .. u, { type = "caption", color = "text_muted" })
			ch[#ch + 1] = p
			y += p.rect.h + SP.xs
		end
		y += SP.md
	end
	if #f.suggested_tests > 0 then
		local names = {}
		for _, t in ipairs(f.suggested_tests) do names[#names + 1] = t.test_type end
		y = field(ch, id .. ".st", 0, y, w, "Suggested verification", table.concat(names, ", ") .. " (needs an approved manifest)", { mono = true })
	end
	sc.canvas_h = math.max(inner.h, y)
	node.children[#node.children + 1] = sc
	return node
end

function P.findings(ctx)
	local R, st = ctx.R, ctx.state
	local f = st.findings
	local rows = V.findings_view(f.list, f.sort, f.filter)
	local total = #f.list
	local nodes = title("fi", R, "Findings", string.format("%d shown of %d", #rows, total))
	local y = R.y + 28 + SP.lg
	local two_rows = R.w < 700
	local x = R.x
	for i, opt in ipairs(V.SEVERITY_FILTERS) do
		local w = math.max(56, C.button_w(opt.label, 56) - 8)
		local selected = (f.filter.severity == opt.key)
		nodes[#nodes + 1] = C.button("fi.f" .. i, { x = x, y = y, w = w, h = 32 }, opt.label, { style = "segment", selected = selected, action = { name = "findings.severity", arg = opt.key or "all" } })
		x += w + SP.xs
	end
	local active = (f.filter.severity ~= nil) or (f.filter.text ~= "")
	local cw = C.button_w("Clear filters")
	local clear_rect = { x = R.x + R.w - cw, y = y, w = cw, h = 32 }
	nodes[#nodes + 1] = C.button("fi.clear", clear_rect, "Clear filters", { style = "ghost", disabled = not active, action = { name = "findings.clear_filters" } })
	local input_rect
	if two_rows then
		input_rect = { x = R.x, y = y + 40, w = R.w, h = 32 }
	else
		local ix = x + SP.lg
		input_rect = { x = ix, y = y, w = math.min(240, clear_rect.x - SP.lg - ix), h = 32 }
	end
	nodes[#nodes + 1] = { id = "fi.search", kind = "input", rect = input_rect, text = f.filter.text, placeholder = "Filter by ID, object or category", action = { name = "findings.text" } }
	y += (two_rows and 72 or 32) + SP.lg

	local body = { x = R.x, y = y, w = R.w, h = math.max(160, R.y + R.h - y) }
	local selected
	for _, fi in ipairs(f.list) do if fi.finding_id == f.selected then selected = fi end end
	local wide = R.w >= 760
	local meta = {}
	local table_rect, detail_rect
	if wide then
		table_rect = { x = body.x, y = body.y, w = body.w - 320 - SP.lg, h = body.h }
		detail_rect = { x = body.x + body.w - 320, y = body.y, w = 320, h = body.h }
	else
		table_rect = body
		detail_rect = body
	end
	local empty
	if total == 0 then
		empty = { title = "No findings yet", body = "Run a passive scan from the Scanner page. Candidates will appear here with their evidence.", action = { label = "Open Scanner", style = "secondary", action = { name = "nav", arg = "scanner" } } }
	else
		empty = { title = "No findings match", body = "Nothing matches the current filters. Clear them to see all " .. total .. " candidates.", action = { label = "Clear filters", style = "secondary", action = { name = "findings.clear_filters" } } }
	end
	if wide or not selected then
		local tnode, info = C.table("fi.table", table_rect, {
			columns = FIND_COLUMNS, rows = rows, sort = f.sort, empty = empty, selected_id = f.selected, page_index = f.page,
			sort_action = function(key) return { name = "findings.sort", arg = key } end,
			row_action = function(row) return { name = "findings.select", arg = row.id } end,
			page_action = function(d) return { name = "findings.page", arg = d } end,
		})
		nodes[#nodes + 1] = tnode
		meta.table = info
	end
	if wide then
		nodes[#nodes + 1] = detail_panel("fi.detail", detail_rect, selected, false)
	elseif selected then
		nodes[#nodes + 1] = detail_panel("fi.detail", detail_rect, selected, true)
	end
	return nodes, R.y + R.h, meta
end

-- ---------------------------------------------------------------- Approved Tests
local TEST_COLUMNS = {
	{ key = "id", label = "Test", w = 96, mono = true, priority = 0 },
	{ key = "endpoint", label = "Endpoint", min_w = 140, priority = 0 },
	{ key = "type", label = "Type", w = 152, priority = 1, muted = true },
	{ key = "calls", label = "Calls", w = 64, align = "right", numeric = true, priority = 3 },
	{ key = "mutates", label = "Changes state", w = 112, priority = 2, muted = true },
	{ key = "expected", label = "Expected", w = 96, priority = 4, muted = true },
	{ key = "result", label = "Result", w = 128, priority = 0, badge = function(v)
		for k, label in pairs(V.VERDICT_LABEL) do if label == v then return V.VERDICT_TONE[k] end end
		return "neutral"
	end },
}

function P.run_block_reason(m, busy)
	if m.state ~= "valid" then return "Load a valid manifest first." end
	if #m.gate_reasons > 0 then return "Blocked: " .. m.gate_reasons[1] end
	if busy then return "Working..." end
	if not m.dry_run_done then return "Run a dry run first. It shows the plan and sends nothing." end
	return "Ready. A typed confirmation is required before anything is sent."
end

function P.tests(ctx)
	local R, st = ctx.R, ctx.state
	local m = st.manifest
	local busy = st.busy["manifest.dry"] or st.busy["manifest.run"] or st.busy["manifest.load"]
	local nodes = title("te", R, "Approved Tests")
	local y = R.y + 28 + SP.lg
	local badge = pa.MANIFEST_BADGE[m.state]
	if #m.gate_reasons > 0 and m.state == "valid" then badge = { "Blocked", "warning" } end
	local bw = C.badge_w(badge[1])
	local inner_w = R.w - 2 * SZ.panel_pad
	local body_nodes_h
	local build_body
	local wide = R.w >= 700
	if m.state == "valid" and m.summary then
		local s = m.summary
		local left = {
			{ label = "Manifest", value = s.manifest_id .. "  v" .. s.version, mono = true },
			{ label = "Approved by", value = s.approved_by },
			{ label = "Reference", value = s.approval_reference },
			{ label = "Mode", value = s.mode },
		}
		local right = {
			{ label = "Scope", value = s.scope },
			{ label = "Server check", value = s.server_check },
			{ label = "Expires", value = s.expires_text },
			{ label = "Limits", value = s.limits_text },
		}
		local reasons = {}
		for i, r in ipairs(m.gate_reasons) do reasons[i] = C.paragraph("te.gate" .. i, 0, 0, inner_w, "Blocked: " .. r, { color = "warning" }) end
		local rh = 0
		for _, p in ipairs(reasons) do rh += p.rect.h + SP.xs end
		body_nodes_h = (wide and C.kv_height(4) or C.kv_height(8)) + (rh > 0 and (rh + SP.sm) or 0)
		build_body = function(panel, inner, cy)
			if wide then
				local cols = layout.columns({ x = inner.x, y = cy, w = inner.w, h = 112 }, 2, SP.lg)
				append(panel.children, (C.kv("te.kv1", cols[1], left, 112)))
				append(panel.children, (C.kv("te.kv2", cols[2], right, 112)))
				cy += C.kv_height(4)
			else
				local all = {}
				for _, r in ipairs(left) do all[#all + 1] = r end
				for _, r in ipairs(right) do all[#all + 1] = r end
				append(panel.children, (C.kv("te.kv", { x = inner.x, y = cy, w = inner.w, h = 224 }, all, 112)))
				cy += C.kv_height(8)
			end
			cy += SP.sm
			for _, p in ipairs(reasons) do
				p.rect.x, p.rect.y = inner.x, cy
				panel.children[#panel.children + 1] = p
				cy += p.rect.h + SP.xs
			end
		end
	elseif m.state == "invalid" then
		local head = (#m.errors) .. " problem(s) found. Nothing was sent and active tests are blocked."
		local ps = { C.paragraph("te.eh", 0, 0, inner_w, head, { color = "error" }) }
		for i = 1, math.min(5, #m.errors) do ps[#ps + 1] = C.paragraph("te.e" .. i, 0, 0, inner_w, "- " .. m.errors[i], { type = "caption", color = "text_muted" }) end
		if #m.errors > 5 then ps[#ps + 1] = C.paragraph("te.more", 0, 0, inner_w, "+" .. (#m.errors - 5) .. " more. Fix these, then load the manifest again.", { type = "caption", color = "text_muted" }) end
		body_nodes_h = 0
		for _, p in ipairs(ps) do body_nodes_h += p.rect.h + SP.xs end
		build_body = function(panel, inner, cy)
			for _, p in ipairs(ps) do
				p.rect.x, p.rect.y = inner.x, cy
				panel.children[#panel.children + 1] = p
				cy += p.rect.h + SP.xs
			end
		end
	else
		local p = C.paragraph("te.none", 0, 0, inner_w, "No manifest loaded. Active tests are impossible without a developer-approved manifest that lists every endpoint, argument and limit.", { color = "text_muted" })
		body_nodes_h = p.rect.h
		build_body = function(panel, inner, cy)
			p.rect.x, p.rect.y = inner.x, cy
			panel.children[#panel.children + 1] = p
		end
	end
	local ph = 48 + 32 + SP.md + body_nodes_h + SZ.panel_pad
	local panel, inner = C.panel("te.panel", { x = R.x, y = y, w = R.w, h = ph }, "Manifest", { title_right_w = bw + SP.sm })
	panel.children[#panel.children + 1] = C.badge("te.state", R.w - SZ.panel_pad - bw, SZ.panel_pad, badge[1], badge[2])
	local lw = C.button_w("Load Manifest")
	panel.children[#panel.children + 1] = { id = "te.path", kind = "input", rect = { x = inner.x, y = inner.y, w = inner.w - lw - SP.sm, h = 32 }, text = m.path_input,
		placeholder = "ShadowScan/manifest.json", action = { name = "manifest.path" }, mono = true }
	panel.children[#panel.children + 1] = C.button("te.load", { x = inner.x + inner.w - lw, y = inner.y, w = lw, h = 32 }, "Load Manifest",
		{ style = "secondary", loading = st.busy["manifest.load"], action = { name = "manifest.load" } })
	build_body(panel, inner, inner.y + 32 + SP.md)
	nodes[#nodes + 1] = panel
	y += ph + SP.lg

	local actions_y = R.y + R.h - 32
	local th = math.max(220, actions_y - SP.lg - y) -- below this the page scrolls instead of squeezing the table to one row
	local test_rows = {}
	for i, t in ipairs(m.tests or {}) do test_rows[i] = { id = t.id, cells = { id = t.id, endpoint = t.endpoint, type = t.type, calls = tostring(t.calls), mutates = t.mutates and "Yes" or "No", expected = t.expected, result = t.result } } end
	local tnode, info = C.table("te.table", { x = R.x, y = y, w = R.w, h = th }, {
		columns = TEST_COLUMNS, rows = test_rows, page_index = m.page,
		page_action = function(d) return { name = "manifest.page", arg = d } end,
		empty = { title = "No test cases", body = "Test cases appear here once a valid manifest is loaded." },
	})
	nodes[#nodes + 1] = tnode
	y += th + SP.lg

	local reason = P.run_block_reason(m, busy)
	local ready = m.state == "valid" and #m.gate_reasons == 0
	local b0, b1, b2 = C.button_w("Generate Draft Plan"), C.button_w("Dry Run"), C.button_w("Run Approved Tests...")
	local rs = layout.right_aligned({ x = R.x, y = y, w = R.w, h = 32 }, { b0, b1, b2 }, 32)
	nodes[#nodes + 1] = C.text("te.reason", { x = R.x, y = y + 8, w = rs[1].x - R.x - SP.lg, h = 16 }, reason, { type = "caption", color = ready and "text_muted" or "warning", truncate = true })
	nodes[#nodes + 1] = C.button("te.draft", rs[1], "Generate Draft Plan",
		{ style = "secondary", disabled = #st.findings.list == 0, loading = st.busy["manifest.draft"], action = { name = "manifest.draft" } })
	nodes[#nodes + 1] = C.button("te.dry", rs[2], "Dry Run", { style = "secondary", disabled = not ready or busy, loading = st.busy["manifest.dry"], action = { name = "manifest.dry" } })
	nodes[#nodes + 1] = C.button("te.run", rs[3], "Run Approved Tests...", { style = "primary", role = "primary_action", disabled = not (ready and m.dry_run_done) or busy, action = { name = "manifest.run_open" } })
	return nodes, math.max(y + 32, R.y + R.h), { table = info }
end

-- ---------------------------------------------------------------- Secure Export
local function form_row(id, inner, y, label, input)
	local lw = 128
	local nodes = { C.line_text(id .. ".l", inner.x, y + 8, lw - SP.sm, label, { type = "caption", color = "text_muted", truncate = true }) }
	input.rect = { x = inner.x + lw, y = y, w = input.w or (inner.w - lw), h = 32 }
	input.w = nil
	input.id = id .. ".i"
	input.kind = "input"
	nodes[#nodes + 1] = input
	return nodes
end

function P.export(ctx)
	local R, st = ctx.R, ctx.state
	local ex = st.export
	local busy = st.busy
	local nodes = title("ex", R, "Secure Export")
	local y = R.y + 28 + SP.lg
	local wide = R.w >= 760
	local colw = wide and layout.columns({ x = R.x, y = y, w = R.w, h = 0 }, 2, SP.lg) or { { x = R.x, y = y, w = R.w, h = 0 }, { x = R.x, y = 0, w = R.w, h = 0 } }

	-- Report
	local rep = ex.report
	local rows = rep and {
		{ label = "File name", value = rep.file_name, mono = true },
		{ label = "Built", value = V.stamp(rep.built_at) },
		{ label = "Size", value = V.bytes(rep.bytes) },
		{ label = "Contents", value = string.format("%d candidate(s), %d test run(s)", rep.candidates, rep.runs) },
	} or { { label = "Status", value = "No report built yet" } }
	local rh = 48 + C.kv_height(#rows) + SP.md + 32 + SZ.panel_pad
	local rp, ri = C.panel("ex.report", { x = colw[1].x, y = y, w = colw[1].w, h = rh }, "1. Report")
	append(rp.children, (C.kv("ex.report.kv", ri, rows, 100)))
	local bw = C.button_w(rep and "Rebuild Report" or "Build Report")
	rp.children[#rp.children + 1] = C.button("ex.build", { x = ri.x + ri.w - bw, y = ri.y + C.kv_height(#rows) + SP.md, w = bw, h = 32 }, rep and "Rebuild Report" or "Build Report",
		{ style = "secondary", role = "primary_action", loading = busy["export.build"], action = { name = "export.build" } })
	nodes[#nodes + 1] = rp

	-- Encrypt
	local cb, eb = pa.COMPANION_BADGE[ex.companion.state], pa.ENCRYPTION_BADGE[ex.encryption.state]
	local status_rows = {
		{ label = "Companion", badge = cb[1], tone = cb[2], text = ex.companion.detail },
		{ label = "Encryption", badge = eb[1], tone = eb[2], text = ex.encryption.detail },
	}
	local eh = 48 + 32 + SP.sm + 32 + SP.md + C.kv_height(2) + SP.md + 32 + SZ.panel_pad
	local ey = y + rh + SP.lg
	local ep, ei = C.panel("ex.enc", { x = colw[1].x, y = ey, w = colw[1].w, h = eh }, "2. Encrypt with the companion")
	local ry = ei.y
	append(ep.children, form_row("ex.token", ei, ry, "Pairing token", { text = ex.token_input, placeholder = "ssp_...", action = { name = "export.token" }, mono = true }))
	ry += 32 + SP.sm
	append(ep.children, form_row("ex.port", ei, ry, "Port", { w = 120, text = ex.port_input, action = { name = "export.port" }, mono = true }))
	ry += 32 + SP.md
	append(ep.children, (C.kv("ex.status", { x = ei.x, y = ry, w = ei.w, h = 56 }, status_rows, 100)))
	ry += C.kv_height(2) + SP.md
	local w1, w2 = C.button_w("Check Companion"), C.button_w("Encrypt and Save")
	local rs = layout.right_aligned({ x = ei.x, y = ry, w = ei.w, h = 32 }, { w1, w2 }, 32)
	ep.children[#ep.children + 1] = C.button("ex.check", rs[1], "Check Companion", { style = "secondary", loading = busy["companion.check"], action = { name = "companion.check" } })
	ep.children[#ep.children + 1] = C.button("ex.encrypt", rs[2], "Encrypt and Save", { style = "primary", role = "primary_action", disabled = not rep, loading = busy["export.encrypt"], action = { name = "export.encrypt" } })
	nodes[#nodes + 1] = ep

	-- Ciphertext
	local ct = ex.cipher
	local cx = colw[2]
	local cy0 = wide and y or (ey + eh + SP.lg)
	local inner_w = cx.w - 2 * SZ.panel_pad
	local sha_p = ct and C.paragraph("probe", 0, 0, inner_w, ct.sha256, { type = "mono" })
	local info_rows = ct and { { label = "File name", value = ct.file_name, mono = true }, { label = "Created", value = V.stamp(ct.created_at) }, { label = "Size", value = V.bytes(ct.bytes) } } or {}
	local none_p = (not ct) and C.paragraph("probe2", 0, 0, inner_w, "No ciphertext yet. Build the report, then encrypt it with the companion. Plaintext is never written by this tool.", { color = "text_muted" })
	local fb = ex.feedback
	local body_h = ct and (C.kv_height(#info_rows) + 20 + sha_p.rect.h) or none_p.rect.h
	local ch = 48 + body_h + SP.md + (fb and 24 or 0) + 32 + SP.md + 32 + SP.md + 32 + SP.md + 32 + SZ.panel_pad
	local cp, ci = C.panel("ex.cipher", { x = cx.x, y = cy0, w = cx.w, h = ch }, "3. Encrypted output")
	local yy = ci.y
	if ct then
		append(cp.children, (C.kv("ex.cipher.kv", { x = ci.x, y = yy, w = ci.w, h = 84 }, info_rows, 100)))
		yy += C.kv_height(#info_rows)
		cp.children[#cp.children + 1] = C.line_text("ex.sha.l", ci.x, yy, ci.w, "SHA-256 of the exported text", { type = "caption", color = "text_muted" })
		yy += 20
		sha_p.id, sha_p.rect.x, sha_p.rect.y = "ex.sha", ci.x, yy
		cp.children[#cp.children + 1] = sha_p
		yy += sha_p.rect.h
	else
		none_p.id, none_p.rect.x, none_p.rect.y = "ex.none", ci.x, yy
		cp.children[#cp.children + 1] = none_p
		yy += none_p.rect.h
	end
	yy += SP.md
	if fb then
		append(cp.children, C.notice("ex.fb", { x = ci.x, y = yy, w = ci.w, h = 16 }, fb.tone, fb.label, fb.text))
		yy += 24
	end
	local a1, a2 = C.button_w("Copy SHA-256"), C.button_w("Copy Ciphertext")
	local r1 = layout.right_aligned({ x = ci.x, y = yy, w = ci.w, h = 32 }, { a1, a2 }, 32)
	cp.children[#cp.children + 1] = C.button("ex.copysha", r1[1], "Copy SHA-256", { style = "secondary", disabled = not ct, action = { name = "export.copy_sha" } })
	cp.children[#cp.children + 1] = C.button("ex.copyct", r1[2], "Copy Ciphertext", { style = "secondary", disabled = not ct, action = { name = "export.copy_cipher" } })
	yy += 32 + SP.md
	local m1, m2 = C.button_w("Save Metadata"), C.button_w("Export Encrypted TXT")
	local r2 = layout.right_aligned({ x = ci.x, y = yy, w = ci.w, h = 32 }, { m1, m2 }, 32)
	cp.children[#cp.children + 1] = C.button("ex.meta", r2[1], "Save Metadata", { style = "secondary", disabled = not ct, loading = busy["export.meta"], action = { name = "export.meta" } })
	cp.children[#cp.children + 1] = C.button("ex.export", r2[2], "Export Encrypted TXT",
		{ style = "primary", role = "primary_action", disabled = not ct, loading = busy["export.save"], action = { name = "export.save" } })
	yy += 32 + SP.md
	local cw = C.button_w("Clear Session")
	cp.children[#cp.children + 1] = C.button("ex.clear", { x = ci.x + ci.w - cw, y = yy, w = cw, h = 32 }, "Clear Session",
		{ style = "danger", action = { name = "export.clear" } })
	nodes[#nodes + 1] = cp
	local bottom = wide and math.max(ey + eh, cy0 + ch) or (cy0 + ch)
	return nodes, bottom
end

-- ---------------------------------------------------------------- Explorer (0.3.0)
local EXP_COLUMNS = {
	{ key = "risk", label = "Risk", w = 60, numeric = true, align = "right", sortable = true, priority = 0 },
	{ key = "band", label = "Band", w = 84, priority = 0, badge = function(v)
		for k, label in pairs(V.RISK_BAND_LABEL) do if label == v then return V.RISK_BAND_TONE[k] end end
		return "neutral"
	end },
	{ key = "object", label = "Object", min_w = 120, sortable = true, priority = 0 },
	{ key = "family", label = "Family", w = 128, priority = 1, muted = true },
}
local FAM_COLUMNS = {
	{ key = "family", label = "Family (hint-level)", min_w = 110, sortable = true, priority = 0 },
	{ key = "count", label = "Candidates", w = 92, numeric = true, align = "right", sortable = true, priority = 0 },
	{ key = "top", label = "Top risk", w = 76, numeric = true, align = "right", priority = 1 },
}
local CON_COLUMNS = {
	{ key = "path", label = "Container (replicated structure)", min_w = 140, priority = 0, mono = true },
	{ key = "remotes", label = "Remotes", w = 76, numeric = true, align = "right", priority = 0 },
}

function P.explorer(ctx)
	local R, st = ctx.R, ctx.state
	local e = st.explorer
	local rows = V.explorer_view(st.findings.list, e.sort, e.family)
	local nodes = title("ex2", R, "Explorer", string.format("%d of %d candidate(s)", #rows, #st.findings.list))
	local y = R.y + 28 + SP.lg
	local desc = "Families and risk scores are HINTS derived from names, structure and observed properties - never proof of a vulnerability."
	local inner_w = R.w - 2 * SZ.panel_pad
	local para_h = C.paragraph("probe", 0, 0, inner_w, desc, { color = "text_muted" }).rect.h
	nodes[#nodes + 1] = C.paragraph("ex2.desc", R.x, y, inner_w, desc, { color = "text_muted" })
	y += para_h + SP.lg

	-- family filter segments (top families only; the full list lives in the Families panel)
	local fams = e.families or {}
	local x = R.x
	local filters = { { key = "all", label = "All families" } }
	for i = 1, math.min(4, #fams) do filters[#filters + 1] = { key = fams[i].family, label = fams[i].label } end
	for _, opt in ipairs(filters) do
		local w = math.max(56, C.button_w(opt.label, 56) - 8)
		nodes[#nodes + 1] = C.button("ex2.f." .. opt.key, { x = x, y = y, w = w, h = 32 }, opt.label,
			{ style = "segment", selected = (e.family or "all") == opt.key, action = { name = "explorer.family", arg = opt.key }, truncate = true })
		x += w + SP.xs
	end
	y += 32 + SP.lg

	local body = { x = layout.snap(R.x), y = layout.snap(y), w = layout.snap(R.w), h = layout.snap(math.max(200, R.y + R.h - y)) }
	local wide = R.w >= 760
	local meta = {}
	local fam_rows = {}
	for i, fam in ipairs(fams) do
		fam_rows[i] = { id = fam.family, family = fam, cells = { family = fam.label, count = tostring(fam.count), top = tostring(fam.top_risk) } }
	end
	local con_rows = {}
	for i, c in ipairs(e.containers or {}) do
		con_rows[i] = { id = c.path, container = c, cells = { path = c.path, remotes = tostring(c.remotes) } }
	end
	local none = #st.findings.list == 0
	local empty_top = none and { title = "No candidates yet", body = "Run a passive scan first; families and risk scores appear here." }
		or { title = "No candidates in this family", body = "Clear the family filter to see all " .. #st.findings.list .. " candidates." }
	local empty_fam = { title = "No families yet", body = "" }
	local empty_con = { title = "No containers yet", body = "" }
	-- lazy rendering: C.table pages internally (table_capacity) so only the visible rows exist in the scene
	local function risk_table(rect)
		local tnode, info = C.table("ex2.risk", rect, {
			columns = EXP_COLUMNS, rows = rows, sort = e.sort, empty = empty_top, page_index = e.page,
			sort_action = function(key) return { name = "explorer.sort", arg = key } end,
			row_action = function(row) return { name = "explorer.select", arg = row.id } end,
			page_action = function(d) return { name = "explorer.page", arg = d } end,
		})
		nodes[#nodes + 1] = tnode
		meta.table = info
	end
	if wide then
		local left_w = layout.snap(math.floor(body.w * 0.56))
		local rx = layout.snap(body.x + left_w + SP.lg)
		local rw = layout.snap(body.w - left_w - SP.lg)
		local fh = math.max(120, layout.snap(math.floor(body.h * 0.42)))
		risk_table({ x = body.x, y = body.y, w = left_w, h = body.h })
		nodes[#nodes + 1] = C.table("ex2.fam", { x = rx, y = body.y, w = rw, h = fh }, {
			columns = FAM_COLUMNS, rows = fam_rows, empty = empty_fam, page_index = e.page,
			row_action = function(row) return { name = "explorer.family", arg = row.id } end,
			page_action = function(d) return { name = "explorer.page", arg = d } end,
		})
		nodes[#nodes + 1] = C.table("ex2.con", { x = rx, y = layout.snap(body.y + fh + SP.lg), w = rw, h = layout.snap(body.h - fh - SP.lg) }, {
			columns = CON_COLUMNS, rows = con_rows, page_index = e.page, empty = empty_con,
			row_action = function(row) return { name = "explorer.container", arg = row.id } end,
			page_action = function(d) return { name = "explorer.page", arg = d } end,
		})
	else
		-- narrow: two tables only (containers appear when the window is wide enough)
		local fh = math.max(96, layout.snap(math.floor(body.h * 0.35)))
		risk_table({ x = body.x, y = body.y, w = body.w, h = layout.snap(body.h - fh - SP.lg) })
		nodes[#nodes + 1] = C.table("ex2.fam", { x = body.x, y = layout.snap(body.y + body.h - fh), w = body.w, h = fh }, {
			columns = FAM_COLUMNS, rows = fam_rows, empty = empty_fam, page_index = e.page,
			row_action = function(row) return { name = "explorer.family", arg = row.id } end,
			page_action = function(d) return { name = "explorer.page", arg = d } end,
		})
	end
	return nodes, R.y + R.h, meta
end

-- ---------------------------------------------------------------- Relationship Graph (0.4.0)
local GRAPH_CON_COLUMNS = {
	{ key = "path", label = "Container (click to inspect)", min_w = 140, priority = 0, mono = true },
	{ key = "remotes", label = "Remotes", w = 76, numeric = true, align = "right", priority = 0 },
}
local GRAPH_MEMBER_COLUMNS = {
	{ key = "cls", label = "Class", w = 148, priority = 1 },
	{ key = "name", label = "Remote", min_w = 110, priority = 0 },
	{ key = "family", label = "Family (hint)", w = 108, priority = 1, muted = true },
}

function P.graph(ctx)
	local R, st = ctx.R, ctx.state
	local g = st.graph
	local stats = g.stats or { remotes = 0, containers = 0, edges = 0 }
	local nodes = title("gr", R, "Relationship Graph", string.format("%d remote(s), %d container(s)", stats.remotes or 0, stats.containers or 0))
	local y = R.y + 28 + SP.lg
	local desc = "Factual, structure-derived relations (child_of / sibling_of / co_named) between replicated remotes. Built from the current audit; nothing here is a behaviour claim."
	local inner_w = R.w - 2 * SZ.panel_pad
	local para_h = C.paragraph("probe", 0, 0, inner_w, desc, { color = "text_muted" }).rect.h
	nodes[#nodes + 1] = C.paragraph("gr.desc", R.x, y, inner_w, desc, { color = "text_muted" })
	y += para_h + SP.lg

	local body = { x = layout.snap(R.x), y = layout.snap(y), w = layout.snap(R.w), h = layout.snap(math.max(160, R.y + R.h - y)) }
	local wide = R.w >= 760
	local con_rows = {}
	for i, c in ipairs(g.containers or {}) do
		con_rows[i] = { id = c.path, container = c, cells = { path = c.path, remotes = tostring(c.remote_count) } }
	end
	local stats_rows = {
		{ label = "Graph nodes / edges", value = string.format("%d / %d", stats.nodes or 0, stats.edges or 0) },
		{ label = "Containers listed", value = string.format("%d of %d", #(g.containers or {}), g.containers_total or 0) },
		{ label = "Truncated", value = stats.truncated and "yes (bounded output)" or "no" },
	}
	if wide then
		local left_w = layout.snap(math.floor(body.w * 0.55))
		local rx = layout.snap(body.x + left_w + SP.lg)
		local rw = layout.snap(body.w - left_w - SP.lg)
		local tnode, info = C.table("gr.cons", { x = body.x, y = body.y, w = left_w, h = body.h }, {
			columns = GRAPH_CON_COLUMNS, rows = con_rows, page_index = g.page,
			selected_id = g.selected,
			empty = { title = "No containers yet", body = "Run a passive scan; the relationship summary appears here." },
			row_action = function(row) return { name = "graph.select", arg = row.id } end,
			page_action = function(d) return { name = "graph.page", arg = d } end,
		})
		nodes[#nodes + 1] = tnode
		local sh = 48 + C.kv_height(#stats_rows) + SZ.panel_pad
		local stat_p, si = C.panel("gr.stats", { x = rx, y = body.y, w = rw, h = sh }, "Graph stats")
		append(stat_p.children, (C.kv("gr.stats.kv", si, stats_rows, 152)))
		nodes[#nodes + 1] = stat_p
		local member_rows, sel = {}, nil
		for _, c in ipairs(g.containers or {}) do if c.path == g.selected then sel = c end end
		if sel then
			for i, rp in ipairs(sel.remotes or {}) do
				local cls, path = rp:match("^([^|]+)|(.*)$")
				member_rows[i] = { id = rp, cells = { cls = cls or "?", name = path or rp, family = "" } }
			end
		end
		local mh = body.h - sh - SP.lg
		local empty = sel and { title = "No remotes listed", body = "This container's remotes exceed the listing cap." }
			or { title = "Pick a container", body = "Click a container on the left to inspect its member remotes." }
		local mnode = C.table("gr.members", { x = rx, y = layout.snap(body.y + sh + SP.lg), w = rw, h = layout.snap(mh) }, {
			columns = GRAPH_MEMBER_COLUMNS, rows = member_rows, empty = empty, page_index = g.page,
		})
		nodes[#nodes + 1] = mnode
	else
		-- narrow: the containers table fills the page; the counts live in the title (a second panel cannot fit)
		local tnode = C.table("gr.cons", { x = body.x, y = body.y, w = body.w, h = body.h }, {
			columns = GRAPH_CON_COLUMNS, rows = con_rows, page_index = g.page, selected_id = g.selected,
			empty = { title = "No containers yet", body = "Run a passive scan first." },
			row_action = function(row) return { name = "graph.select", arg = row.id } end,
			page_action = function(d) return { name = "graph.page", arg = d } end,
		})
		nodes[#nodes + 1] = tnode
	end
	return nodes, R.y + R.h
end

-- ---------------------------------------------------------------- Session Compare (0.4.0)
local CMP_COLUMNS = {
	{ key = "kind", label = "Change", w = 92, priority = 0, badge = function(v)
		return ({ Added = "success", Removed = "error", Changed = "warning", Moved = "neutral" })[v] or "neutral"
	end },
	{ key = "obj", label = "Remote", min_w = 100, priority = 0 },
	{ key = "path", label = "Path (or from -> to)", min_w = 180, priority = 0, mono = true },
	{ key = "conf", label = "Match", w = 88, priority = 1, muted = true },
}

function P.compare(ctx)
	local R, st = ctx.R, ctx.state
	local sn = st.snapshot
	local d = sn.diff
	local nodes = title("cp", R, "Session Compare", d and string.format("+%d / -%d / ~%d", d.added_count, d.removed_count, d.changed_count or 0) or nil)
	local y = R.y + 28 + SP.lg
	-- the honesty note lives in the report; on short windows the paragraph is dropped so the diff table fits
	if R.h >= 560 then
		local desc = "Compares the current remote surface with a saved snapshot. A remote that no longer appears may still exist on the server: replication, streaming and distance can hide it."
		local inner_w = R.w - 2 * SZ.panel_pad
		local para_h = C.paragraph("probe", 0, 0, inner_w, desc, { color = "text_muted" }).rect.h
		nodes[#nodes + 1] = C.paragraph("cp.desc", R.x, y, inner_w, desc, { color = "text_muted" })
		y += para_h + SP.lg
	end

	-- adaptive: on short windows the counts live in the title and the kv summary is skipped (the diff table needs the space)
	local show_summary = R.h >= 560
	local rows
	if not show_summary then
		rows = { { label = "Status", value = d and "See the change list below and the title counts." or "No comparison yet" } }
	elseif d then
		rows = {
			{ label = "Added", value = tostring(d.added_count) },
			{ label = "Removed", value = tostring(d.removed_count) },
			{ label = "Metadata changed", value = tostring(d.changed_count or 0) },
			{ label = "Moved (low confidence)", value = tostring(d.moved_count or 0) },
			{ label = "Compared with", value = tostring(d.previous_created_utc), mono = true },
		}
	else
		rows = { { label = "Status", value = sn.state == "saved" and ("Snapshot written: " .. tostring(sn.detail)) or "No comparison yet" } }
	end
	if sn.state == "error" and sn.detail then rows[#rows + 1] = { label = "Problem", value = sn.detail } end
	if sn.state == "deleted" and sn.detail then rows[#rows + 1] = { label = "Deleted", value = sn.detail, mono = true } end
	local ph = 48 + 32 + SP.md + C.kv_height(#rows) + SP.md + 32 + SZ.panel_pad
	local act, ai = C.panel("cp.act", { x = R.x, y = y, w = R.w, h = ph }, "Snapshots")
	local ay = ai.y
	append(act.children, form_row("cp.path", ai, ay, "Snapshot file", { text = sn.path_input, placeholder = "ShadowScan/out/snapshot-....json", action = { name = "snapshot.path" }, mono = true }))
	ay += 32 + SP.md
	append(act.children, (C.kv("cp.kv", { x = ai.x, y = ay, w = ai.w, h = C.kv_height(#rows) }, rows, 152)))
	ay += C.kv_height(#rows) + SP.md
	local b1, b2, b3 = C.button_w("Save Snapshot"), C.button_w("Compare with Snapshot"), C.button_w("Delete Snapshot")
	local brs = layout.right_aligned({ x = ai.x, y = ay, w = ai.w, h = 32 }, { b1, b2, b3 }, 32)
	act.children[#act.children + 1] = C.button("cp.save", brs[1], "Save Snapshot",
		{ style = "secondary", disabled = st.scan.state ~= "complete" and st.scan.state ~= "cancelled", loading = st.busy["snapshot.save"], action = { name = "snapshot.save" } })
	act.children[#act.children + 1] = C.button("cp.compare", brs[2], "Compare with Snapshot",
		{ style = "secondary", disabled = st.scan.state ~= "complete" and st.scan.state ~= "cancelled", loading = st.busy["snapshot.compare"], action = { name = "snapshot.compare" } })
	act.children[#act.children + 1] = C.button("cp.delete", brs[3], "Delete Snapshot",
		{ style = "danger", loading = st.busy["snapshot.delete"], action = { name = "snapshot.delete" } })
	nodes[#nodes + 1] = act
	y += ph + SP.lg

	local body = { x = layout.snap(R.x), y = layout.snap(y), w = layout.snap(R.w), h = layout.snap(math.max(120, R.y + R.h - y)) }
	local rows2 = {}
	local function push(kind, item)
		if #rows2 >= 120 then return end
		if kind == "Moved" then
			rows2[#rows2 + 1] = { id = kind .. tostring(#rows2), cells = { kind = kind, obj = item.name, path = item.from .. " -> " .. item.to, conf = item.match_confidence or "low" } }
		elseif kind == "Changed" then
			rows2[#rows2 + 1] = { id = kind .. tostring(#rows2), cells = { kind = kind, obj = item.name, path = item.path, conf = item.match_confidence or "high" } }
		else
			rows2[#rows2 + 1] = { id = kind .. tostring(#rows2), cells = { kind = kind, obj = item.name, path = item.path, conf = "high" } }
		end
	end
	if d then
		for _, x in ipairs(d.added or {}) do push("Added", x) end
		for _, x in ipairs(d.removed or {}) do push("Removed", x) end
		for _, x in ipairs(d.changed or {}) do push("Changed", x) end
		for _, x in ipairs(d.moved or {}) do push("Moved", x) end
	end
	local tnode, info = C.table("cp.table", body, {
		columns = CMP_COLUMNS, rows = rows2, page_index = st.explorer.page,
		empty = d and { title = "No differences", body = "The remote surface matches the snapshot exactly (within the listed bounds)." }
			or { title = "No comparison yet", body = "Save a snapshot, play for a while, then compare against it." },
		page_action = function(dd) return { name = "explorer.page", arg = dd } end,
	})
	nodes[#nodes + 1] = tnode
	return nodes, R.y + R.h, { table = info }
end

return P
end
__factories["client.ui.renderer"] = function(require)
-- Scene -> Roblox Instances. Thin on purpose: all layout decisions were made (and tested) before this runs.
-- Nothing here is verified inside real Roblox yet; tests drive it with a recording mock factory (tests/luau/mock_gui.lua).
local json = require("client.util.json")
local tokens = require("client.ui.tokens")
local styles = require("client.ui.styles")
local C = require("client.ui.components")

local R = {}
R.__index = R

local FONT_ENUM = { ui = "Gotham", ui_medium = "GothamMedium", ui_bold = "GothamBold", mono = "RobotoMono" }

-- opts: { factory = {create=fn(class)->instance}, parent = instance, env = { Color3, UDim2, UDim, Enum }, dispatch = fn(action) }
function R.new(opts)
	local self = setmetatable({}, R)
	self.factory, self.parent, self.env, self.dispatch = opts.factory, opts.parent, opts.env, opts.dispatch
	self.entries = {}
	self.root_inst = nil
	return self
end

local function hex(self, h) return self.env.Color3.fromHex(C.resolve(h)) end

local function set_corner(self, entry, radius)
	if (radius or 0) > 0 then
		if not entry.corner then
			entry.corner = self.factory.create("UICorner")
			entry.corner.Parent = entry.inst
		end
		entry.corner.CornerRadius = self.env.UDim.new(0, radius)
	elseif entry.corner then
		entry.corner:Destroy()
		entry.corner = nil
	end
end

local function set_stroke(self, entry, color)
	if color then
		if not entry.stroke then
			entry.stroke = self.factory.create("UIStroke")
			entry.stroke.Parent = entry.inst
			entry.stroke.Thickness = 1
			entry.stroke.ApplyStrokeMode = self.env.Enum.ApplyStrokeMode.Border
		end
		entry.stroke.Color = hex(self, color)
	elseif entry.stroke then
		entry.stroke:Destroy()
		entry.stroke = nil
	end
end

local function set_padding(self, entry, left, right)
	if not entry.pad then
		entry.pad = self.factory.create("UIPadding")
		entry.pad.Parent = entry.inst
	end
	entry.pad.PaddingLeft = self.env.UDim.new(0, left)
	entry.pad.PaddingRight = self.env.UDim.new(0, right)
end

local function class_for(node)
	if node.kind == "text" then return "TextLabel" end
	if node.kind == "button" then return "TextButton" end
	if node.kind == "input" then return "TextBox" end
	if node.kind == "scroll" then return "ScrollingFrame" end
	return "Frame"
end

local function apply(self, entry, node)
	local inst, env = entry.inst, self.env
	local rect = node.rect
	inst.Position = env.UDim2.fromOffset(rect.x, rect.y)
	inst.Size = env.UDim2.fromOffset(rect.w, rect.h)
	inst.BorderSizePixel = 0
	entry.node = node
	if node.kind == "frame" then
		inst.BackgroundColor3 = hex(self, node.fill or "panel")
		inst.BackgroundTransparency = node.fill and (1 - (node.alpha or 1)) or 1
		inst.ClipsDescendants = node.clip == true
		set_corner(self, entry, node.radius)
		set_stroke(self, entry, node.stroke)
	elseif node.kind == "scroll" then
		inst.BackgroundTransparency = 1
		inst.CanvasSize = env.UDim2.fromOffset(0, node.canvas_h)
		inst.ScrollBarThickness = 6
		inst.ScrollingDirection = env.Enum.ScrollingDirection.Y
		inst.ScrollBarImageColor3 = hex(self, "border_strong")
		inst.ClipsDescendants = true
	elseif node.kind == "text" then
		inst.BackgroundTransparency = 1
		inst.Text = node.text
		inst.TextColor3 = hex(self, node.color or "text")
		inst.Font = env.Enum.Font[FONT_ENUM[node.font or "ui"]]
		inst.TextSize = node.size
		inst.TextXAlignment = env.Enum.TextXAlignment[node.align == "right" and "Right" or (node.align == "center" and "Center" or "Left")]
		inst.TextYAlignment = env.Enum.TextYAlignment.Center
		inst.TextWrapped = node.wrap == true
		inst.TextTruncate = (node.truncate and not node.wrap) and env.Enum.TextTruncate.AtEnd or env.Enum.TextTruncate.None
		inst.RichText = false
	elseif node.kind == "button" then
		local st = styles.button(node)
		entry.style = st
		local disabled = node.disabled or node.loading or not node.action
		entry.disabled = disabled and node.style ~= "scrim"
		inst.AutoButtonColor = false
		inst.Active = true
		inst.BackgroundColor3 = hex(self, st.fill or "panel")
		inst.BackgroundTransparency = st.fill and (1 - (st.alpha or 1)) or 1
		inst.Text = node.label or ""
		inst.TextColor3 = hex(self, st.text or "text")
		inst.Font = env.Enum.Font[FONT_ENUM[node.font or "ui_medium"]]
		inst.TextSize = node.size or 13
		inst.TextTruncate = env.Enum.TextTruncate.AtEnd
		local left = (node.style == "nav" and node.align == "left") or (node.style == "header" and node.align ~= "right")
		inst.TextXAlignment = env.Enum.TextXAlignment[left and "Left" or (node.align == "right" and "Right" or "Center")]
		if node.style == "nav" then set_padding(self, entry, 16, 8) elseif node.style == "header" then set_padding(self, entry, 8, 8) else set_padding(self, entry, 4, 4) end
		set_corner(self, entry, (node.style == "row" or node.style == "header" or node.style == "scrim") and 0 or 4)
		set_stroke(self, entry, st.stroke)
		if st.bar then
			if not entry.bar then
				entry.bar = self.factory.create("Frame")
				entry.bar.Parent = inst
				entry.bar.BorderSizePixel = 0
				entry.bar.Size = env.UDim2.fromOffset(2, node.rect.h)
			end
			entry.bar.BackgroundColor3 = hex(self, st.bar)
			entry.bar.Size = env.UDim2.fromOffset(2, node.rect.h)
		elseif entry.bar then
			entry.bar:Destroy()
			entry.bar = nil
		end
	elseif node.kind == "input" then
		inst.BackgroundColor3 = hex(self, "bg")
		inst.BackgroundTransparency = 0
		inst.Text = node.text or ""
		inst.PlaceholderText = node.placeholder or ""
		inst.PlaceholderColor3 = hex(self, "text_disabled")
		inst.TextColor3 = hex(self, node.disabled and "text_disabled" or "text")
		inst.Font = env.Enum.Font[FONT_ENUM[node.mono and "mono" or "ui"]]
		inst.TextSize = node.mono and 12 or 13
		inst.TextXAlignment = env.Enum.TextXAlignment.Left
		inst.ClearTextOnFocus = false
		inst.TextEditable = not node.disabled
		set_padding(self, entry, 12, 12)
		set_corner(self, entry, 4)
		set_stroke(self, entry, "border_strong")
	end
end

local function connect(self, entry)
	local inst = entry.inst
	if entry.connected then return end
	entry.connected = true
	entry.conns = {}
	local function on(signal, fn) entry.conns[#entry.conns + 1] = signal:Connect(fn) end
	if entry.node.kind == "button" then
		on(inst.MouseButton1Click, function()
			local node = entry.node
			if entry.disabled or not node.action then return end
			self.dispatch(node.action)
		end)
		on(inst.MouseEnter, function()
			local st = entry.style
			if entry.disabled or not st or not st.fill_hover then if st and st.text_hover and not entry.disabled then inst.TextColor3 = hex(self, st.text_hover) end return end
			inst.BackgroundColor3 = hex(self, st.fill_hover)
			inst.BackgroundTransparency = 0
			if st.text_hover then inst.TextColor3 = hex(self, st.text_hover) end
		end)
		on(inst.MouseLeave, function()
			local st = entry.style
			if not st then return end
			inst.BackgroundColor3 = hex(self, st.fill or "panel")
			inst.BackgroundTransparency = st.fill and (1 - (st.alpha or 1)) or 1
			if st.text then inst.TextColor3 = hex(self, st.text) end
		end)
		on(inst.MouseButton1Down, function()
			local st = entry.style
			if entry.disabled or not st or not st.fill_down then return end
			inst.BackgroundColor3 = hex(self, st.fill_down)
			inst.BackgroundTransparency = 0
		end)
	elseif entry.node.kind == "input" then
		on(inst.FocusLost, function()
			local node = entry.node
			if node.disabled or not node.action then return end
			self.dispatch({ name = node.action.name, arg = inst.Text })
		end)
	end
end

local function signature(node)
	local copy = {}
	for k, v in pairs(node) do
		if k ~= "children" then copy[k] = v end
	end
	return json.encode(copy)
end

local function build(self, node, parent_inst, seen, z)
	seen[node.id] = true
	local entry = self.entries[node.id]
	local cls = class_for(node)
	if entry and entry.class ~= cls then
		self:_destroy_entry(node.id)
		entry = nil
	end
	if not entry then
		entry = { inst = self.factory.create(cls), class = cls }
		self.entries[node.id] = entry
		entry.inst.Name = node.id
		entry.sig = nil
	end
	local sig = signature(node)
	if entry.sig ~= sig then
		apply(self, entry, node)
		entry.sig = sig
	end
	connect(self, entry)
	if entry.inst.Parent ~= parent_inst then entry.inst.Parent = parent_inst end
	entry.inst.ZIndex = z or 1 -- explicit sibling order: later siblings (e.g. the dialog scrim) always draw on top
	for i, child in ipairs(node.children or {}) do
		build(self, child, entry.inst, seen, i)
	end
	return entry
end

function R:_destroy_entry(id)
	local entry = self.entries[id]
	if not entry then return end
	for _, c in ipairs(entry.conns or {}) do pcall(function() c:Disconnect() end) end
	pcall(function() entry.inst:Destroy() end)
	self.entries[id] = nil
end

-- render(root) builds or updates the whole tree; instances whose ids vanished are destroyed
function R:render(root)
	local seen = {}
	build(self, root, self.parent, seen, 1)
	local stale = {}
	for id in pairs(self.entries) do
		if not seen[id] then stale[#stale + 1] = id end
	end
	for _, id in ipairs(stale) do self:_destroy_entry(id) end
	self.root_id = root.id
end

function R:destroy()
	local ids = {}
	for id in pairs(self.entries) do ids[#ids + 1] = id end
	for _, id in ipairs(ids) do self:_destroy_entry(id) end
end

function R:count() local n = 0 for _ in pairs(self.entries) do n += 1 end return n end

return R
end
__factories["client.ui.scene"] = function(require)
-- A "scene" is a declarative tree describing the whole GUI:  { id, kind, rect, children, ... }.
--   kinds: frame | text | button | input | scroll | line
-- Pages build scenes from state; renderer.lua turns a scene into Roblox Instances; tools/render_scene.py draws it to PNG.
-- This module is pure Luau and contains the layout RULES (validate) that tests enforce on every page and window size.
local measure = require("client.ui.measure")
local tokens = require("client.ui.tokens")

local S = {}

function S.walk(node, fn, ox, oy, parent, parent_abs)
	ox, oy = ox or 0, oy or 0
	local abs = { x = ox + node.rect.x, y = oy + node.rect.y, w = node.rect.w, h = node.rect.h }
	fn(node, abs, parent, parent_abs)
	for _, c in ipairs(node.children or {}) do
		S.walk(c, fn, abs.x, abs.y, node, abs)
	end
end

function S.count(root)
	local n = 0
	S.walk(root, function() n += 1 end)
	return n
end

function S.find(root, id)
	local found
	S.walk(root, function(n) if n.id == id then found = n end end)
	return found
end

-- interactive nodes in reading order (depth first): the keyboard/focus order
function S.interactive(root)
	local out = {}
	S.walk(root, function(n)
		if (n.kind == "button" and not n.disabled and not n.loading and n.action) or (n.kind == "input" and not n.disabled) then out[#out + 1] = n end
	end)
	return out
end

local function inside(inner, outer) return inner.x >= outer.x and inner.y >= outer.y and inner.x + inner.w <= outer.x + outer.w and inner.y + inner.h <= outer.y + outer.h end
local function overlap(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end

local LEAF = { text = true, button = true, input = true }

-- validate(root, opts) -> list of problem strings. opts.max_nodes (default 1500)
function S.validate(root, opts)
	opts = opts or {}
	local problems = {}
	local function bad(n, msg) problems[#problems + 1] = string.format("[%s] %s", tostring(n.id), msg) end
	local ids, total = {}, 0

	S.walk(root, function(n, abs, parent, pabs)
		total += 1
		if ids[n.id] then bad(n, "duplicate id") end
		ids[n.id] = true
		local r = n.rect
		for _, k in ipairs({ "x", "y", "w", "h" }) do
			if type(r[k]) ~= "number" or r[k] ~= math.floor(r[k]) then bad(n, "non-integer " .. k) end
		end
		if r.w < 0 or r.h < 0 then bad(n, "negative size") end
		if not n.hairline then
			for _, k in ipairs({ "x", "y", "w", "h" }) do
				if r[k] % 4 ~= 0 then bad(n, string.format("%s=%s is off the 4px grid", k, tostring(r[k]))) end
			end
		end

		-- containment (a scroll parent scrolls vertically: its canvas is taller than its rect)
		if parent and pabs then
			local limit = pabs
			if parent.kind == "scroll" then limit = { x = pabs.x, y = pabs.y, w = pabs.w, h = math.max(pabs.h, parent.canvas_h or pabs.h) } end
			if not inside(abs, limit) then bad(n, string.format("outside its parent (%s)", tostring(parent.id))) end
			if parent.pad and not n.bleed and parent.kind == "frame" then
				local pad = parent.pad
				local inner = { x = pabs.x + pad, y = pabs.y + pad, w = pabs.w - 2 * pad, h = pabs.h - 2 * pad }
				if not inside(abs, inner) then bad(n, "violates the " .. pad .. "px padding of " .. tostring(parent.id)) end
			end
			if n.role == "primary_action" then
				local right = pabs.x + pabs.w - (parent.pad or 0)
				if abs.x + abs.w ~= right then bad(n, "primary action is not aligned to the right edge of its container") end
			end
		end

		-- text must fit unless it is allowed to truncate; wrapped text must fit its height
		if n.kind == "text" then
			if n.numeric and n.align ~= "right" then bad(n, "numeric text must be right aligned") end
			if n.wrap then
				local lines = measure.lines(n.text, n.size, n.font, r.w)
				if lines * n.line > r.h then bad(n, string.format("wrapped text needs %d lines (%dpx) but has %dpx", lines, lines * n.line, r.h)) end
			else
				if r.h < n.line then bad(n, "text box shorter than its line height") end
				if not n.truncate and measure.width(n.text, n.size, n.font) > r.w then
					bad(n, string.format("text '%s' (%dpx) does not fit %dpx and may not truncate", string.sub(n.text, 1, 24), measure.width(n.text, n.size, n.font), r.w))
				end
			end
		elseif n.kind == "button" then
			if r.h < 32 and not n.compact_ok then bad(n, "button shorter than 32px") end
			if n.label and measure.width(n.label, n.size or 13, n.font or "ui_medium") + 24 > r.w and not n.truncate then
				bad(n, string.format("label '%s' does not fit the button (%dpx)", n.label, r.w))
			end
			if not n.disabled and not n.loading and not n.action and n.style ~= "scrim" then bad(n, "enabled button without an action") end
		elseif n.kind == "input" then
			if r.h < 32 then bad(n, "input shorter than 32px") end
			if not n.disabled and not n.action then bad(n, "input without an action") end
		end

		-- siblings that carry content must not overlap each other
		local kids = n.children or {}
		for i = 1, #kids do
			local a = kids[i]
			if (LEAF[a.kind] or a.leaf) and not a.overlay then
				for j = i + 1, #kids do
					local b = kids[j]
					if (LEAF[b.kind] or b.leaf) and not b.overlay then
						local ra = { x = a.rect.x, y = a.rect.y, w = a.rect.w, h = a.rect.h }
						local rb = { x = b.rect.x, y = b.rect.y, w = b.rect.w, h = b.rect.h }
						if overlap(ra, rb) then bad(a, "overlaps sibling " .. tostring(b.id)) end
					end
				end
			end
		end
	end)
	if total > (opts.max_nodes or 1500) then problems[#problems + 1] = string.format("scene has %d nodes (budget %d)", total, opts.max_nodes or 1500) end
	return problems
end

return S
end
__factories["client.ui.shell"] = function(require)
-- Shell: turns the whole UI state into ONE scene tree (window, header, sidebar, page, dialog).
local C = require("client.ui.components")
local layout = require("client.ui.layout")
local tokens = require("client.ui.tokens")
local pa = require("client.ui.pages_a")
local pb = require("client.ui.pages_b")
local V = require("client.ui.viewmodel")

local Shell = {}
local SZ = tokens.size

local PAGES = {
	overview = pa.overview, scanner = pa.scanner, settings = pa.settings,
	findings = pb.findings, explorer = pb.explorer, tests = pb.tests, export = pb.export,
	graph = pb.graph, compare = pb.compare,
}

local function status_badge(st)
	local s = pa.SCAN_BADGE[st.scan.state]
	return { label = s[1], tone = s[2] }
end

-- build(state) -> root, meta.  meta carries facts the controller needs (e.g. table paging) without the view mutating state.
function Shell.build(state)
	local vw, vh = state.viewport.w, state.viewport.h
	if state.window.minimized then
		local w = SZ.minimized_w
		local root = { id = "root", kind = "frame", rect = { x = layout.snap(vw - w - SZ.screen_margin), y = SZ.screen_margin, w = w, h = SZ.header_h }, fill = "sidebar", stroke = "border", radius = 6, clip = true, children = {} }
		root.children[1] = C.header(w, nil, true)
		return root, {}
	end
	local win = layout.window(vw, vh)
	local shell = layout.shell(win)
	local root = { id = "root", kind = "frame", rect = win, fill = "bg", stroke = "border", radius = 6, clip = true, children = {} }
	local counts = { findings = #state.findings.list }
	root.children[1] = C.header(win.w, status_badge(state), false)
	root.children[2] = C.sidebar(shell, state.page, counts, state.info.version, state.window.toggle_key)

	local R = { x = SZ.content_pad, y = SZ.content_pad, w = shell.inner.w, h = shell.inner.h }
	local builder = PAGES[state.page] or PAGES.overview
	local nodes, bottom, meta = builder({ R = R, state = state, win = win, shell = shell })
	local content = C.scroll("content", { x = shell.content.x, y = shell.content.y, w = shell.content.w, h = shell.content.h }, bottom + SZ.content_pad)
	content.children = nodes
	content.pad = SZ.content_pad
	root.children[3] = content

	local m = state.manifest
	if m.confirm_open and m.plan then
		local ok = (m.confirm_input == m.plan.phrase)
		root.children[#root.children + 1] = C.dialog("dlg", win.w, win.h, {
			title = "Run approved active tests?",
			body = string.format("This sends up to %d call(s) to the %d endpoint(s) listed in the manifest (%s). Type the confirmation phrase exactly to continue:",
				m.plan.calls, m.plan.endpoints, m.plan.mode),
			phrase = m.plan.phrase,
			input = { value = m.confirm_input or "", placeholder = "Type the phrase", action = { name = "manifest.confirm_input" } },
			checkbox = m.plan.mutating and { label = (m.reset_ack and "[x] " or "[ ] ") .. "I prepared the QA reset the manifest describes", value = m.reset_ack == true, action = { name = "manifest.reset_ack" } } or nil,
			buttons = { { label = "Cancel", style = "secondary", action = { name = "manifest.run_cancel" } },
				{ label = "Run Active Test", style = "danger", disabled = not ok or (m.plan.mutating and not m.reset_ack), action = { name = "manifest.run" } } },
		})
	end
	return root, meta or {}
end

return Shell
end
__factories["client.ui.store"] = function(require)
-- UI state container. One table, one subscriber list. No Roblox, no business logic (that lives in controller.lua).
local Store = {}

function Store.new_state(init)
	init = init or {}
	return {
		now = init.now or 0, started_at = init.now or 0, page = "overview",
		viewport = init.viewport or { w = 1366, h = 768 },
		window = { minimized = false, visible = true, toggle_key = nil },
		info = init.info or {
			version = "0.0.0", build_id = "-", integrity = "unverified", executor = "unknown", mode = "passive",
			caps = {}, config = { minimize = true, anonymize = true },
		},
		scan = { state = "idle", visited = nil, observed = nil, candidates = nil, elapsed = 0, error = nil, started = nil },
		log = {},
		findings = { list = {}, sort = { key = "severity", dir = "desc" }, filter = { severity = nil, text = "" }, selected = nil, page = 1 },
		manifest = { state = "none", path_input = "ShadowScan/manifest.json", errors = {}, summary = nil, gate_reasons = {}, tests = {}, dry_run_done = false,
			run_state = "idle", page = 1, confirm_open = false, confirm_input = "", plan = nil },
		export = { report = nil, cipher = nil, token_input = "", port_input = "47821", companion = { state = "unknown", detail = nil },
			encryption = { state = "idle", detail = nil }, feedback = nil },
		explorer = { family = nil, sort = { key = "risk", dir = "desc" }, page = 1, version = 0 },
		graph = { selected = nil, page = 1 },
		snapshot = { path_input = "ShadowScan/out/snapshot-PLACE-STAMP.json", state = "idle", detail = nil, diff = nil },
		live = { running = false },
		busy = {},
	}
end

function Store.new(state)
	local self = { state = state, subs = {} }
	function self:subscribe(fn) self.subs[#self.subs + 1] = fn end
	function self:notify() for _, fn in ipairs(self.subs) do fn(self.state) end end
	return self
end

local MAX_LOG = 200
function Store.log(state, level, text, t)
	local log = state.log
	log[#log + 1] = { t = t or state.now, level = level or "info", text = tostring(text) }
	while #log > MAX_LOG do table.remove(log, 1) end
end

return Store
end
__factories["client.ui.styles"] = function(require)
-- Single source of truth for how a node LOOKS in each state. Used by the Roblox renderer and exported to the PNG preview,
-- so the preview and the real GUI cannot drift apart.
local tokens = require("client.ui.tokens")
local C = require("client.ui.components")

local S = {}
local K = tokens.color

local function raised_hover() return C.mix("border_strong", "panel_raised", 0.45) end

-- returns { fill, fill_hover, fill_down, text, text_hover, stroke, bar, alpha }
function S.button(node)
	local style = node.style or "secondary"
	if style == "scrim" then return { fill = K.overlay, alpha = node.alpha or 0.6 } end
	if node.disabled or node.loading then
		return { fill = K.disabled_bg, text = node.loading and K.text_muted or K.text_disabled }
	end
	-- filled controls use accent_fill (white text >= 4.5:1); the brand accent #7565E8 is the hover state, ring and bar colour
	if style == "primary" then return { fill = K.accent_fill, fill_hover = K.accent_fill_hover, fill_down = K.accent_fill_pressed, text = K.on_accent } end
	if style == "danger" then
		local base = C.mix("error", "#000000", 0.5)
		return { fill = base, fill_hover = C.mix("error", "#000000", 0.62), fill_down = C.mix("error", "#000000", 0.42), text = K.on_accent, stroke = K.error }
	end
	if style == "ghost" then return { fill_hover = K.panel_raised, fill_down = K.border, text = K.text_muted, text_hover = K.text } end
	if style == "header" then return { fill_hover = K.panel, text = K.text_muted, text_hover = K.text } end
	if style == "nav" then
		if node.selected then return { fill = K.accent_soft, text = K.text, bar = K.accent } end
		return { fill_hover = K.panel_raised, fill_down = K.panel, text = K.text_muted, text_hover = K.text }
	end
	if style == "row" then
		if node.selected then return { fill = K.accent_soft, bar = K.accent, text = K.text } end
		return { fill_hover = K.panel_raised, fill_down = K.accent_soft, text = K.text }
	end
	if style == "segment" then
		if node.selected then return { fill = K.accent_soft, stroke = K.accent, text = K.text, fill_hover = K.accent_soft } end
		return { fill = K.panel_raised, stroke = K.border, text = K.text_muted, text_hover = K.text, fill_hover = raised_hover() }
	end
	if style == "toggle" then
		if node.selected then return { fill = K.accent_fill, fill_hover = K.accent_fill_hover, fill_down = K.accent_fill_pressed, text = K.on_accent } end
		return { fill = K.panel_raised, stroke = K.border, text = K.text_muted, fill_hover = raised_hover() }
	end
	return { fill = K.panel_raised, fill_hover = raised_hover(), fill_down = K.border, text = K.text, stroke = K.border_strong }
end

return S
end
