-- Pure view-model helpers: labels, tones, sorting, filtering, formatting. No Roblox, no state.
local util = require("client.util.util")

local V = {}

V.SEVERITY_LABEL = { high = "HIGH", medium = "MEDIUM", low = "LOW", informational = "INFO" }
V.SEVERITY_TONE = { high = "error", medium = "warning", low = "text", informational = "neutral" }
