local M = {}

M.null = setmetatable({}, { __tostring = function() return "null" end, __jsontype = "null" })
local OBJ_MT = { __jsontype = "object" }
local ARR_MT = { __jsontype = "array" }

function M.object(t) return setmetatable(t or {}, OBJ_MT) end
function M.array(t) return setmetatable(t or {}, ARR_MT) end

local MAX_DEPTH = 64

local function is_array(t)
	local mt = getmetatable(t)
	if mt == OBJ_MT then return false end
	if mt == ARR_MT then return true end
	local n, maxk = 0, 0
	for k in pairs(t) do
		if type(k) ~= "number" or k < 1 or k ~= math.floor(k) then return false end
		n += 1
		if k > maxk then maxk = k end
	end
	return n == maxk
end

local function fix_utf8_run(run)
	if utf8.len(run) then return run end
	local out, i, n = {}, 1, #run
	while i <= n do
		local len, bad = utf8.len(run, i)
		if len then
			out[#out + 1] = string.sub(run, i)
			break
		end
		if bad > i then out[#out + 1] = string.sub(run, i, bad - 1) end
		out[#out + 1] = "\u{FFFD}"
		i = bad + 1
	end
	return table.concat(out)
end

local ESC = { ['"'] = '\\"', ["\\"] = "\\\\", ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t", ["\b"] = "\\b", ["\f"] = "\\f" }

local function enc_string(s)
