		local arr = M.array({})
		pos = skip_ws(s, pos + 1)
		if string.sub(s, pos, pos) == "]" then return arr, pos + 1 end
		while true do
			local val
			val, pos = parse_value(s, pos, depth + 1)
			arr[#arr + 1] = val
			pos = skip_ws(s, pos)
			local d = string.sub(s, pos, pos)
			if d == "," then pos += 1
			elseif d == "]" then return arr, pos + 1
			else decode_error(s, pos, "expected ',' or ']'") end
		end
