-- Secret detection shared by the passive scanner and the report builder.
-- The Python side (reporting/redact.py) keeps an equivalent list; tests/fixtures/secret_samples.json
-- is checked against BOTH implementations so the lists cannot silently drift apart.
local M = {}

M.PATTERNS = {
	{ kind = "age_private_key", pattern = "AGE%-SECRET%-KEY%-1[%u%d]+" },
	{ kind = "roblosecurity_cookie", pattern = "_|WARNING:%-DO%-NOT%-SHARE%-THIS" },
	{ kind = "roblosecurity_name", pattern = "%.ROBLOSECURITY" },
	{ kind = "private_key_block", pattern = "%-%-%-%-%-BEGIN [%u ]*PRIVATE KEY%-%-%-%-%-" },
	{ kind = "bearer_token", pattern = "[Bb]earer%s+[%w%._%-]+%.[%w%._%-]+" },
	{ kind = "discord_webhook", pattern = "discord[app]*%.com/api/webhooks/%d+/[%w_%-]+" },
	{ kind = "pairing_token", pattern = "ssp_[%w_%-]+" },
	{ kind = "aws_access_key", pattern = "AKIA[%u%d]+" },
}

-- Returns kind of first pattern found, or nil.
function M.find(s)
	if type(s) ~= "string" then return nil end
	for _, p in ipairs(M.PATTERNS) do
		local a, b = string.find(s, p.pattern)
		if a then
			-- pairing_token / aws need minimum length to avoid flagging innocuous words
			if p.kind == "pairing_token" and (b - a + 1) < 24 then
				-- too short, ignore
			elseif p.kind == "aws_access_key" and (b - a + 1) ~= 20 then
				-- not an AWS key shape
			else
				return p.kind
			end
		end
	end
	return nil
end

