end

function M.sorted_keys(t)
	local keys = {}
	for k in pairs(t) do keys[#keys + 1] = k end
	table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
	return keys
end

function M.count(t)
	local n = 0
	for _ in pairs(t) do n += 1 end
	return n
end

function M.list_contains(list, value)
	for _, x in ipairs(list) do
		if x == value then return true end
	end
	return false
end

function M.set(list)
	local s = {}
	for _, x in ipairs(list) do s[x] = true end
	return s
end

function M.startswith(s, prefix) return string.sub(s, 1, #prefix) == prefix end

-- ---------------------------------------------------------------- time
local function days_from_civil(y, m, d)
	if m <= 2 then y -= 1 end
	local era = math.floor(y / 400)
	local yoe = y - era * 400
	local mp = (m + 9) % 12
	local doy = math.floor((153 * mp + 2) / 5) + d - 1
	local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
	return era * 146097 + doe - 719468
end

-- "2026-10-24T13:00:00Z" -> unix seconds (UTC) or nil when malformed.
function M.iso_to_unix(s)
	if type(s) ~= "string" then return nil end
	local y, mo, d, h, mi, se = string.match(s, "^(%d%d%d%d)%-(%d%d)%-(%d%d)T(%d%d):(%d%d):(%d%d)Z$")
	if not y then return nil end
	y, mo, d, h, mi, se = tonumber(y), tonumber(mo), tonumber(d), tonumber(h), tonumber(mi), tonumber(se)
	if mo < 1 or mo > 12 or d < 1 or d > 31 or h > 23 or mi > 59 or se > 60 then return nil end
	return days_from_civil(y, mo, d) * 86400 + h * 3600 + mi * 60 + se
end

function M.unix_to_iso(t)
	return os.date("!%Y-%m-%dT%H:%M:%SZ", math.floor(t))
end

-- UTC "YYYYMMDD_HHMMSS" stamp for export file names (e.g. ShadowScan_Audit_20261107_093012.txt)
function M.audit_stamp(t)
	return os.date("!%Y%m%d_%H%M%S", math.floor(t))
end

-- ---------------------------------------------------------------- randomness (identifiers only, never secrets)
function M.rand_hex(nbytes, rnd)
	rnd = rnd or math.random
	local out = {}
	for i = 1, nbytes do out[i] = string.format("%02x", rnd(0, 255)) end
	return table.concat(out)
end

-- ---------------------------------------------------------------- text
function M.trim(s) return (string.gsub(s, "^%s*(.-)%s*$", "%1")) end

-- Truncate to n bytes on a UTF-8 boundary and strip control characters.
function M.clean_text(s, n)
	s = tostring(s)
	s = string.gsub(s, "%c", " ")
	if #s > n then
		s = string.sub(s, 1, n)
		while #s > 0 and string.find(string.sub(s, -1), "[\128-\191]") do s = string.sub(s, 1, -2) end
		if #s > 0 and string.find(string.sub(s, -1), "[\192-\255]") then s = string.sub(s, 1, -2) end
		s = s .. "..."
	end
	return s
end

-- Split an identifier ("GiveMoneyToPlayer", "buy_item2") into lowercase alphabetic tokens.
function M.tokenize(s)
	s = tostring(s)
	s = string.gsub(s, "(%l)(%u)", "%1 %2")
	s = string.gsub(s, "(%u)(%u%l)", "%1 %2")
	local tokens = {}
	for w in string.gmatch(string.lower(s), "%a+") do tokens[#tokens + 1] = w end
	return tokens
end

-- words: set of exact tokens; prefixes: list of prefixes (>= 5 chars recommended). Returns matched token or nil.
function M.match_tokens(tokens, words, prefixes)
	for _, tok in ipairs(tokens) do
		if words and words[tok] then return tok end
		if prefixes then
			for _, p in ipairs(prefixes) do
				if string.sub(tok, 1, #p) == p then return tok end
			end
		end
	end
	return nil
end

function M.last_segment(path)
	return string.match(path, "([^%.]+)$") or path
end

function M.parent_path(path)
	return string.match(path, "^(.*)%.[^%.]+$")
end

-- severity / confidence ordering
M.SEVERITY_ORDER = { informational = 1, low = 2, medium = 3, high = 4 }
M.CONFIDENCE_ORDER = { low = 1, medium = 2, high = 3 }

function M.max_by_order(order, a, b)
	if a == nil then return b end
	if b == nil then return a end
	return (order[a] >= order[b]) and a or b
end

function M.min_by_order(order, a, b)
	return (order[a] <= order[b]) and a or b
end

return M
end
__factories["reporting.report_builder"] = function(require)
-- Assembles the structured audit report (schema 1.1) from an audit state.
-- Data minimisation is ON by default: no JobId, no executor details, anonymous tester, only observations that back a finding.
-- 1.1 adds OPTIONAL blocks (findings may carry classification/risk; relationships; summary.snapshot_diff).
-- Every string passes through secret redaction before the report leaves this module.
local json = require("client.util.json")
local util = require("client.util.util")
local secrets = require("client.util.secrets")
local rules = require("scanner.rules")
local analyzer = require("scanner.analyzer")
local graph_mod = require("scanner.graph")

local B = {}

B.SCHEMA_VERSION = "1.1"
B.VERDICT_KEYS = { "CANDIDATE", "NOT_TESTED", "TESTED_REJECTED", "TESTED_ACCEPTED", "CONFIRMED", "INCONCLUSIVE" }

local STATIC_LIMITATIONS = {
	"Black-box, client-side view only: server code, server-side validation and data that is not replicated to clients cannot be observed.",
	"Findings are candidates for review. A name, a location or the existence of an object is never evidence of a vulnerability.",
	"A single session from one player's perspective cannot prove that a game has no vulnerabilities.",
	"Executor compatibility is UNVERIFIED: ShadowScan has only been exercised against a mock environment, not against real executors or Roblox.",
}

local function limitations(state)
	local out = {}
	for _, l in ipairs(STATIC_LIMITATIONS) do out[#out + 1] = l end
	local scan = state.scan
	if scan and scan.stats.cancelled then out[#out + 1] = "The scan was cancelled by the tester; this inventory is PARTIAL and must not be read as complete." end
	if scan and scan.stats.truncated then out[#out + 1] = "Inventory was truncated at the configured object limit; some objects were not visited." end
	if scan and scan.stats.depth_limited > 0 then out[#out + 1] = "Some subtrees were deeper than the depth limit and were not traversed." end
	if scan and scan.stats.skipped_player_owned > 0 then out[#out + 1] = "Player-owned character models were skipped to avoid collecting player data." end
	if scan and scan.stats.live_recorded and scan.stats.live_recorded > 0 then
		out[#out + 1] = string.format("%d object(s) appeared via passive live observation after the walk; the inventory covers the walk plus those events.", scan.stats.live_recorded)
	end
	if not scan then out[#out + 1] = "No passive inventory was performed for this audit." end
	if state.mode == "passive" then out[#out + 1] = "No active tests were run; every finding is an untested candidate." end
	if state.mode == "active_dry_run" then out[#out + 1] = "Only a dry run was performed; no request was sent to any endpoint." end
	if state.counts and state.counts.blocked and state.counts.blocked > 0 then out[#out + 1] = "Some test cases were blocked by safety gates and were not executed." end
	if state.minimize then out[#out + 1] = "Data minimisation was enabled: observations not backing a finding are counted but not listed." end
	return out
end

local function count_tests(runs)
	local c = { planned = 0, executed = 0, skipped = 0, blocked = 0, failed = 0, dry_run = 0 }
	for _, r in ipairs(runs) do
		c.planned += 1
		if r.status == "executed" then c.executed += 1
		elseif r.status == "failed" then c.executed += 1; c.failed += 1
		elseif r.status == "skipped" then c.skipped += 1
		elseif r.status == "blocked" then c.blocked += 1
		elseif r.status == "dry_run" then c.dry_run += 1 end
	end
	return c
end

local function derive_status(state, counts)
	if state.blocked then return "blocked" end
	if state.scan and state.scan.stats.cancelled then return "aborted" end
	if not state.scan and #state.test_runs == 0 then return "aborted" end
	if #state.errors > 0 or counts.failed > 0 or (state.scan and state.scan.stats.truncated) then return "completed_with_errors" end
	return "completed"
end

-- state fields used: audit_id, started_utc, finished_utc, mode, minimize, anonymize, tester_label, include_job_id,
-- tool{version,build_id,bundle_sha256}, target{game_id,place_id,job_id,target_mode,target_check}, caps, scan, findings, test_runs,
-- manifest_info, errors, blocked
function B.build(state)
	local observations_all = state.scan and state.scan.observations or {}
	local findings = state.findings or {}
	local runs = state.test_runs or {}
	local counts = count_tests(runs)

	local referenced = {}
	for _, f in ipairs(findings) do for _, id in ipairs(f.observation_ids) do referenced[id] = true end end
	local listed = {}
	for _, o in ipairs(observations_all) do
		if not state.minimize or referenced[o.obs_id] then listed[#listed + 1] = o end
	end

	local fsum = analyzer.summarize(findings)
	local verdicts = {}
	for _, k in ipairs(B.VERDICT_KEYS) do verdicts[k] = 0 end
	for _, f in ipairs(findings) do verdicts[f.verdict] += 1 end

	local by_class = json.object({})
	if state.scan then for k, v in pairs(state.scan.stats.by_class) do by_class[k] = v end end

	-- relationships (0.3.0): factual, structure-derived; compact listing of the busiest containers
	local relationships = nil
	if state.scan and #state.scan.observations > 0 then
		local graph = graph_mod.build(state.scan.observations)
		local containers, total = graph_mod.listing(graph, 50, 20)
		relationships = {
			stats = {
				remotes = graph.stats.remotes, containers = graph.stats.containers,
				nodes = graph.stats.nodes, edges = graph.stats.edges, truncated = graph.stats.truncated,
				listed_containers = #containers, containers_total = total,
			},
			containers = containers,
		}
	end

	-- snapshot diff (0.3.0): included when the tester compared this audit against a saved snapshot
	local snapshot_diff = nil
	if state.snapshot_diff then
		local d = state.snapshot_diff
		local function cap(list, n)
			local out = {}
			for i, x in ipairs(list) do if i > n then break end out[i] = x end
			return out
		end
		snapshot_diff = {
			previous_created_utc = d.previous_created_utc, compared_utc = d.compared_utc,
			previous_snapshot_version = d.previous_snapshot_version,
			added_count = d.added_count, removed_count = d.removed_count,
			changed_count = d.changed_count or 0, moved_count = d.moved_count or 0,
			added = cap(d.added, 50), removed = cap(d.removed, 50),
			changed = cap(d.changed or {}, 50), moved = cap(d.moved or {}, 50),
			note = d.note,
			previous_remote_count = d.previous_remote_count, current_remote_count = d.current_remote_count,
		}
	end

	-- compatibility report (0.4.0): counts for every capability + the unsupported/failed items (bounded)
	local compat_block = nil
	if state.compat then
		local c = state.compat.counts or {}
		local items = {}
		for _, it in ipairs(state.compat.capabilities or {}) do
			if it.status == "unsupported" or it.status == "failed_init" or it.status == "partial" then
				if #items < 25 then items[#items + 1] = it end
			end
		end
		compat_block = {
			counts = { supported = c.supported or 0, unsupported = c.unsupported or 0, partial = c.partial or 0,
				not_tested = c.not_tested or 0, failed_init = c.failed_init or 0 },
			notable = items,
		}
	end

	local t = state.target
	local report = {
		report_schema_version = B.SCHEMA_VERSION,
		audit = {
			audit_id = state.audit_id,
			tool = { name = "ShadowScan", version = state.tool.version, build_id = state.tool.build_id, bundle_sha256 = state.tool.bundle_sha256 or "unverified" },
			started_utc = state.started_utc,
			finished_utc = state.finished_utc,
			mode = state.mode,
			status = derive_status(state, counts),
			tester_label = state.anonymize and "anonymous" or (state.tester_label or "tester"),
		},
		target = {
			game_id = t.game_id or json.null,
			place_id = t.place_id or json.null,
			job_id = (state.include_job_id and t.job_id and t.job_id ~= "") and t.job_id or json.null,
			target_mode = t.target_mode or "unspecified",
			target_check = t.target_check or "not_run",
		},
		environment = {
			executor = (not state.minimize and state.caps) and { name = state.caps.executor_name or "unknown", version = state.caps.executor_version or json.null } or json.null,
			capabilities = {
				http = state.caps and state.caps.request ~= nil or false,
				readfile = state.caps and state.caps.readfile ~= nil or false,
				writefile = state.caps and state.caps.writefile ~= nil or false,
			},
			data_minimization = state.minimize == true,
			unverified_executor = true,
			compatibility = compat_block or json.null,
			performance_profile = state.profile or json.null,
		},
		summary = {
			objects_visited = state.scan and state.scan.stats.visited or 0,
			objects_observed = #observations_all,
			observations_included = #listed,
			observations_by_class = by_class,
			candidates_total = fsum.total,
			candidates_by_category = fsum.by_category,
			candidates_by_severity = fsum.by_severity,
			tests = counts,
			verdicts = verdicts,
			redactions = 0,
			scan_truncated = state.scan and state.scan.stats.truncated or false,
			scan_cancelled = state.scan and state.scan.stats.cancelled or false,
		},
		observations = listed,
		findings = findings,
		test_runs = runs,
		manifest = state.manifest_info or json.null,
		relationships = relationships or json.null,
		limitations = limitations(state),
		errors = state.errors,
	}
	if snapshot_diff then report.summary.snapshot_diff = snapshot_diff end

	-- normalise empty containers so they encode as {} / []
	report.summary.observations_by_class = json.object(report.summary.observations_by_class)
	report.summary.candidates_by_category = json.object(report.summary.candidates_by_category)
	report.summary.candidates_by_severity = json.object(report.summary.candidates_by_severity)
	report.summary.verdicts = json.object(report.summary.verdicts)
	for _, o in ipairs(report.observations) do o.metadata = json.object(o.metadata or {}) end
	for _, r in ipairs(report.test_runs) do
		r.actual_outcome.details = json.array(r.actual_outcome.details)
		r.actual_outcome.call_outcomes = json.array(r.actual_outcome.call_outcomes)
	end

	local redacted, n = secrets.redact_deep(report)
	redacted.summary.redactions = n
	return redacted
end

function B.to_json(report, pretty) return json.encode(report, pretty) end

return B
end
__factories["scanner.active_runner"] = function(require)
-- ACTIVE test runner. Fires ONLY endpoints listed in a validated, unexpired manifest, behind these gates:
--   target (GameId/PlaceId/private-server) -> dry-run preview -> explicit confirmation bound to the exact plan
--   -> per-test gates (QA reset, class match, allowlist) -> call/interval/duration limits -> stop conditions.
-- There is deliberately NO function here that accepts an observed object or enumerates remotes to fire:
-- the only way to send anything is a manifest test case. No payload generation, no retries-until-success.
local json = require("client.util.json")
local sha256 = require("client.util.sha256")
local util = require("client.util.util")
local validator = require("test_manifest.validator")
local verdict = require("scanner.verdict")

local R = {}

R.INVOKE_TIMEOUT_SECONDS = 10

local function fingerprint(args) return sha256.hex(json.encode(args)) end

-- ---------------------------------------------------------------- planning
-- target = { game_id, place_id, job_id, private_server_id }
function R.check_target(manifest, target)
	local reasons = {}
	local mt = manifest.target
	if target.game_id ~= mt.game_id then
		reasons[#reasons + 1] = string.format("GameId mismatch (manifest %s, current %s)", tostring(mt.game_id), tostring(target.game_id))
	end
	local place_ok = false
	for _, p in ipairs(mt.place_ids) do if p == target.place_id then place_ok = true end end
	if not place_ok then reasons[#reasons + 1] = string.format("PlaceId %s is not in the manifest allowlist", tostring(target.place_id)) end
	if mt.mode == "private_qa" then
		local qa = mt.qa or {}
		if qa.require_private_server == true and (target.private_server_id == nil or target.private_server_id == "") then
			reasons[#reasons + 1] = "manifest requires a private server but this is a public server"
		end
		if qa.allowed_job_ids ~= nil then
			local found = false
			for _, j in ipairs(qa.allowed_job_ids) do if j == target.job_id then found = true end end
			if not found then reasons[#reasons + 1] = "current server JobId is not in manifest allowed_job_ids" end
		end
	end
	return #reasons == 0, reasons
end

-- new_plan(manifest, ctx) -> plan | nil, errors.   ctx = { target = {...}, now_unix = number }
function R.new_plan(manifest, ctx)
	local ok, errs = validator.validate(manifest, { now_unix = ctx.now_unix })
	if not ok then return nil, errs end
	local gate_ok, reasons = R.check_target(manifest, ctx.target)

	local allowlist, tests = {}, {}
	for i, tc in ipairs(manifest.test_cases) do
		allowlist[tc.endpoint.path] = tc.endpoint.class
		local native = {}
		for k = 1, #tc.args do native[k] = json.to_native(tc.args[k]) end
		tests[i] = {
			test_id = tc.test_id, title = tc.title, path = tc.endpoint.path, class = tc.endpoint.class, is_canary = tc.endpoint.is_canary,
			test_type = tc.test_type, args = tc.args, native_args = native, arg_count = #tc.args, args_fingerprint = fingerprint(tc.args),
			mutates_state = tc.mutates_state, max_calls = tc.max_calls, min_interval_seconds = tc.min_interval_seconds,
			expected_outcome = tc.expected_outcome, evidence = tc.evidence, confirmable = tc.confirmable,
		}
	end
	local manifest_sha = sha256.hex(json.encode(manifest))
	local canon = { manifest_sha256 = manifest_sha, target = { game_id = ctx.target.game_id, place_id = ctx.target.place_id }, tests = {} }
	for i, t in ipairs(tests) do
		canon.tests[i] = { id = t.test_id, path = t.path, class = t.class, type = t.test_type, args = t.args_fingerprint, calls = t.max_calls,
			interval = t.min_interval_seconds, mutates = t.mutates_state, expected = t.expected_outcome, channel = t.evidence.channel }
	end
	local plan_hash = sha256.hex(json.encode(canon))
	local mid = manifest.manifest.manifest_id
	return {
		manifest_id = mid, manifest_version = manifest.manifest.version, manifest_sha256 = manifest_sha,
		mode = manifest.target.mode, qa = manifest.target.qa, limits = manifest.limits, stop_conditions = manifest.stop_conditions,
		tests = tests, allowlist = allowlist, target = ctx.target, gate = { ok = gate_ok, reasons = reasons },
		plan_hash = plan_hash, required_confirmation = "APPROVE " .. mid .. " " .. string.sub(plan_hash, 1, 8),
	}
end

-- Human-readable preview. Pure text, sends nothing.
function R.preview_lines(plan)
	local lines = {
		string.format("Manifest %s v%s  mode=%s  plan=%s", plan.manifest_id, plan.manifest_version, plan.mode, string.sub(plan.plan_hash, 1, 8)),
		string.format("Limits: <=%d total calls, >=%ss between calls, <=%ss total", plan.limits.max_total_calls, tostring(plan.limits.min_interval_seconds), tostring(plan.limits.max_duration_seconds)),
		"Target check: " .. (plan.gate.ok and "PASSED" or ("FAILED - " .. table.concat(plan.gate.reasons, "; "))),
	}
	for _, t in ipairs(plan.tests) do
		lines[#lines + 1] = string.format("  %s  %s %s  type=%s calls<=%d interval>=%ss mutates=%s expect=%s evidence=%s",
			t.test_id, t.class, t.path, t.test_type, t.max_calls, tostring(t.min_interval_seconds), tostring(t.mutates_state), t.expected_outcome, t.evidence.channel)
	end
	lines[#lines + 1] = "To run for real, call active_run with confirm = \"" .. plan.required_confirmation .. "\""
	return lines
end

-- ---------------------------------------------------------------- evidence helpers
local function walk_field(v, field)
	if field == nil or field == "" then return v end
	local cur = v
	for seg in string.gmatch(field, "[^%.]+") do
		if type(cur) ~= "table" then return nil end
		cur = cur[seg]
	end
	return cur
end

local function matcher_hits(m, v)
	local target = walk_field(v, m.field)
	if m.equals ~= nil then
		local want = json.to_native(m.equals)
		if type(want) == "table" or type(target) == "table" then return false end -- primitives only
		return target == want
	elseif m.exists ~= nil then
		return (target ~= nil) == m.exists
	elseif m.type_is ~= nil then
		return type(target) == m.type_is
	end
	return false
end

local function classify_response(ev, response)
	local a, r = matcher_hits(ev.accepted_when, response), matcher_hits(ev.rejected_when, response)
	if a and not r then return "accepted" end
	if r and not a then return "rejected" end
	return "unknown"
end

local function change_hits(kind, before, after)
	if kind == "unchanged" then return before == after end
	if kind == "changed" then return before ~= after end
	if type(before) ~= "number" or type(after) ~= "number" then return false end
	if kind == "increase" then return after > before end
	if kind == "decrease" then return after < before end
	return false
end

local function read_probe(env, probe)
	local inst = env.resolve(probe.target_path)
	if not inst then return false end
	local ok, v = pcall(function()
		if probe.kind == "attribute" then return inst:GetAttribute(probe.name) end
		return inst[probe.name]
	end)
	return ok, v
end

local function safe_value(v)
	local t = type(v)
	if t == "number" or t == "boolean" then return v end
	if t == "string" then return util.clean_text(v, 64) end
	return t
end

-- ---------------------------------------------------------------- execution
local function do_call(inst, class, test, env)
	if class == "RemoteFunction" then
		local done, ok, res = false, false, nil
		env.spawn(function()
			ok, res = pcall(function() return inst:InvokeServer(table.unpack(test.native_args, 1, test.arg_count)) end)
			done = true
		end)
		local t0 = env.clock()
		while not done and env.clock() - t0 < R.INVOKE_TIMEOUT_SECONDS do env.wait(0.1) end
		if not done then return false, "timeout waiting for InvokeServer" end
		return ok, res
	end
	local ok, err = pcall(function() inst:FireServer(table.unpack(test.native_args, 1, test.arg_count)) end)
	return ok, err
end

local function new_record(plan, test, idx)
	return {
		run_id = string.format("TR-%03d", idx), test_id = test.test_id, title = test.title, endpoint_path = test.path,
		endpoint_class = test.class, test_type = test.test_type, mutates_state = test.mutates_state,
		plan = { max_calls = test.max_calls, min_interval_seconds = test.min_interval_seconds, arg_count = test.arg_count, args_fingerprint = test.args_fingerprint },
		expected_outcome = test.expected_outcome, evidence_channel = test.evidence.channel, confirmable = test.confirmable,
		status = "skipped", actual_outcome = { observed = "none", calls_made = 0, call_outcomes = {}, details = {} },
		verdict = "NOT_TESTED", confidence = "low", reason = "", expectation_mismatch = false, stop_reason = nil,
	}
end

local function finalize(rec, test, error_msg, aborted)
	local res = verdict.resolve({
		ran = rec.actual_outcome.calls_made > 0, error = error_msg, aborted = aborted, expected = test.expected_outcome,
		channel = test.evidence.channel, confirmable = test.confirmable, test_type = test.test_type, call_outcomes = rec.actual_outcome.call_outcomes,
	})
	rec.verdict, rec.confidence, rec.reason, rec.expectation_mismatch = res.verdict, res.confidence, res.reason, res.expectation_mismatch
	rec.actual_outcome.observed = res.observed_outcome
end

local function run_one(plan, test, idx, env, opts, state)
	local rec = new_record(plan, test, idx)
	local function block(why) rec.status, rec.reason, rec.stop_reason = "blocked", why, why return rec end
	local function skip(why) rec.status, rec.reason, rec.stop_reason = "skipped", why, why return rec end

	if test.mutates_state and not opts.reset_confirmed then
		return block("mutating test blocked: reset procedure not confirmed (pass reset_confirmed=true after preparing the QA reset)")
	end
	if plan.allowlist[test.path] ~= test.class then return block("endpoint is not in the manifest allowlist") end
	if state.total_calls >= plan.limits.max_total_calls then return skip("global call limit reached") end
	if env.clock() - state.started > plan.limits.max_duration_seconds then return skip("max duration reached") end

	local inst = env.resolve(test.path)
	if not inst then return block("endpoint not found in this server (nothing was sent)") end
	local okc, cls = pcall(function() return inst.ClassName end)
	if not okc or cls ~= test.class then return block("endpoint class mismatch (manifest " .. test.class .. ", found " .. tostring(cls) .. ")") end

	local ev = test.evidence
	local telemetry_conn, queue = nil, {}
	if ev.channel == "qa_telemetry" then
		-- listening on a developer-provided telemetry RemoteEvent is passive: nothing is sent to it
		local tinst = env.resolve(ev.telemetry.remote_path)
		if not tinst or tinst.ClassName ~= "RemoteEvent" then return block("telemetry remote not found or not a RemoteEvent (nothing was sent)") end
		telemetry_conn = tinst.OnClientEvent:Connect(function(msg) queue[#queue + 1] = msg end)
	end

	rec.status = "executed"
	local error_msg, aborted = nil, false
	for i = 1, test.max_calls do
		if state.total_calls >= plan.limits.max_total_calls then rec.stop_reason = "global call limit reached" aborted = true break end
		if env.clock() - state.started > plan.limits.max_duration_seconds then rec.stop_reason = "max duration reached" aborted = true break end
		-- enforce spacing between ANY two calls of this run
		if state.last_call_at then
			local gap = env.clock() - state.last_call_at
			local need = math.max(test.min_interval_seconds, plan.limits.min_interval_seconds)
			if gap < need then env.wait(need - gap) end
		end

		local before_ok, before = false, nil
		if ev.channel == "observable_state" then before_ok, before = read_probe(env, ev.probe) end

		-- one authoritative allowlist check immediately before sending
		if plan.allowlist[test.path] ~= test.class then error_msg = "allowlist check failed before send" break end
		state.total_calls += 1
		state.last_call_at = env.clock()
		local ok, res = do_call(inst, test.class, test, env)
		rec.actual_outcome.calls_made += 1
		if not ok then
			error_msg = tostring(res)
			rec.status = "failed"
			rec.stop_reason = "call raised an error"
			break
		end

		local outcome = "unknown"
		if ev.channel == "response_value" then
			outcome = classify_response(ev, res)
			rec.actual_outcome.details[#rec.actual_outcome.details + 1] = { call = i, response_type = type(res) }
		elseif ev.channel == "observable_state" then
			env.wait(ev.probe.settle_seconds or 1)
			local after_ok, after = read_probe(env, ev.probe)
			if before_ok and after_ok then
				local a, r = change_hits(ev.accepted_when.change, before, after), change_hits(ev.rejected_when.change, before, after)
				if a and not r then outcome = "accepted" elseif r and not a then outcome = "rejected" end
				rec.actual_outcome.details[#rec.actual_outcome.details + 1] = { call = i, before = safe_value(before), after = safe_value(after) }
			else
				rec.actual_outcome.details[#rec.actual_outcome.details + 1] = { call = i, note = "state probe unreadable" }
			end
		elseif ev.channel == "qa_telemetry" then
			local t0, got = env.clock(), nil
			while not got and env.clock() - t0 < ev.telemetry.timeout_seconds do
				for qi, msg in ipairs(queue) do
					if type(msg) == "table" and msg.test_id == test.test_id and (msg.outcome == "accepted" or msg.outcome == "rejected") then
						got = msg.outcome
						table.remove(queue, qi)
						break
					end
				end
				if not got then env.wait(0.1) end
			end
			if got then outcome = got end
			rec.actual_outcome.details[#rec.actual_outcome.details + 1] = { call = i, telemetry = got or "timeout" }
		end
		rec.actual_outcome.call_outcomes[#rec.actual_outcome.call_outcomes + 1] = outcome

		if outcome == "unknown" and test.evidence.channel ~= "none" then rec.stop_reason = "outcome could not be classified" aborted = true break end
		if test.test_type == "rate_limit_probe" and outcome == "rejected" then rec.stop_reason = "rate limit engaged; probing stopped" break end
	end
	if telemetry_conn then telemetry_conn:Disconnect() end

	finalize(rec, test, error_msg, aborted)
	return rec
end

-- execute(plan, env, opts) -> { status, reason, test_runs, counts }
-- env  = { resolve(path)->inst, wait(s), clock()->s, spawn(fn) }
-- opts = { dry_run, confirm, reset_confirmed }
function R.execute(plan, env, opts)
	opts = opts or {}
	local out = { status = "blocked", reason = nil, test_runs = {} }
	local function mark_all(status, why)
		for i, t in ipairs(plan.tests) do
			local rec = new_record(plan, t, i)
			rec.status, rec.reason, rec.stop_reason = status, why, why
			out.test_runs[#out.test_runs + 1] = rec
		end
	end

	if not plan.gate.ok then
		out.reason = "target check failed: " .. table.concat(plan.gate.reasons, "; ")
		mark_all("blocked", out.reason)
	elseif opts.dry_run then
		out.status = "dry_run"
		mark_all("dry_run", "dry run only; no request was sent")
	elseif opts.confirm ~= plan.required_confirmation then
		out.reason = "confirmation gate not met"
		mark_all("blocked", out.reason)
	else
		out.status = "complete"
		local state = { total_calls = 0, started = env.clock(), last_call_at = nil }
		local halt = nil
		for i, t in ipairs(plan.tests) do
			if halt then
				local rec = new_record(plan, t, i)
				rec.status, rec.reason, rec.stop_reason = "skipped", halt, halt
				out.test_runs[#out.test_runs + 1] = rec
			else
				local rec = run_one(plan, t, i, env, opts, state)
				out.test_runs[#out.test_runs + 1] = rec
				local sc = plan.stop_conditions
				if rec.status == "failed" and sc.stop_on_error then halt = "stopped: error in " .. t.test_id end
				if rec.status == "executed" or rec.status == "failed" then
					local unexpected = rec.expectation_mismatch or rec.verdict == "CONFIRMED" or rec.verdict == "TESTED_ACCEPTED" and t.expected_outcome == "rejected"
					if sc.stop_on_unexpected_outcome and (unexpected or rec.verdict == "INCONCLUSIVE") and not halt then
						halt = "stopped: unexpected outcome in " .. t.test_id
					elseif sc.stop_on_inconclusive and rec.verdict == "INCONCLUSIVE" and not halt then
						halt = "stopped: inconclusive result in " .. t.test_id
					end
				end
				if state.total_calls >= plan.limits.max_total_calls and not halt then halt = "global call limit reached" end
			end
		end
		out.reason = halt
		out.total_calls = state.total_calls
	end
	out.counts = R.counts(out.test_runs)
	return out
end

function R.counts(runs)
	local c = { planned = #runs, executed = 0, skipped = 0, blocked = 0, failed = 0, dry_run = 0 }
	for _, r in ipairs(runs) do
		if r.status == "executed" then c.executed += 1
		elseif r.status == "failed" then c.executed += 1; c.failed += 1
		elseif r.status == "skipped" then c.skipped += 1
		elseif r.status == "blocked" then c.blocked += 1
		elseif r.status == "dry_run" then c.dry_run += 1 end
	end
	return c
end

-- attach test run results to findings by endpoint path, then recompute each finding's verdict
function R.attach_to_findings(findings, runs)
	local by_path = {}
	for _, f in ipairs(findings) do f.test_run_ids = {} end
	for _, f in ipairs(findings) do by_path[f.object_path] = by_path[f.object_path] or {}; table.insert(by_path[f.object_path], f) end
	for _, run in ipairs(runs) do
		run.finding_ids = {}
		for _, f in ipairs(by_path[run.endpoint_path] or {}) do
			f.test_run_ids[#f.test_run_ids + 1] = run.run_id
			run.finding_ids[#run.finding_ids + 1] = f.finding_id
		end
	end
	local run_by_id = {}
	for _, r in ipairs(runs) do run_by_id[r.run_id] = r end
	for _, f in ipairs(findings) do
		-- Only runs that probe for a violation (expected "rejected") decide a finding. A positive control
		-- (expected "accepted") that was accepted is NOT a security result; a broken one makes things inconclusive.
		local vs = {}
		for _, rid in ipairs(f.test_run_ids) do
			local r = run_by_id[rid]
			if r.status == "executed" or r.status == "failed" then
				if r.expected_outcome == "rejected" or r.verdict == "INCONCLUSIVE" then vs[#vs + 1] = r.verdict end
			end
		end
		f.verdict = verdict.aggregate(vs)
	end
end

return R
end
__factories["scanner.analyzer"] = function(require)
-- Turns observations into candidate findings. Pure function: same observations -> same findings.
-- The analyzer NEVER produces a verdict stronger than CANDIDATE. Only verdict.lua can, after a manifest-approved test.
-- 0.3.0: findings additionally carry a functional classification (hint-level) and an evidence-based risk score.
local util = require("client.util.util")
local rules = require("scanner.rules")
local classify = require("scanner.classify")
local risk = require("scanner.risk")

local A = {}

local WEAK_SEVERITY_CAP = "low"

function A.new_name_counts(observations)
	local counts = {}
	for _, o in ipairs(observations) do
		if rules.REMOTE_CLASSES[o.class_name] then
			local k = o.class_name .. "|" .. o.name
			counts[k] = (counts[k] or 0) + 1
		end
	end
	return counts
end

local function union_unknowns(hits)
	local seen, out = {}, {}
	for _, h in ipairs(hits) do
		for _, u in ipairs(h.unknowns or {}) do
			if not seen[u] then seen[u] = true; out[#out + 1] = u end
		end
	end
	return out
end

local function union_tests(hits)
	local seen, out = {}, {}
	for _, h in ipairs(hits) do
		for _, t in ipairs(h.tests or {}) do
			if not seen[t.test_type] then seen[t.test_type] = true; out[#out + 1] = { test_type = t.test_type, note = t.note } end
		end
	end
	return out
end

-- analyze(observations) -> findings (array)
function A.analyze(observations)
	local ctx = { name_counts = A.new_name_counts(observations) }
	local ordered = {}
	for _, o in ipairs(observations) do ordered[#ordered + 1] = o end
	table.sort(ordered, function(a, b)
		if a.path ~= b.path then return a.path < b.path end
		return a.obs_id < b.obs_id
	end)

	local findings = {}
	for _, obs in ipairs(ordered) do
		local hits = rules.evaluate(obs, ctx)
		if #hits > 0 then
			local primary = hits[1]
			local all_weak, sev, conf = true, nil, nil
			local seen_cat, secondary = { [primary.category] = true }, {}
			for _, h in ipairs(hits) do
				if rules.CATEGORY_INDEX[h.category] < rules.CATEGORY_INDEX[primary.category] then primary = h end
				if not h.weak then all_weak = false end
				sev = util.max_by_order(util.SEVERITY_ORDER, sev, h.severity)
				conf = util.max_by_order(util.CONFIDENCE_ORDER, conf, h.confidence)
			end
			for _, h in ipairs(hits) do
				if h.category ~= primary.category and not seen_cat[h.category] then
					seen_cat[h.category] = true
					secondary[#secondary + 1] = h.category
				end
			end
			table.sort(secondary, function(a, b) return rules.CATEGORY_INDEX[a] < rules.CATEGORY_INDEX[b] end)
			if all_weak then
				-- name / location / existence only: never above low severity and low confidence
				sev = util.min_by_order(util.SEVERITY_ORDER, sev, WEAK_SEVERITY_CAP)
				conf = "low"
			end
			local evidence, rationale, seen_r = {}, {}, {}
			for _, h in ipairs(hits) do
				evidence[#evidence + 1] = { kind = h.kind, rule_id = h.rule_id, detail = h.evidence }
				if not seen_r[h.rationale] then seen_r[h.rationale] = true; rationale[#rationale + 1] = h.rationale end
			end
			findings[#findings + 1] = {
				object_name = obs.name,
				object_class = obs.class_name,
				object_path = obs.path,
				observation_ids = { obs.obs_id },
				category = primary.category,
				secondary_categories = secondary,
				evidence = evidence,
				rationale = table.concat(rationale, " "),
				severity = sev,
				confidence = conf,
				unknowns = union_unknowns(hits),
				suggested_tests = union_tests(hits),
				verdict = "CANDIDATE",
				test_run_ids = {},
			}
			findings[#findings].classification = classify.classify(obs)
			findings[#findings].risk = risk.score(findings[#findings])
		end
	end
	table.sort(findings, function(a, b)
		if a.object_path ~= b.object_path then return a.object_path < b.object_path end
		return a.category < b.category
	end)
	for i, f in ipairs(findings) do f.finding_id = string.format("SS-%04d", i) end
	return findings
end

function A.summarize(findings)
	local by_cat, by_sev = {}, { informational = 0, low = 0, medium = 0, high = 0 }
	for _, c in ipairs(rules.CATEGORIES) do by_cat[c] = 0 end
	for _, f in ipairs(findings) do
		by_cat[f.category] += 1
		by_sev[f.severity] += 1
	end
	return { total = #findings, by_category = by_cat, by_severity = by_sev }
end

return A
end
__factories["scanner.classify"] = function(require)
-- Smart remote classification: buckets remotes into coarse FUNCTIONAL FAMILIES from name / parent-name tokens.
-- A family is a REVIEW AID, not a fact: the client cannot see what a remote actually does. Every classification
-- carries its basis (which token matched where) and a confidence that is "low" unless two independent sources agree.
-- Pure function; deterministic; no network, no remotes.
local util = require("client.util.util")

local C = {}

-- family -> (exact tokens, prefixes). Ordered: the FIRST family that matches wins (more specific first).
-- 0.4.0 set per the spec: Economy, Currency, Shop, Inventory, Rewards, Progression, Combat, Movement,
-- Teleportation, Admin, Permission, Trading, Social (+ Unknown). Every match records its basis.
C.FAMILIES = {
	{ key = "admin", label = "Admin", words = util.set({ "admin", "admins", "mod", "mods", "moderator", "ban", "bans", "kick", "staff", "owner", "sudo", "command", "commands", "cmd", "debug", "godmode" }), prefixes = { "administr", "moderat" } },
	{ key = "permission", label = "Permission", words = util.set({ "permission", "permissions", "whitelist", "blacklist", "rank", "privilege", "access", "auth", "authorize" }), prefixes = { "authoriz", "permiss" } },
	{ key = "teleportation", label = "Teleportation", words = util.set({ "teleport", "tp", "warp", "waypoint" }), prefixes = { "telepor" } },
	{ key = "movement", label = "Movement", words = util.set({ "walk", "walkspeed", "run", "sprint", "jump", "dash", "move", "movement", "speed", "spawn", "respawn", "mount", "ride", "crawl", "swim" }), prefixes = {} },
	{ key = "trading", label = "Trading", words = util.set({ "trade", "trades", "trading", "offer", "offers", "exchange", "swap", "gift" }), prefixes = {} },
	{ key = "shop", label = "Shop", words = util.set({ "shop", "store", "buy", "sell", "purchase", "price", "cart", "checkout", "market", "vendor", "order" }), prefixes = { "purchas" } },
	{ key = "economy", label = "Economy", words = util.set({ "money", "cash", "wallet", "bank", "balance", "deposit", "withdraw", "robux", "pay", "payment", "refund", "income", "salary", "tax" }), prefixes = { "currenc" } },
	{ key = "currency", label = "Currency", words = util.set({ "coin", "coins", "gold", "gems", "gem", "diamond", "diamonds", "credits", "credit", "points", "token", "tokens", "give", "grant", "coins" }), prefixes = {} },
	{ key = "inventory", label = "Inventory", words = util.set({ "inventory", "equip", "unequip", "item", "items", "drop", "pickup", "loot", "pet", "pets", "tool", "tools", "craft", "backpack", "slot", "stash", "storage" }), prefixes = { "inventor", "equipment" } },
	{ key = "rewards", label = "Rewards", words = util.set({ "reward", "rewards", "claim", "daily", "bonus", "freebie", "redeem", "prize", "wheel" }), prefixes = {} },
	{ key = "progression", label = "Progression", words = util.set({ "level", "levels", "xp", "exp", "experience", "quest", "quests", "rebirth", "unlock", "achievement", "prestige", "mission", "checkpoint", "stage", "progress", "save", "load", "data", "settings", "config" }), prefixes = { "achievem", "progress" } },
	{ key = "combat", label = "Combat", words = util.set({ "damage", "hit", "attack", "shoot", "weapon", "heal", "kill", "health", "explode", "projectile", "ability", "cast", "stun", "revive", "swing", "respawnplayer" }), prefixes = { "damag", "weapon" } },
	{ key = "social", label = "Social", words = util.set({ "chat", "message", "messages", "whisper", "friend", "friends", "party", "team", "emote", "emoji", "bubble", "mention", "join", "leave", "serverhop" }), prefixes = {} },
}

C.UNKNOWN = { key = "unknown", label = "Unclassified" }

-- classify(obs) -> { family, label, confidence, basis } | nil (only remotes classify)
function C.classify(obs)
	if not ({ RemoteEvent = true, RemoteFunction = true, UnreliableRemoteEvent = true })[obs.class_name] then return nil end
	local hits = {}
	-- source 1: the remote's own name (a default class name carries no information)
	if obs.name ~= obs.class_name then
		local fam = C.match(obs.name)
		if fam then hits[#hits + 1] = { source = "name", token = fam.token, family = fam.family } end
	end
	-- source 2: the parent container's name (nested containers only - a root service name like
	-- "ReplicatedStorage" carries no developer intent and must not classify anything)
	local parent_name = obs.parent_path and util.last_segment(obs.parent_path) or nil
	if parent_name and parent_name ~= obs.name and (obs.parent_path:find(".", 1, true)) then
		local fam = C.match(parent_name)
		if fam then hits[#hits + 1] = { source = "parent", token = fam.token, family = fam.family } end
	end
	if #hits == 0 then return nil end
	local primary = hits[1].family
	local agree = false
	for _, h in ipairs(hits) do
		if h.family == primary and h ~= hits[1] then agree = true end
	end
	return {
		family = primary,
		label = C.label(primary),
		confidence = agree and "medium" or "low", -- never "high": the client cannot observe behaviour
		basis = hits,
	}
end

function C.match(text)
	local toks = util.tokenize(tostring(text))
	for _, fam in ipairs(C.FAMILIES) do
		local tok = util.match_tokens(toks, fam.words, fam.prefixes)
		if tok then return { family = fam.key, token = tok } end
	end
	return nil
end

function C.label(key)
	for _, fam in ipairs(C.FAMILIES) do
		if fam.key == key then return fam.label end
	end
	return C.UNKNOWN.label
end

-- families of the given findings (in analysis order), for the Explorer's summary
function C.tally(findings)
	local order, counts = {}, {}
	for _, f in ipairs(findings) do
		local fam = f.classification and f.classification.family or C.UNKNOWN.key
		if not counts[fam] then counts[fam] = { family = fam, label = f.classification and f.classification.label or C.UNKNOWN.label, count = 0, top_risk = 0 } end
		counts[fam].count += 1
		local score = f.risk and f.risk.score or 0
		if score > counts[fam].top_risk then counts[fam].top_risk = score end
	end
	for _, c in pairs(counts) do order[#order + 1] = c end
	table.sort(order, function(a, b)
		if a.count ~= b.count then return a.count > b.count end
		return a.family < b.family
	end)
	return order
end

return C
end
__factories["scanner.graph"] = function(require)
-- Remote relationship graph, derived ONLY from replicated structure (factual relations, no guessing):
--   child_of    : a remote lives inside a container (parent_path)
--   sibling_of  : two remotes share the same parent_path
--   co_named    : the same remote name appears at several paths
-- The graph is a bounded, data-level adjacency structure (never rendered eagerly in the GUI; pages page through it).
local util = require("client.util.util")

local G = {}

G.MAX_NODES = 400
G.MAX_EDGES = 1200
G.MAX_SIBLING_FAN = 24 -- per parent: cap sibling edges so one huge folder cannot dominate the graph

-- build(observations) -> { nodes, edges, stats }
function G.build(observations)
	local remotes, containers, names = {}, {}, {}
	for _, o in ipairs(observations) do
		local is_remote = o.class_name == "RemoteEvent" or o.class_name == "RemoteFunction" or o.class_name == "UnreliableRemoteEvent"
		if is_remote then
			remotes[#remotes + 1] = o
			local pp = o.parent_path or "?"
			if not containers[pp] then containers[pp] = { path = pp, name = util.last_segment(pp), remotes = {} } end
			local c = containers[pp]
			c.remotes[#c.remotes + 1] = o
			local nk = o.class_name .. "|" .. o.name
			names[nk] = (names[nk] or 0) + 1
		end
	end

	local nodes, edges = {}, {}
	local by_id = {}
	local truncated = false

	local function node(id, kind, class, name, path)
		if by_id[id] then return by_id[id] end
		if #nodes >= G.MAX_NODES then truncated = true return nil end
		local n = { id = id, kind = kind, class = class, name = name, path = path }
		by_id[id] = n
		nodes[#nodes + 1] = n
		return n
	end

	local function edge(kind, from, to, evidence)
		if #edges >= G.MAX_EDGES then truncated = true return end
		edges[#edges + 1] = { kind = kind, from = from, to = to, evidence = evidence }
	end

	local container_ids = {}
	for _, pp in ipairs(util.sorted_keys(containers)) do
		local c = containers[pp]
		if #c.remotes > 0 then
			local cid = "C:" .. pp
			local cn = node(cid, "container", "Container", c.name, pp)
			if cn then
				container_ids[pp] = cid
			else
				break -- node budget exhausted
			end
		end
	end

	for _, o in ipairs(remotes) do
		local rid = "R:" .. o.path
		local rn = node(rid, "remote", o.class_name, o.name, o.path)
		if not rn then break end
		local cid = container_ids[o.parent_path or "?"]
		if cid then edge("child_of", rid, cid, "replicated structure") end
	end

	-- sibling_of: remotes sharing a container (bounded per container, deterministic order)
	for _, pp in ipairs(util.sorted_keys(containers)) do
		local c = containers[pp]
		local ids = {}
		for _, o in ipairs(c.remotes) do
			if by_id["R:" .. o.path] then ids[#ids + 1] = "R:" .. o.path end
		end
		table.sort(ids)
		for i = 1, math.min(#ids - 1, G.MAX_SIBLING_FAN) do
