			end
			if #edges >= G.MAX_EDGES then break end
		end
	end

	-- co_named: same class+name at several paths (factual duplicate), one edge per extra occurrence
	for _, nk in ipairs(util.sorted_keys(names)) do
		if names[nk] > 1 then
			local cls, nm = nk:match("^([^|]+)|(.*)$")
			local group = {}
			for _, o in ipairs(remotes) do
				if o.class_name == cls and o.name == nm and by_id["R:" .. o.path] then group[#group + 1] = "R:" .. o.path end
