-- containers sorted by remote count (desc), for the Explorer's bounded summary
function G.container_summary(graph, cap)
	local out = {}
	local seen = {}
	for _, e in ipairs(graph.edges) do
		if e.kind == "child_of" then
			seen[e.to] = (seen[e.to] or 0) + 1
		end
	end
	for _, n in ipairs(graph.nodes) do
		if n.kind == "container" then
			out[#out + 1] = { path = n.path, name = n.name, remotes = seen[n.id] or 0 }
		end
	end
	table.sort(out, function(a, b)
		if a.remotes ~= b.remotes then return a.remotes > b.remotes end
		return a.path < b.path
	end)
	if cap and #out > cap then
		local trimmed = {}
		for i = 1, cap do trimmed[i] = out[i] end
		return trimmed, #out
	end
	return out, #out
end

-- Compact report listing: top containers by remote count with (capped) member remote paths.
function G.listing(graph, cap_containers, cap_remotes)
	local path_of = {}
	for _, n in ipairs(graph.nodes) do path_of[n.id] = n.path end
	local per, counts = {}, {}
	for _, e in ipairs(graph.edges) do
		if e.kind == "child_of" then
			counts[e.to] = (counts[e.to] or 0) + 1
			per[e.to] = per[e.to] or {}
			if #per[e.to] < cap_remotes then per[e.to][#per[e.to] + 1] = path_of[e.from] or e.from end
		end
	end
	local out = {}
	for _, n in ipairs(graph.nodes) do
		if n.kind == "container" then
			local remotes = per[n.id] or {}
			table.sort(remotes)
			out[#out + 1] = { path = n.path, name = n.name, remote_count = counts[n.id] or 0, remotes = remotes }
		end
	end
	table.sort(out, function(a, b)
		if a.remote_count ~= b.remote_count then return a.remote_count > b.remote_count end
		return a.path < b.path
	end)
	local total = #out
	while #out > cap_containers do table.remove(out) end
	return out, total
end

return G
end
