-- PASSIVE reconnaissance. Reads only what a normal client can already see (replicated instances).
--
-- This module NEVER: fires/invokes remotes, reads Script.Source, decompiles, hooks or intercepts anything,
-- touches the network, or records player data. It records metadata + a verdict of OBSERVED, nothing more.
local util = require("client.util.util")
local secrets = require("client.util.secrets")
local rules = require("scanner.rules")

local I = {}

-- Properties read (each through pcall) per class of interest.
I.CLASS_PROPS = {
	RemoteEvent = {},
	RemoteFunction = {},
	UnreliableRemoteEvent = {},
	ProximityPrompt = { "ActionText", "MaxActivationDistance", "HoldDuration", "RequiresLineOfSight", "Enabled" },
	ClickDetector = { "MaxActivationDistance" },
	DragDetector = { "MaxActivationDistance" },
}

-- Instances whose attributes are inspected for sensitive attribute NAMES.
local ATTRIBUTE_HOSTS = util.set({ "Folder", "Configuration", "Model", "RemoteEvent", "RemoteFunction", "UnreliableRemoteEvent",
	"ProximityPrompt", "ClickDetector", "DragDetector" })

I.DEFAULTS = {
	max_objects = 100000,
	progress_every = 2000,
	batch_budget_ms = 3,  -- engineering objective: ~2-3ms of uninterrupted work per batch, then yield (see docs/PERFORMANCE.md)
	batch_min = 16,       -- adaptive batch size lower bound (small batches keep latency bounded on slow machines)
	batch_max = 512,      -- adaptive batch size upper bound (amortise bookkeeping on fast machines)
	max_depth = 64,
}

local function safe_get(inst, prop)
	local ok, v = pcall(function() return inst[prop] end)
	return ok, v
end

local function norm_value(v)
	local t = type(v)
	if t == "number" then
		if v ~= v then return "nan" end
		if v == math.huge or v == -math.huge then return "unbounded" end
		return v
	elseif t == "string" then
		local r = secrets.redact(util.clean_text(v, 64))
		return r
	elseif t == "boolean" then
		return v
	end
	return tostring(v)
end

local function value_summary(v)
	local t = type(v)
	local s = { value_type = t }
	if t == "string" then
		s.value_length = #v
		s.looks_like_secret = secrets.value_looks_secret(v)
	end
	return s
end

-- scan(env, config, progress) -> { observations, stats }
-- env = { roots = { {name=, inst=}, ... }, players = PlayersService|nil, now_iso = fn, yield = fn|nil, clock = fn|nil }
-- Incremental + adaptive: objects are processed in small batches bounded by a wall-clock budget
-- (config.batch_budget_ms, default ~3ms) so the frame is never blocked for long; between batches the
-- scanner yields once. The batch size adapts to the measured processing speed within [batch_min, batch_max].
function I.scan(env, config, progress)
	config = config or {}
	local max_objects = config.max_objects or I.DEFAULTS.max_objects
	local progress_every = config.progress_every or I.DEFAULTS.progress_every
	local budget_s = (config.batch_budget_ms or I.DEFAULTS.batch_budget_ms) / 1000
	local batch_min = config.batch_min or I.DEFAULTS.batch_min
	local batch_max = config.batch_max or I.DEFAULTS.batch_max
