		for ci = from, stop, -1 do
			local child = children[ci]
			local okn, cname = safe_get(child, "Name")
			local seg = okn and type(cname) == "string" and util.clean_text(cname, 100) or "?"
			stack[#stack + 1] = { inst = child, path = item.path .. "." .. seg, depth = item.depth + 1 }
		end
		item.pending_children = nil
		if stop > 1 then
			item.pending_children = children
			item.push_index = stop - 1
			stack[#stack + 1] = item -- resume at the top before any other branch
		end
	end

	-- incremental, adaptive main loop: bounded batches + one yield between batches
	local batch_size = batch_min
	while #stack > 0 do
		local batch_start = clock()
		local n = 0
		local budget_exceeded = false
		while #stack > 0 and n < batch_size do
			-- 0.4.1: check elapsed time INSIDE the batch (every 16 items) BEFORE popping, so the batch stops
			-- at a safe boundary and NO item is ever lost: pending work simply stays on the stack.
			if n % 16 == 0 and clock() - batch_start > budget_s then
				budget_exceeded = true
				break
			end
			local item = table.remove(stack)
			n += 1
			if item.pending_children then
				-- 0.4.1: child-enumeration slice resume - counts as work, not as a visit
				push_child_slice(item, item.pending_children, item.push_index)
			else
				result.stats.visited += 1
				if should_cancel and result.stats.visited % 64 == 0 and should_cancel() then
					result.stats.cancelled = true
					break
				end
				if result.stats.visited > max_objects then
					result.stats.truncated = true
					break
				end
				if progress and result.stats.visited % progress_every == 0 then progress(result.stats.visited) end
				process_one(item)
			end
		end
		local batch_ms = (clock() - batch_start) * 1000
		result.stats.batches += 1
		result.stats.batch_ms_total += batch_ms
		result.stats.batch_ms[#result.stats.batch_ms + 1] = math.floor(batch_ms * 1000) / 1000
		if batch_ms > result.stats.max_batch_ms then result.stats.max_batch_ms = batch_ms end
		result.stats.batch_size_last = batch_size
		if batch_ms > 0 and not budget_exceeded then
			-- adapt towards the budget; the midpoint smooths out single slow batches (GC, first-touch pages).
			-- A budget-cut batch does not grow the size (its measurement is truncated, not representative).
			local target = math.floor(batch_size * ((budget_s * 1000) / batch_ms) + 0.5)
