		end
		if result.stats.cancelled or result.stats.truncated then break end
		if #stack > 0 and env.yield then env.yield() end
	end
	return result
end

return I
end
__factories["scanner.live"] = function(require)
-- Passive LIVE observation: records replicated objects that APPEAR while the session is open.
-- Event-driven and bounded: the handler only reads class/name/parent (cheap, non-yielding) and appends to a capped
-- buffer; the caller drains on its own schedule (GUI tick / explicit call). It NEVER fires or invokes anything,
-- never reads script source, and skips player-owned characters. When the executor does not expose
-- DescendantAdded, start() returns false and nothing pretends to watch.
local util = require("client.util.util")
local rules = require("scanner.rules")

local L = {}

L.DEFAULTS = {
	max_events = 500,      -- buffered events before overflow counting kicks in
	max_depth = 32,        -- max path depth walked per event
	max_tracked = 5000,    -- dedupe set size; cleared when exceeded (memory bound)
}

function L.new(env, opts)
	opts = opts or {}
	local max_events = opts.max_events or L.DEFAULTS.max_events
	local max_depth = opts.max_depth or L.DEFAULTS.max_depth
	local max_tracked = opts.max_tracked or L.DEFAULTS.max_tracked

	local self = {
		buffer = {}, stats = { received = 0, recorded = 0, duplicates = 0, overflow = 0, skipped_player = 0, skipped_uninteresting = 0 },
		running = false, supported = nil,
	}
	local seen, count = {}, 0
	local conn

	local function is_player_character(inst)
		if not env.players then return false end
		local ok, p = pcall(function() return env.players:GetPlayerFromCharacter(inst) end)
		return ok and p ~= nil
	end

	local function interesting(class_name, inst)
		if rules.REMOTE_CLASSES[class_name] or rules.INTERACT_CLASSES[class_name] then return true end
		if rules.VALUE_CLASSES[class_name] then
			local okn, n = pcall(function() return inst.Name end)
			return okn and type(n) == "string" and rules.is_sensitive_name(n) ~= nil
		end
		return false
	end

	local function path_of(inst)
		local segs, cur, depth = {}, inst, 0
		while cur and depth < max_depth do
			depth += 1
			local okn, n = pcall(function() return cur.Name end)
			if not okn or type(n) ~= "string" then break end
			segs[#segs + 1] = util.clean_text(n, 100)
			local okp, p = pcall(function() return cur.Parent end)
			cur = okp and p or nil
		end
		for i = 1, math.floor(#segs / 2) do
			local t = segs[i]; segs[i] = segs[#segs + 1 - i]; segs[#segs + 1 - i] = t
		end
		return table.concat(segs, ".")
	end

	local function on_added(inst)
		if not self.running then return end
		self.stats.received += 1
		if count > max_tracked then seen, count = {}, 0 end -- bounded memory
		local okc, class_name = pcall(function() return inst.ClassName end)
		if not okc or type(class_name) ~= "string" then return end
		if not interesting(class_name, inst) then
			self.stats.skipped_uninteresting += 1
			return
		end
		if is_player_character(inst) then
			self.stats.skipped_player += 1
			return
		end
		local okn, name = pcall(function() return inst.Name end)
		if not okn or type(name) ~= "string" then return end
		local path = path_of(inst)
		local key = class_name .. "|" .. path
		if seen[key] then
			self.stats.duplicates += 1
			return
		end
		seen[key] = true
		count += 1
		if #self.buffer >= max_events then
			self.stats.overflow += 1
			return
		end
		self.stats.recorded += 1
		self.buffer[#self.buffer + 1] = {
			class_name = class_name, name = util.clean_text(name, 100), path = path,
			parent_path = util.parent_path(path), live = true,
		}
	end

	function self.start()
		if self.running then return true end
		local g = env.game
		if not g then self.supported = false return false end
		local ok, c = pcall(function() return g.DescendantAdded:Connect(on_added) end)
		if not ok or not c then self.supported = false return false end
		conn = c
		self.running = true
		self.supported = true
		return true
	end

	function self.stop()
		if conn then pcall(function() conn:Disconnect() end) end
		conn = nil
		self.running = false
	end

	function self.drain()
		local out = self.buffer
		self.buffer = {}
		return out
	end

	return self
end

-- fold drained live observations into a scan result (dedup against what the walk already recorded)
function L.merge(scan_result, events, now_iso, obs_counter)
	local added = {}
	local existing = {}
	for _, o in ipairs(scan_result.observations) do existing[o.class_name .. "|" .. o.path] = true end
	for _, e in ipairs(events) do
		if not existing[e.class_name .. "|" .. e.path] then
			existing[e.class_name .. "|" .. e.path] = true
			local rec = {
				class_name = e.class_name, name = e.name, path = e.path, parent_path = e.parent_path,
				depth = 0, access = "readable", metadata = {}, live = true,
				obs_id = string.format("OBS-%04d", obs_counter.n), observed_at = now_iso(), verdict = "OBSERVED",
			}
			obs_counter.n += 1
			scan_result.observations[#scan_result.observations + 1] = rec
			scan_result.stats.by_class[e.class_name] = (scan_result.stats.by_class[e.class_name] or 0) + 1
			added[#added + 1] = rec
		end
	end
	scan_result.stats.live_recorded = (scan_result.stats.live_recorded or 0) + #added
	return added
end

return L
end
__factories["scanner.risk"] = function(require)
-- Evidence-based risk scoring: a transparent 0-100 score with a per-factor breakdown. Every factor cites the
-- evidence that earned its points; a factor without evidence contributes nothing. Weak-only evidence is capped
