R.BANDS = { low = 1, medium = 2, high = 3 }

local FACTORS = {
	-- weak = true: name/structure/location-derived; a finding backed ONLY by weak factors stays in the low band.
	-- Every remote finding trivially matches F-REMOTE-SURFACE, so it must not count as strong evidence.
