		condition = function(f) return f.object_class == "RemoteEvent" or f.object_class == "RemoteFunction" or f.object_class == "UnreliableRemoteEvent" end,
		basis = function(f) return f.object_class .. " is callable from the client" end },
	{ id = "F-STATE-HINT", label = "State-changing purpose hint", points = 15, max = 15, weak = true,
		condition = function(f) return f.category == "Economy and currency" or f.category == "Inventory and item ownership"
			or f.category == "Progression and rewards" or f.category == "Combat and player state" or f.category == "Access control and authorization" end,
		basis = function(f) return "category '" .. f.category .. "' is name/structure-derived" end },
	{ id = "F-UNUSUAL-PROPERTY", label = "Unusual observed property", points = 15, max = 15,
		condition = function(f)
			for _, e in ipairs(f.evidence) do
				-- secret-shaped values are scored by F-SECRET-SHAPED; no double counting
