R.WEAK_ONLY_SCORE_CAP = 25

function R.score(finding)
	local pts, factors = 0, {}
	local strong = false
	for _, fac in ipairs(FACTORS) do
		local ok = false
		if fac.condition then ok = fac.condition(finding) end
		if ok then
			pts += fac.points
			if not fac.weak then strong = true end
