	--   priority            = the 0-100 candidate-priority score (identical to `score`; kept for readability)
	--   evidence_confidence = how strong the OBSERVED evidence is (low/medium/high) - pre-test only
	--   verification_status = what testing has established (unverified/inconclusive/tested_rejected/tested_accepted/confirmed)
	local level = 1
	for _, e in ipairs(finding.evidence or {}) do
