		CANDIDATE = "unverified", NOT_TESTED = "unverified", INCONCLUSIVE = "inconclusive",
		TESTED_REJECTED = "tested_rejected", TESTED_ACCEPTED = "tested_accepted", CONFIRMED = "confirmed",
	}
