		score = pts, band = band, factors = factors,
		capped = (not strong) and pts >= R.WEAK_ONLY_SCORE_CAP or false,
		priority = pts, priority_band = band,
		evidence_confidence = evidence_confidence,
		verification_status = VERDICT_TO_VERIFICATION[finding.verdict] or "unverified",
	}
