__factories["scanner.verdict"] = function(require)
-- Verdict logic. The ONLY place that may produce TESTED_* / CONFIRMED.
-- reporting/verdict_rules.py is a line-by-line Python mirror; tests/fixtures/verdict_cases.json is run against both.
local V = {}

V.VERDICTS = { "OBSERVED", "CANDIDATE", "NOT_TESTED", "TESTED_REJECTED", "TESTED_ACCEPTED", "CONFIRMED", "INCONCLUSIVE" }
V.VERIFIABLE_CHANNELS = { response_value = true, observable_state = true, qa_telemetry = true }

-- spec fields:
--   ran (bool), error (string|nil), aborted (bool), expected ("accepted"|"rejected"),
--   channel ("response_value"|"observable_state"|"qa_telemetry"|"none"), confirmable (bool),
--   test_type, call_outcomes = { "accepted"|"rejected"|"unknown", ... }
-- returns { verdict, observed_outcome, confidence, reason, expectation_mismatch }
function V.resolve(spec)
	local function out(verdict, observed, conf, reason, mismatch)
		return { verdict = verdict, observed_outcome = observed, confidence = conf, reason = reason, expectation_mismatch = mismatch == true }
	end
	if not spec.ran then
		return out("NOT_TESTED", "none", "low", "no test case was executed")
	end
	local outcomes = spec.call_outcomes or {}
	if (spec.error or spec.aborted) and #outcomes == 0 then
		return out("INCONCLUSIVE", "unknown", "low", "test stopped before any outcome was observed: " .. tostring(spec.error or "aborted"))
	end
	if not V.VERIFIABLE_CHANNELS[spec.channel] then
		-- e.g. RemoteEvent without a response: absence of an error proves neither success nor failure
		return out("INCONCLUSIVE", "unknown", "low", "no observable evidence channel; absence of an error is not evidence")
	end
	if #outcomes == 0 then
		return out("INCONCLUSIVE", "unknown", "low", "no outcome recorded")
	end
	for _, o in ipairs(outcomes) do
		if o ~= "accepted" and o ~= "rejected" then
			return out("INCONCLUSIVE", "unknown", "low", "at least one call produced an outcome that could not be classified")
		end
	end

	local observed
	if spec.test_type == "rate_limit_probe" then
		observed = "accepted"
		for _, o in ipairs(outcomes) do
			if o == "rejected" then observed = "rejected" end
		end
	else
		observed = outcomes[1]
		for _, o in ipairs(outcomes) do
			if o ~= observed then
				return out("INCONCLUSIVE", "unknown", "low", "calls of a single-call test disagreed with each other")
			end
		end
	end

	local expected = spec.expected
	if expected ~= "accepted" and expected ~= "rejected" then
		return out("INCONCLUSIVE", observed, "low", "test case has no valid expected outcome")
	end

	if expected == "rejected" and observed == "rejected" then
		return out("TESTED_REJECTED", observed, "medium", "request rejected as expected")
	end
	if expected == "accepted" and observed == "accepted" then
		return out("TESTED_ACCEPTED", observed, "medium", "request accepted as expected (positive control)")
	end
	if expected == "accepted" and observed == "rejected" then
		-- a positive control failed: the test setup (or the feature) is broken, so we must not conclude anything
		return out("INCONCLUSIVE", observed, "low", "expected acceptance but the request was rejected; check the test setup", true)
	end
	-- expected rejection, observed acceptance
	if spec.confirmable == true and spec.test_type ~= "rate_limit_probe" then
		return out("CONFIRMED", observed, "high",
			"request accepted although the manifest expected rejection, backed by a verifiable evidence channel", true)
	end
	local why = spec.test_type == "rate_limit_probe"
		and "bounded probe saw no rejection; this cannot prove the absence of a rate limit"
		or "request accepted although rejection was expected; acceptance alone is not a confirmed vulnerability"
	return out("TESTED_ACCEPTED", observed, "medium", why, true)
end

-- aggregate verdicts of all test runs attached to one finding
function V.aggregate(verdicts)
	if #verdicts == 0 then return "CANDIDATE" end
	local seen = {}
	for _, v in ipairs(verdicts) do seen[v] = (seen[v] or 0) + 1 end
	if seen.CONFIRMED then return "CONFIRMED" end
	if seen.TESTED_ACCEPTED then return "TESTED_ACCEPTED" end
	if seen.INCONCLUSIVE then return "INCONCLUSIVE" end
	if (seen.TESTED_REJECTED or 0) == #verdicts then return "TESTED_REJECTED" end
	return "CANDIDATE"
end

return V
end
