-- Test-manifest validator (Luau side). test_manifest/validate.py + manifest.schema.json are the Python side;
-- tests/fixtures/manifests/*.json is run through BOTH and the accept/reject decisions must agree.
--
-- Unknown keys are rejected everywhere: a manifest cannot smuggle in "payload generators", "fuzz", "loop" etc.
local json = require("client.util.json")
local util = require("client.util.util")

local V = {}

V.HARD = {
	MAX_CALLS_PER_TEST = 25,
	MAX_TOTAL_CALLS = 100,
	MIN_INTERVAL_SECONDS = 0.2,
	MAX_DURATION_SECONDS = 1800,
	MAX_TEST_CASES = 50,
	MAX_PLACE_IDS = 20,
	MAX_STRING_LEN = 4096,
	MAX_ARGS = 10,
	MAX_ARGS_JSON_BYTES = 16384,
	MAX_NESTING = 6,
}

V.ENDPOINT_CLASSES = util.set({ "RemoteEvent", "RemoteFunction", "UnreliableRemoteEvent" })
V.TEST_TYPES = util.set({ "read_only_call", "valid_call_baseline", "negative_input", "rate_limit_probe" })
V.MODES = util.set({ "production_observation", "private_qa" })
V.CHANNELS = util.set({ "response_value", "observable_state", "qa_telemetry", "none" })
V.ENDPOINT_ROOTS = util.set({ "ReplicatedStorage", "Workspace", "ReplicatedFirst" })
V.PROBE_ROOTS = util.set({ "ReplicatedStorage", "Workspace", "ReplicatedFirst", "Players" })
V.RESET_KINDS = util.set({ "manual", "server_side_auto" })

local function is_int(v) return type(v) == "number" and v == math.floor(v) and v > 0 and v < 9007199254740992 end

-- A "path" is dot separated segments; the first must be an allowed service root. '@LocalPlayer' is allowed under Players.
local function check_path(p, roots, allow_player)
	if type(p) ~= "string" or #p == 0 or #p > 400 then return false, "must be a non-empty string up to 400 chars" end
	local segs = {}
	for seg in string.gmatch(p .. ".", "([^%.]*)%.") do segs[#segs + 1] = seg end
	if #segs < 2 then return false, "must contain a service and at least one child (e.g. ReplicatedStorage.Remotes.Name)" end
	if not roots[segs[1]] then return false, "root '" .. segs[1] .. "' is not an allowed root" end
	for i, seg in ipairs(segs) do
		if seg == "" then return false, "empty path segment" end
		if #seg > 100 or string.find(seg, "[%c]") then return false, "invalid path segment" end
		if string.sub(seg, 1, 1) == "@" and not (allow_player and seg == "@LocalPlayer" and i == 2 and segs[1] == "Players") then
			return false, "'@' segments are only allowed as Players.@LocalPlayer in state probes"
		end
	end
	return true
end

local function is_object(t)
	if type(t) ~= "table" then return false end
	local mt = getmetatable(t)
	if mt and mt.__jsontype then return mt.__jsontype == "object" end
	return #t == 0
end

-- safe field access: wrong-typed input (e.g. "evidence": true) must produce an error, never a crash
local function get(t, k)
	if type(t) == "table" then return t[k] end
	return nil
end

local function check_keys(obj, allowed, required, where, errs)
	if not is_object(obj) then
		errs[#errs + 1] = where .. ": must be an object"
		return false
	end
	for k in pairs(obj) do
		if not allowed[k] then errs[#errs + 1] = where .. ": unknown key '" .. tostring(k) .. "'" end
	end
	for _, k in ipairs(required) do
		if obj[k] == nil then errs[#errs + 1] = where .. ": missing required key '" .. k .. "'" end
	end
	return true
end

local function nesting_ok(v, depth)
	if depth > V.HARD.MAX_NESTING then return false end
	if type(v) == "table" and v ~= json.null then
		for _, x in pairs(v) do
			if not nesting_ok(x, depth + 1) then return false end
		end
	end
	return true
end

local function check_arg_value(v, where, errs, budget)
	local t = type(v)
	if t == "string" then
		if #v > V.HARD.MAX_STRING_LEN then errs[#errs + 1] = where .. ": string longer than " .. V.HARD.MAX_STRING_LEN end
	elseif t == "number" then
		if v ~= v or v == math.huge or v == -math.huge then errs[#errs + 1] = where .. ": non-finite number" end
	elseif t == "boolean" then
	elseif t == "table" then
		if v ~= json.null then
			for k, x in pairs(v) do
				if type(k) ~= "number" and type(k) ~= "string" then errs[#errs + 1] = where .. ": invalid key" end
				check_arg_value(x, where, errs, budget)
			end
		end
	else
		errs[#errs + 1] = where .. ": unsupported value type " .. t
	end
end

local function check_matcher(m, where, errs)
	if not check_keys(m, util.set({ "field", "equals", "exists", "type_is" }), {}, where, errs) then return end
	local n = 0
	for _, k in ipairs({ "equals", "exists", "type_is" }) do
		if m[k] ~= nil then n += 1 end
	end
	if n ~= 1 then errs[#errs + 1] = where .. ": exactly one of equals / exists / type_is is required" end
	if m.field ~= nil and (type(m.field) ~= "string" or #m.field > 200) then errs[#errs + 1] = where .. ".field: must be a string" end
	if m.exists ~= nil and type(m.exists) ~= "boolean" then errs[#errs + 1] = where .. ".exists: must be boolean" end
	if m.type_is ~= nil and not util.set({ "string", "number", "boolean", "table", "nil" })[m.type_is] then
		errs[#errs + 1] = where .. ".type_is: must be string|number|boolean|table|nil"
	end
end

local function check_evidence(ev, tc, where, errs)
	local allowed = util.set({ "channel", "accepted_when", "rejected_when", "probe", "telemetry" })
	if not check_keys(ev, allowed, { "channel" }, where, errs) then return end
	if not V.CHANNELS[ev.channel] then errs[#errs + 1] = where .. ".channel: must be one of response_value|observable_state|qa_telemetry|none"; return end
	local cls = get(tc.endpoint, "class")
	if ev.channel == "none" then
		for _, k in ipairs({ "accepted_when", "rejected_when", "probe", "telemetry" }) do
			if ev[k] ~= nil then errs[#errs + 1] = where .. ": '" .. k .. "' is not allowed with channel 'none'" end
		end
	elseif ev.channel == "response_value" then
		if cls ~= "RemoteFunction" then errs[#errs + 1] = where .. ": response_value needs a RemoteFunction endpoint (RemoteEvents return nothing)" end
		if ev.accepted_when == nil or ev.rejected_when == nil then errs[#errs + 1] = where .. ": accepted_when and rejected_when are required" end
		if ev.accepted_when then check_matcher(ev.accepted_when, where .. ".accepted_when", errs) end
		if ev.rejected_when then check_matcher(ev.rejected_when, where .. ".rejected_when", errs) end
		if ev.probe ~= nil or ev.telemetry ~= nil then errs[#errs + 1] = where .. ": probe/telemetry not allowed with response_value" end
	elseif ev.channel == "observable_state" then
		if not check_keys(ev.probe, util.set({ "target_path", "kind", "name", "settle_seconds" }), { "target_path", "kind", "name" }, where .. ".probe", errs) then return end
		local p = ev.probe or {}
		local okp, why = check_path(p.target_path, V.PROBE_ROOTS, true)
		if not okp then errs[#errs + 1] = where .. ".probe.target_path: " .. why end
		if p.kind ~= "property" and p.kind ~= "attribute" then errs[#errs + 1] = where .. ".probe.kind: must be property|attribute" end
		if type(p.name) ~= "string" or #p.name == 0 or #p.name > 100 then errs[#errs + 1] = where .. ".probe.name: must be a string" end
		if p.settle_seconds ~= nil and (type(p.settle_seconds) ~= "number" or p.settle_seconds < 0 or p.settle_seconds > 10) then
			errs[#errs + 1] = where .. ".probe.settle_seconds: must be 0..10"
		end
		for _, side in ipairs({ "accepted_when", "rejected_when" }) do
			local c = ev[side]
			if c == nil then errs[#errs + 1] = where .. "." .. side .. ": required" else
				if check_keys(c, util.set({ "change" }), { "change" }, where .. "." .. side, errs) then
					if not util.set({ "increase", "decrease", "changed", "unchanged" })[c.change] then
						errs[#errs + 1] = where .. "." .. side .. ".change: must be increase|decrease|changed|unchanged"
					end
				end
			end
		end
		if ev.telemetry ~= nil then errs[#errs + 1] = where .. ": telemetry not allowed with observable_state" end
	elseif ev.channel == "qa_telemetry" then
		if not check_keys(ev.telemetry, util.set({ "remote_path", "timeout_seconds" }), { "remote_path", "timeout_seconds" }, where .. ".telemetry", errs) then return end
		local t = ev.telemetry or {}
		local okp, why = check_path(t.remote_path, V.ENDPOINT_ROOTS, false)
		if not okp then errs[#errs + 1] = where .. ".telemetry.remote_path: " .. why end
		if type(t.timeout_seconds) ~= "number" or t.timeout_seconds <= 0 or t.timeout_seconds > 30 then
			errs[#errs + 1] = where .. ".telemetry.timeout_seconds: must be > 0 and <= 30"
		end
		if ev.accepted_when ~= nil or ev.rejected_when ~= nil or ev.probe ~= nil then
			errs[#errs + 1] = where .. ": qa_telemetry takes its outcome from the developer's telemetry message only"
		end
	end
end

local function check_stop(sc, where, errs)
	if sc == nil then return end
	if check_keys(sc, util.set({ "stop_on_error", "stop_on_unexpected_outcome", "stop_on_inconclusive" }), {}, where, errs) then
		for k, v in pairs(sc) do
			if type(v) ~= "boolean" then errs[#errs + 1] = where .. "." .. k .. ": must be boolean" end
		end
	end
end

-- validate(manifest, ctx) -> ok, errors
-- ctx = { now_unix = number }  (required for the expiry check)
function V.validate(m, ctx)
	ctx = ctx or {}
	local errs = {}
	if type(m) ~= "table" then return false, { "manifest: must be a JSON object" } end
	check_keys(m, util.set({ "schema_version", "manifest", "target", "limits", "stop_conditions", "test_cases", "signature" }),
		{ "schema_version", "manifest", "target", "limits", "stop_conditions", "test_cases" }, "manifest", errs)
	if m.schema_version ~= "1.0" then errs[#errs + 1] = "schema_version: must be \"1.0\"" end

	-- identity / approval
	local id = m.manifest
	if type(id) == "table" and check_keys(id, util.set({ "manifest_id", "version", "created_utc", "expires_utc", "approved_by", "approval_reference" }),
		{ "manifest_id", "version", "created_utc", "expires_utc", "approved_by", "approval_reference" }, "manifest.manifest", errs) then
		if type(id.manifest_id) ~= "string" or not string.match(id.manifest_id, "^[%w_%-]+$") or #id.manifest_id > 64 then
			errs[#errs + 1] = "manifest.manifest_id: must match [A-Za-z0-9_-]{1,64}"
		end
		if type(id.version) ~= "string" or not string.match(id.version, "^%d+%.%d+%.%d+$") then errs[#errs + 1] = "manifest.version: must be semver (e.g. 1.0.0)" end
		for _, k in ipairs({ "approved_by", "approval_reference" }) do
			if type(id[k]) ~= "string" or #util.trim(id[k]) < 3 or #id[k] > 200 then errs[#errs + 1] = "manifest." .. k .. ": must be a non-empty string" end
		end
		local created, expires = util.iso_to_unix(id.created_utc), util.iso_to_unix(id.expires_utc)
		if not created then errs[#errs + 1] = "manifest.created_utc: must be ISO-8601 UTC like 2026-10-24T00:00:00Z" end
		if not expires then errs[#errs + 1] = "manifest.expires_utc: must be ISO-8601 UTC like 2026-10-24T00:00:00Z" end
		if created and expires then
			if expires <= created then errs[#errs + 1] = "manifest.expires_utc: must be after created_utc" end
			if ctx.now_unix and expires <= ctx.now_unix then errs[#errs + 1] = "manifest.expires_utc: manifest has expired" end
		end
	elseif type(id) ~= "table" then
		errs[#errs + 1] = "manifest.manifest: must be an object"
	end

	-- 0.3.0 draft gate: a generated draft carries placeholder approval fields and is INVALID until a human edits it.
	local function looks_like_draft(s)
		if type(s) ~= "string" then return false end
		local l = string.lower(s)
		return string.find(l, "draft", 1, true) ~= nil or string.find(l, "replace", 1, true) ~= nil
			or string.find(l, "not approved", 1, true) ~= nil
	end
	if type(id) == "table" then
		if looks_like_draft(id.approved_by) or looks_like_draft(id.approval_reference) then
			errs[#errs + 1] = "manifest.approved_by/approval_reference: this is an UNEDITED DRAFT generated by ShadowScan"
				.. " (placeholders detected); a named approver and a real approval reference are required before it can run"
		end
	end

	-- 0.3.0 optional signature block: the Luau client CANNOT verify Ed25519; it only checks the shape here so a
	-- malformed block fails everywhere. Content verification happens on the PC (test_manifest/validate.py) - see docs/MANIFEST.md.
	if m.signature ~= nil then
		local sig = m.signature
		if not check_keys(sig, util.set({ "alg", "public_key", "value" }), { "alg", "public_key", "value" }, "manifest.signature", errs) then
			-- keys already reported
		else
			if sig.alg ~= "ed25519" then errs[#errs + 1] = "manifest.signature.alg: must be \"ed25519\"" end
			if type(sig.public_key) ~= "string" or #sig.public_key ~= 64 or not string.match(sig.public_key, "^%x+$") then
				errs[#errs + 1] = "manifest.signature.public_key: must be 64 hex characters"
			end
			if type(sig.value) ~= "string" or #sig.value ~= 128 or not string.match(sig.value, "^%x+$") then
				errs[#errs + 1] = "manifest.signature.value: must be 128 hex characters"
			end
		end
	end

	-- target
	local target = m.target
	local mode
	local qa
	if type(target) == "table" and check_keys(target, util.set({ "game_id", "place_ids", "mode", "qa" }), { "game_id", "place_ids", "mode" }, "manifest.target", errs) then
		if not is_int(target.game_id) then errs[#errs + 1] = "target.game_id: must be a positive integer" end
		if type(target.place_ids) ~= "table" or #target.place_ids == 0 or #target.place_ids > V.HARD.MAX_PLACE_IDS then
			errs[#errs + 1] = "target.place_ids: must be a list of 1.." .. V.HARD.MAX_PLACE_IDS .. " integers"
		else
			local seen = {}
			for i, p in ipairs(target.place_ids) do
				if not is_int(p) then errs[#errs + 1] = "target.place_ids[" .. i .. "]: must be a positive integer"
				elseif seen[p] then errs[#errs + 1] = "target.place_ids[" .. i .. "]: duplicate" end
				seen[p] = true
			end
		end
		mode = target.mode
		if not V.MODES[mode] then errs[#errs + 1] = "target.mode: must be production_observation or private_qa" end
		qa = target.qa
		if qa ~= nil and check_keys(qa, util.set({ "require_private_server", "allowed_job_ids", "reset" }), {}, "target.qa", errs) then
			if qa.require_private_server ~= nil and type(qa.require_private_server) ~= "boolean" then errs[#errs + 1] = "target.qa.require_private_server: must be boolean" end
			if qa.allowed_job_ids ~= nil then
				if type(qa.allowed_job_ids) ~= "table" or #qa.allowed_job_ids == 0 or #qa.allowed_job_ids > 20 then
					errs[#errs + 1] = "target.qa.allowed_job_ids: must be a list of 1..20 strings"
				else
					for i, j in ipairs(qa.allowed_job_ids) do
						if type(j) ~= "string" or #j == 0 or #j > 100 then errs[#errs + 1] = "target.qa.allowed_job_ids[" .. i .. "]: must be a non-empty string" end
					end
				end
			end
			if qa.reset ~= nil and check_keys(qa.reset, util.set({ "kind", "instructions" }), { "kind", "instructions" }, "target.qa.reset", errs) then
				if not V.RESET_KINDS[qa.reset.kind] then errs[#errs + 1] = "target.qa.reset.kind: must be manual|server_side_auto" end
				if type(qa.reset.instructions) ~= "string" or #util.trim(qa.reset.instructions) < 10 then
					errs[#errs + 1] = "target.qa.reset.instructions: describe how state is reset (>= 10 chars)"
				end
			end
		end
		if mode == "private_qa" then
			if qa == nil or not (get(qa, "require_private_server") == true or get(qa, "allowed_job_ids") ~= nil) then
				errs[#errs + 1] = "target.qa: private_qa needs require_private_server=true or allowed_job_ids so the tool can verify it is NOT on a public server"
			end
		end
	elseif type(target) ~= "table" then
		errs[#errs + 1] = "manifest.target: must be an object"
	end

	-- limits & stop conditions
	local limits = m.limits
	local total_cap, min_interval = V.HARD.MAX_TOTAL_CALLS, V.HARD.MIN_INTERVAL_SECONDS
	if type(limits) == "table" and check_keys(limits, util.set({ "max_total_calls", "min_interval_seconds", "max_duration_seconds" }),
		{ "max_total_calls", "min_interval_seconds", "max_duration_seconds" }, "manifest.limits", errs) then
		if not is_int(limits.max_total_calls) or limits.max_total_calls > V.HARD.MAX_TOTAL_CALLS then
			errs[#errs + 1] = "limits.max_total_calls: integer 1.." .. V.HARD.MAX_TOTAL_CALLS
		else total_cap = limits.max_total_calls end
		if type(limits.min_interval_seconds) ~= "number" or limits.min_interval_seconds < V.HARD.MIN_INTERVAL_SECONDS or limits.min_interval_seconds > 60 then
			errs[#errs + 1] = "limits.min_interval_seconds: number " .. V.HARD.MIN_INTERVAL_SECONDS .. ".. 60"
		else min_interval = limits.min_interval_seconds end
		if not is_int(limits.max_duration_seconds) or limits.max_duration_seconds > V.HARD.MAX_DURATION_SECONDS then
			errs[#errs + 1] = "limits.max_duration_seconds: integer 1.." .. V.HARD.MAX_DURATION_SECONDS
		end
	elseif type(limits) ~= "table" then
		errs[#errs + 1] = "manifest.limits: must be an object"
	end
	if type(m.stop_conditions) == "table" then
		check_stop(m.stop_conditions, "manifest.stop_conditions", errs)
		for _, k in ipairs({ "stop_on_error", "stop_on_unexpected_outcome" }) do
			if m.stop_conditions[k] == nil then errs[#errs + 1] = "manifest.stop_conditions: missing required key '" .. k .. "'" end
		end
	else
		errs[#errs + 1] = "manifest.stop_conditions: must be an object"
	end

	-- test cases
	local tcs = m.test_cases
	if type(tcs) ~= "table" or (getmetatable(tcs) and getmetatable(tcs).__jsontype == "object") or #tcs == 0 or #tcs > V.HARD.MAX_TEST_CASES then
		errs[#errs + 1] = "test_cases: must be a list of 1.." .. V.HARD.MAX_TEST_CASES .. " test cases"
		return #errs == 0, errs
	end
	local seen_ids, calls_sum = {}, 0
	for i, tc in ipairs(tcs) do
		local w = "test_cases[" .. i .. "]"
		if check_keys(tc, util.set({ "test_id", "title", "endpoint", "test_type", "args", "mutates_state", "read_only_justification",
			"max_calls", "min_interval_seconds", "expected_outcome", "evidence", "confirmable" }),
			{ "test_id", "title", "endpoint", "test_type", "args", "mutates_state", "max_calls", "min_interval_seconds", "expected_outcome", "evidence", "confirmable" }, w, errs) then
			if type(tc.test_id) ~= "string" or not string.match(tc.test_id, "^[%w_%-]+$") or #tc.test_id > 64 then
				errs[#errs + 1] = w .. ".test_id: must match [A-Za-z0-9_-]{1,64}"
			elseif seen_ids[tc.test_id] then errs[#errs + 1] = w .. ".test_id: duplicate '" .. tc.test_id .. "'" end
			seen_ids[tostring(tc.test_id)] = true
			if type(tc.title) ~= "string" or #tc.title == 0 or #tc.title > 200 then errs[#errs + 1] = w .. ".title: must be a non-empty string" end

			local ep = tc.endpoint
			if check_keys(ep, util.set({ "path", "class", "is_canary" }), { "path", "class", "is_canary" }, w .. ".endpoint", errs) then
				local okp, why = check_path(ep.path, V.ENDPOINT_ROOTS, false)
				if not okp then errs[#errs + 1] = w .. ".endpoint.path: " .. why end
				if not V.ENDPOINT_CLASSES[ep.class] then
					errs[#errs + 1] = w .. ".endpoint.class: must be RemoteEvent|RemoteFunction|UnreliableRemoteEvent (ProximityPrompt/ClickDetector active tests are not supported in this version)"
				end
				if type(ep.is_canary) ~= "boolean" then errs[#errs + 1] = w .. ".endpoint.is_canary: must be boolean" end
			end

			if not V.TEST_TYPES[tc.test_type] then errs[#errs + 1] = w .. ".test_type: must be read_only_call|valid_call_baseline|negative_input|rate_limit_probe" end
			if type(tc.args) ~= "table" or is_object(tc.args) and next(tc.args) ~= nil or #tc.args > V.HARD.MAX_ARGS then
				errs[#errs + 1] = w .. ".args: must be a list of at most " .. V.HARD.MAX_ARGS .. " JSON values"
			else
				local aerrs = {}
				check_arg_value(tc.args, w .. ".args", aerrs, {})
				for _, e in ipairs(aerrs) do errs[#errs + 1] = e end
				if not nesting_ok(tc.args, 1) then errs[#errs + 1] = w .. ".args: nesting deeper than " .. V.HARD.MAX_NESTING end
				local okj, enc = pcall(json.encode, tc.args)
				if okj and #enc > V.HARD.MAX_ARGS_JSON_BYTES then errs[#errs + 1] = w .. ".args: larger than " .. V.HARD.MAX_ARGS_JSON_BYTES .. " bytes" end
			end

			if type(tc.mutates_state) ~= "boolean" then errs[#errs + 1] = w .. ".mutates_state: must be boolean" end
			if not is_int(tc.max_calls) or tc.max_calls > V.HARD.MAX_CALLS_PER_TEST then
				errs[#errs + 1] = w .. ".max_calls: integer 1.." .. V.HARD.MAX_CALLS_PER_TEST
			else
				calls_sum += tc.max_calls
				if tc.test_type ~= "rate_limit_probe" and tc.max_calls ~= 1 then errs[#errs + 1] = w .. ".max_calls: only rate_limit_probe may use more than one call" end
			end
			if type(tc.min_interval_seconds) ~= "number" or tc.min_interval_seconds < min_interval or tc.min_interval_seconds > 60 then
				errs[#errs + 1] = w .. ".min_interval_seconds: must be >= the global minimum (" .. tostring(min_interval) .. ") and <= 60"
			end
			if tc.expected_outcome ~= "accepted" and tc.expected_outcome ~= "rejected" then errs[#errs + 1] = w .. ".expected_outcome: must be accepted|rejected" end
			if type(tc.confirmable) ~= "boolean" then errs[#errs + 1] = w .. ".confirmable: must be boolean" end
			check_evidence(tc.evidence, tc, w .. ".evidence", errs)
			if tc.confirmable == true then
				if get(tc.evidence, "channel") == "none" then errs[#errs + 1] = w .. ".confirmable: needs a verifiable evidence channel" end
				if tc.test_type == "rate_limit_probe" then errs[#errs + 1] = w .. ".confirmable: a bounded rate-limit probe can never confirm a vulnerability" end
			end
			if tc.read_only_justification ~= nil and (type(tc.read_only_justification) ~= "string" or #tc.read_only_justification > 500) then
				errs[#errs + 1] = w .. ".read_only_justification: must be a string up to 500 chars"
			end

			-- mode-dependent safety rules
			local just_ok = type(tc.read_only_justification) == "string" and #util.trim(tc.read_only_justification) >= 10
			if tc.test_type == "read_only_call" and tc.mutates_state == true then errs[#errs + 1] = w .. ": read_only_call cannot mutate state" end
			if mode == "production_observation" then
				if tc.mutates_state ~= false then errs[#errs + 1] = w .. ": production_observation allows only non-mutating tests" end
				if not just_ok then errs[#errs + 1] = w .. ".read_only_justification: required (>= 10 chars) in production_observation to document why this call is safe" end
				if (tc.test_type == "negative_input" or tc.test_type == "rate_limit_probe") and get(ep, "is_canary") ~= true then
					errs[#errs + 1] = w .. ": " .. tostring(tc.test_type) .. " in production_observation requires a developer-prepared canary endpoint (is_canary=true)"
				end
			elseif mode == "private_qa" then
				if tc.mutates_state == true then
					local reset = get(qa, "reset")
					if not reset then errs[#errs + 1] = w .. ": mutating test requires target.qa.reset (reset/rollback procedure)" end
				end
			end
		end
	end
	if calls_sum > total_cap then errs[#errs + 1] = "test_cases: sum of max_calls (" .. calls_sum .. ") exceeds limits.max_total_calls (" .. total_cap .. ")" end
	return #errs == 0, errs
end

return V
end
return __require
